(window.GIM_TS=window.GIM_TS||{})["Kiddushin.0"]={"from":0,"a":[["\u0003האשה נקנית\u0004 לבעלה להיות אשתו \u0003בשלש דרכים, וקונה את עצמה,\u0004 כלומר, משתחררת מקשר הנישואין, \u0003בשתי דרכים.\u0004 ומפרטים: \u0003נקנית בכסף, בשטר, ובביאה.\u0004 ולגבי הקנין ש\u0003בכסף\u0004 נחלקו הדעות: \u0003בית שמאי אומרים\u0004 שהוא מתקיים לפחות \u0003בדינר\u0004 או \u0003ב\u0004כל דבר ה\u0003שוה דינר. ובית הלל אומרים:\u0004 גם \u0003בפרוטה\u0004 (מטבע קטנה של נחושת) או \u0003בשוה פרוטה.\u0004 מבררים: \u0003וכמה היא\u0004 (מהו ערכה) של \u0003פרוטה\u0004 על פי בסיס הערך הקבוע של כסף — \u0003אחד משמנה\u0004 (שמינית) \u0003באיסר האיטלקי\u0004 שהוא מטבע קטנה של כסף.","\u0003וקונה\u0004 האשה \u0003את עצמה בגט\u0004 או \u0003במיתת הבעל. היבמה\u0004 אינה \u0003נקנית\u0004 קנין גמור ליבם בכל הדרכים שאשה נקנית, אלא \u0003בביאה\u0004 בלבד, \u0003וקונה\u0004 לשחרר \u0003את עצמה\u0004 מן הקשר ליבם \u0003בחליצה\u0004 או \u0003במיתת היבם.\u0004","שנינו במשנה: \u0003\"האשה נקנית\",\u0004 ושואלים: \u0003מאי שנא הכא\u0004 \u0005[\u0006ב\u0005מה שונה כאן]\u0006 במשנתנו \u0003דתני\u0004 \u0005[ששנה]\u0006 בה \u0003\"האשה נקנית\",\u0004 בלשון קנין \u0003ומאי שנא התם\u0004 \u0005[ומה שונה שם]\u0006 בתחילת הפרק הבא \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003\"האיש מקדש\"\u0004 בלשון קידושין? ומסבירים: במשנתנו שנה התנא לשון קנין \u0003משום דקא בעי למיתני\u0004 \u0005[שרצה\u0006 התנא \u0005לשנות]\u0006 בהמשך קנין \u0003כסף,\u0004","\u0003וכסף מנא לן\u0004 \u0005[מנין לנו]\u0006 שאשה נקנית בו — \u0003גמר\u0004 \u0005[למד]\u0006 מגזירה שווה של לשונות \u0003\"קיחה\" \"קיחה\" משדה עפרון.\u0004 כיצד? — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בענין נישואין \u0003\"כי יקח איש אשה\"\u0004 (דברים כד, א) \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בקנין השדה מעפרון החתי \u0003\"נתתי כסף השדה קח ממני\"\u0004 (בראשית כג, יג) והגזירה השווה מלמדת שכשם שלקיחת שדה עפרון היתה בכסף, גם לקיחת אשה היא בכסף.","\u0003וקיחה\u0004 זו של שדה עפרון \u0003איקרי\u0004 \u0005[נקראת]\u0006 במקרא \u0003\"קנין\", דכתיב\u0004 \u0005[שנאמר]:\u0006 באותו ענין \u0003\"השדה אשר קנה אברהם\"\u0004 (שם כה, י)."],["\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 ראיה שלקיחת שדה בכסף נקראת \"קנין\", מן הכתוב \u0003\"שדות בכסף יקנו\"\u0004 (ירמיה לב, מד). ומשום שרצה לשנות דין קידושי אשה בכסף לכן \u0003תני\u0004 \u0005[שנה]\u0006 והשתמש בלשון \u0003\"האשה נקנית\".\u0004","ושואלים: דבר זה מסביר מדוע במשנתנו נאמר \"האשה נקנית\", ואולם עדיין יש לשאול: \u0003וניתני התם\u0004 \u0005[ונשנה\u0006 גם \u0005שם]\u0006 בפרק הבא \u0003\"האיש קונה\"!\u0004 ומסבירים: \u0003מעיקרא תני לישנא דאורייתא\u0004 \u0005[בתחילה שנה\u0006 במשנה \u0005לשון התורה]\u0006 ובלשון תורה קנין נקרא \"לקיחה\", \u0003ולבסוף\u0004 בפרק הבא \u0003תני לישנא דרבנן\u0004 \u0005[שנה לשון חכמים],\u0006 \u0003ומאי לישנא דרבנן\u0004 \u0005[ומה\u0006 טעמה של \u0005לשון\u0006 זו \u0005של חכמים]\u0006 שקוראים ללקיחת אשה \"קידושין\"? — משום \u0003דאסר לה אכולי עלמא\u0004 \u0005[שאוסר אותה\u0006 בעלה בקידושיה \u0005על כל העולם]\u0006 \u0003כהקדש,\u0004 ולכן משתמשים בלשון \"קידושי\" אשה.","ושואלים שאלה נוספת על ההבדל בנוסח שתי המשניות: \u0003וניתני הכא\u0004 \u0005[ונשנה\u0006 גם \u0005כאן]\u0006 כמו בפרק הבא \u0003\"האיש קונה\"!\u0004 ומדוע שנה \"האשה נקנית\" שהאשה היא נושא המשפט? ומשיבים: \u0003משום דקא בעי למיתנא סיפא\u0004 \u0005[שרצה לשנות\u0006 ב\u0005סוף\u0006 המשנה\u0005]\u0006 \u0003\"וקונה את עצמה\"\u0004 שמדובר \u0003בדידה\u0004 \u0005[בה],\u0006 שהיא נושא המשפט, \u0003תנא נמי רישא בדידה\u0004 \u0005[שנה גם תחילתה בה].\u0006","על כך שואלים: אם משום כך, אפשר היה לשנות הכל בצורה אחרת \u0003וניתני\u0004 \u0005[וישנה]\u0006 \u0003\"האיש קונה ומקנה\"!\u0004 ומשיבים: אי אפשר להשתמש בסוף המשנה בלשון \"מקנה\" \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 בין הדרכים שבהן האשה נקנית גם מקרה של \u0003מיתת הבעל דלאו איהו קא מקני\u0004 \u0005[שלא הוא מקנה]\u0006 אלא \u0003מן שמיא\u0004 \u0005[השמים]\u0006 \u0003הוא דמקני\u0004 \u0005[שמקנים]\u0006 \u0003לה\u0004 את עצמה, ולכן אין מקום לומר באופן כללי שהאיש מקנה מדעתו.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003אי תנא\u0004 \u0005[אילו היה שונה]\u0006 \"האיש \u0003קונה\u0004 את האשה\", \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שיכול לקנותה \u0003אפילו בעל כרחה,\u0004 כפי שמשמע בלשון \"קונה\" שהכל בא מצד הבעל, ואינו צריך לשאול את דעתה, לכן \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003\"האשה נקנית\",\u0004 ללמדנו ש\u0003מדעתה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 יכול הוא לקנותה לאשה\u0003, ואולם\u0004 \u0003שלא מדעתה\u0004 — \u0003לא.\u0004","ועוד שאלה לגבי לשון המשנה: \u0003ומאי איריא דתני\u0004 \u0005[ומה שייך,\u0006 מדוע דווקא, \u0005שנה]\u0006 \u0003\"שלש\u0004 דרכים \u0003\",\u0004 \u0003ליתני\u0004 \u0005[שישנה]\u0006 \u0003\"שלשה\u0004 דרכים \u0003\"!\u0004 ומסבירים: \u0003משום דקא בעי למיתני\u0004 \u0005[שרצה לשנות]\u0006 \u0003\"דרך\"\u0004 (\"שלש דרכים\") \u0003ו\"דרך\" לשון נקבה הוא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והודעת להם את הדרך ילכו בה\"\u0004 (שמות יח, כ).","ומקשים: \u0003ואלא הא דתניא\u0004 \u0005[זו ששנינו]\u0006 \u0003\"בשבעה דרכים בודקין את הזב\", ניתני\u0004 \u0005[שישנה]\u0006 \u0003\"שבע\u0004 דרכים \u0003\"\u0004בלשון נקבה! ומשיבים: \u0003משום דקא בעי למיתני\u0004 \u0005[שרצה לשנות\u0006 שם\u0005]\u0006 \u0003\"דרך\" ואשכחן\u0004 \u0005[ומצאנו]\u0006 ב\u0003דרך דאיקרי\u0004 \u0005[ש\u0006היא \u0005קרויה]\u0006 \u0003לשון זכר, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בדרך אחד יצאו אליך ובשבעה דרכים ינוסו לפניך\"\u0004 (דברים כח, ז). ושואלים: \u0003אי הכי קשו קראי אהדדי\u0004 \u0005[אם כך קשים הכתובים זה על זה],\u0006 שבמקום אחד \"דרך\" הוא לשון זכר ובמקום שני \"דרך\" היא לשון נקבה! ועוד: \u0003וקשיא נמי מתניתין אהדדי\u0004 \u0005[וקשות גם כן המשניות זו על זו],\u0006 שבאחת נקט \"דרך\" בלשון זכר ובשניה בלשון נקבה!","ומתרצים: \u0003קראי אהדדי לא קשיין\u0004 \u0005[הכתובים זה על זה אינם קשים]:\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 בפסוק \"הדרך ילכו בה\" ש\u0003בתורה קאי\u0004 \u0005[עומד,\u0006 עוסק\u0005]\u0006 הכתוב, שהרי \"דרך\" זו דרך התורה היא \u0003ותורה איקרי\u0004 \u0005[נקראת]\u0006 \u0003לשון נקבה דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"תורת ה' תמימה משיבת נפש\"\u0004 (תהלים יט, ח), לכך \u0003כתב לה\u0004 \u0005[אותה],\u0006 את המלה \"דרך\", \u0003בלשון נקבה. התם\u0004 \u0005[שם]\u0006 (\"בדרך אחד יצאו אליך\") ש\u0003במלחמה קאי\u0004 \u0005[\u0006הוא \u0005עומד,\u0006 עוסק\u0005],\u0006 ומכיון ש\u0003דרכו של איש לעשות מלחמה ואין דרכה של אשה לעשות מלחמה\u0004 מתאימה לשון זכר ולכן \u0003כתב לה\u0004 \u0005[אותה]\u0006 את המלה \"דרך\" \u0003בלשון זכר.\u0004","וכן \u0003מתניתין אהדדי לא קשיין\u0004 \u0005[המשניות אינן קשות זו על זו];\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 ש\u0003לגבי אשה קאי\u0004 \u0005[\u0006הוא \u0005עומד,\u0006 עוסק\u0005]\u0006 \u0003קתני לה\u0004 \u0005[שנה אותה],\u0006 את המלה \"דרך\", \u0003בלשון נקבה. התם\u0004 \u0005[שם]\u0006 בבדיקת הזב ש\u0003לגבי איש קאי\u0004 \u0005[\u0006הוא \u0005עומד,\u0006 עוסק\u0005],\u0006 ומדוע באיש דווקא — שכן \u0003דרכו של איש ליבדק\u0004 לענין הזיבה, אם הזיבה אינה נובעת מסיבה אחרת, \u0003ואין דרכה של אשה ליבדק, דהא\u0004 \u0005[שהרי]\u0006 \u0003אשה,\u0004 שלא כבאיש, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003באונס מיטמאה,\u0004 שגם אם יצא ממנה הדם מחמת כל אונס אחר ולא מחמת מחלה הריהי טמאה ואין איפוא מקום לבדיקה בה, ומשום שהוא עוסק באיש לכן \u0003תני\u0004 \u0005[שנה]\u0006 \"דרך\" ב\u0003לשון זכר.\u0004","ושואלים שאלה נוספת על לשון המשנה: כפי שהסברנו \u0003מאי טעמא תני\u0004 \u0005[מה טעם שנה]\u0006 \u0003\"שלש\"\u0004 בלשון נקבה — \u0003משום\u0004 שרצה לשנות \u0003\"דרכים\",\u0004 מדוע לא \u0003ניתני\u0004 \u0005[ישנה]\u0006 לשון \u0003\"דברים\"\u0004 (\"בשלושה דברים אשה נקנית\") \u0003וניתני\u0004 \u0005[ושישנה]\u0006 \u0003\"שלשה\"\u0004 ולא \"שלוש\"! ומשיבים: \u0003משום דקבעי למיתני\u0004 \u0005[שרצה לשנות]\u0006 אחר כך בין אלה גם \u0003ביאה, וביאה איקרי\u0004 \u0005[נקראה]\u0006 בכתוב \u0003\"דרך\", דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ודרך גבר בעלמה כן דרך אשה מנאפת\"\u0004 (משלי ל, יט–כ) לכן אמר \"דרכים\" ולא \"דברים\".","ומקשים: \u0003הא תינח\u0004 \u0005[זה נוח]\u0006 לענין \u0003ביאה\u0004 שנקראה \"דרך\", אבל \u0003כסף ושטר מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי בהם אפשר היה לומר \"דברים\"! ומשיבים: \u0003משום\u0004 שהיה צורך להזכיר איתם \u0003ביאה\u0004 הנקראת \"דרך\", לפיכך השתמש בכולם בלשון \"דרך\".","ומקשים: \u0003ותני תרתי אטו חדא\u0004 \u0005[ו\u0006כי \u0005היה שונה שני\u0006 דברים \u0005בגלל אחד]?\u0006 וכיון שלשון \"דרך\" מתאימה רק למקרה אחד מתוך שלושה, מדוע לא אמר בלשון \"דברים\" מפני האחרים? ומשיבים: \u0003הנך נמי\u0004 \u0005[אלה גם כן]\u0006 \u0003צורך ביאה נינהו\u0004 \u0005[הם]\u0006 שהיא הצד המיוחד בקנין הנישואין, ולכן ראה ענין זה כעיקר.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר: \u0003הא מני\u0004 \u0005[\u0006משנתנו \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' שמעון היא,\u0004 וכפי \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון אומר: מפני מה אמרה תורה \"כי יקח איש אשה\"\u0004 (דברים כב, יג) \u0003ולא כתב \"כי תלקח אשה לאיש\"?\u0004 — \u0003מפני שדרכו של איש לחזר על\u0004 (לחפש אחר) \u0003אשה ואין דרכה של אשה לחזר על איש.\u0004 וטעמו של דבר: \u0003משל לאדם שאבדה לו אבידה מי חוזר על מי?\u0004 הרי \u0003בעל אבידה מחזר על אבידתו\u0004 ולא להיפך. וכיון שהאשה נבראה מצלעו של האדם ואבדה לו, כדרך העולם, ככל בעל אבידה, הוא המחפש את אבידתו. וכיון שכך — כל עיקרם של נישואין (בכל צורה) הוא ענין של \"דרך\", דרכו של עולם, ולכן, אף המשנה נקטה לשון זו.","ושואלים: \u0003ו\u0004אולם \u0003הא דתנן\u0004 \u0005[וזו ששנינו\u0006 במשנה\u0005]\u0006 \u0003\"בשבעה דרכים בודקין את הזב\"\u0004 מדוע שונה כך? \u0003ליתני\u0004 \u0005[שישנה]\u0006 שם \u0003\"דברים\"\u0004 ולא \"דרכים\"! ומשיבים: \u0003התם הא קא משמע לן\u0004 \u0005[שם\u0006 דבר \u0005זה השמיע לנו]:\u0006 \u0003דדרכא דמיכלא יתירא לאתויי\u0004 \u0005[שדרכה של אכילה יתירה להביא]\u0006 \u0003לידי זיבה ודרכא דמישתיא יתירא לאתויי\u0004 \u0005[ודרכה של שתיה יתירה להביא]\u0006 \u0003לידי זיבה\u0004 ולכן מדבר על \"שבעה דרכים\", משום שהם הדרכים המובילות לזיבה.","\u0003ו\u0004שואלים עוד: \u0003הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003אתרוג שוה לאילן בשלשה דרכים, ליתני\u0004 \u0005[שישנה\u0006 שם\u0005]\u0006 \u0003\"\u0004שלושה \u0003דברים\"!\u0004 ומשיבים: \u0003משום דבעינן מתני סיפא\u0004 \u0005[שרצה לשנות\u0006 ב\u0005סוף]\u0006 שהאתרוג שווה \u0003לירק בדרך אחד,\u0004 לכן שנה גם בתחילה לשון \"דרכים\" ולא דברים. ומקשים: \u0003סיפא נמי ניתני\u0004 \u0005[בסוף גם כן שישנה]\u0006 \u0003\"דבר\"\u0004 ולא \"דרך\"!"],["\u0003התם הא קמשמע לן\u0004 \u0005[שם\u0006 דבר \u0005זה השמיע לנו]\u0006 — \u0003דדרכיה\u0004 \u0005[שדרכו]\u0006 של \u0003אתרוג,\u0004 כלומר, דרך גידולו, \u0003כירק, מה ירק דרכו ליגדל על כל מים\u0004 ולא רק ממי גשמים אלא גם בהשקאה, \u0003ובשעת לקיטתו עישורו,\u0004 שלפי זמן לקיטתו מן השדה מעשרים אותו, שאם לקטוהו בשנת מעשר עני, אף על פי שחנט בשנת מעשר שני — הריהו מתעשר מעשר עני, וכן להיפך, \u0003אף אתרוג דרכו ליגדל על כל מים\u0004 ואינו מסתפק במי גשמים, \u0003ובשעת לקיטתו עישורו.\u0004 וכיון שדרך גידולו כירק השתמש בלשון \"דרך\".","ומוסיפים ושואלים: אם אמנם שימוש הלשון תלוי ב\"רגילות\" הטבעית, כדרכו של איש (לחזר), וכגידולו של אתרוג, הרי: \u0003והא דתנן\u0004 \u0005[וזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כוי,\u0004 שהוא בעל חיים מסופק — שלא הכריעו בו חכמים אם הוא מין חיה או מין בהמה — \u0003יש בו דרכים\u0004 שהוא \u0003שוה לחיה, ויש בו דרכים\u0004 שהוא \u0003שוה לבהמה, ויש בו דרכים\u0004 שהוא \u0003שוה לחיה ולבהמה, ויש בו דרכים שאינו שוה לא לחיה ולא לבהמה. ניתני\u0004 \u0005[שישנה]\u0006 שם לשון \u0003\"דברים\"! ותו, הא דתנן\u0004 \u0005[ועוד, זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003זו אחת מן הדרכים ששוו גיטי נשים לשחרורי עבדים, ניתני\u0004 \u0005[שישנה]\u0006 לשון \u0003\"דברים\"!\u0004","\u0003אלא\u0004 יש לדחות את ההסברים שניתנו ולהסביר באופן אחר, שאין שימוש לשון זה תלוי בטבע הענין, אלא \u0003כל היכא דאיכא פלוגתא\u0004 \u0005[\u0006ב\u0005כל מקום שיש חילוק\u0006 בדבר\u0005]\u0006 \u0003תני\u0004 \u0005[\u0006הוא \u0005שונה]\u0006 לשון \u0003\"דרכים\",\u0004 כדרך, שיש בה כיוונים שונים, \u0003וכל היכא דליכא פלוגתא\u0004 \u0005[ו\u0006ב\u0005כל מקום שאין חילוק]\u0006 \u0003תני\u0004 \u0005[שונה]\u0006 לשון \u0003\"דברים\".\u0004 ומעירים: \u0003דיקא נמי דקתני סיפא\u0004 \u0005[מדויק גם כן\u0006 כתירוץ זה ממה \u0005ששנינו בסוף]\u0006 אותה משנה, \u0003ר' אליעזר אומר: אתרוג שוה לאילן לכל דבר,\u0004 ומשמע שבמקום שאין בו חילוקים והבדלים משתמש בביטוי \"דבר\". ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","ועוד בבירור ובדקדוק לשון המשנה: \u0003מניינא דרישא למעוטי מאי\u0004 \u0005[המנין שבראש\u0006 המשנה \"אשה נקנית בשלוש דרכים\" \u0005למעט\u0006 את \u0005מה],\u0006 שהרי מנין זה בא ללמדנו שאין אשה נקנית בדרך אחרת, ומה היא אותה דרך שבה אין האשה נקנית? וכן \u0003מניינא דסיפא למעוטי מאי\u0004 \u0005[\u0006ו\u0005המנין שבסוף,\u0006 שקונה את עצמה בשתי דרכים \u0005למעט\u0006 את \u0005מה\u0006 הוא בא\u0005]?\u0006","ומסבירים: \u0003מניינא דרישא\u0004 \u0005[המנין שבראש\u0006 המשנה\u0005]\u0006 בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003חופה,\u0004 לומר שחופה כשלעצמה אינה דרך של קידושין ואין האשה נקנית בכך. ושואלים: \u0003ולרב הונא,\u0004 ש\u0003אמר: חופה קונה\u0004 באשה, שהיא עצמה דרך של קידושין \u0003מקל וחומר,\u0004 כמבואר להלן (קידושין דף ה,א), אם כן מנין זה \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה\u0006 הוא בא\u0005]?\u0006","ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 קנין \u0003חליפין,\u0004 שאף שמתקדשת בנתינת כסף או שווה כסף, אינה מתקדשת אם היא מקבלת דבר אחר כחליפין. ומדוע נצרך מיעוט זה, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וגמר\u0004 \u0005[ולמד]\u0006 קנין אשה בגזירה שווה \u0003\"קיחה\" \"קיחה\" משדה עפרון\u0004 (ראה לעיל קידושין ב,א), הייתי אומר: \u0003מה שדה מקניא\u0004 \u0005[נקנה]\u0006 \u0003בחליפין, אף אשה נמי מקניא\u0004 \u0005[גם כן נקנית]\u0006 \u0003בחליפין,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 התנא שאין הדבר כן.","על כך שואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור כך\u0006 הוא \u0005גם כן],\u0006 ותהא אשה נקנית גם בחליפין! ומשיבים: אי אפשר לומר שאשה נקנית בחליפין, כי קנייני \u0003חליפין איתנהו\u0004 \u0005[ישנם]\u0006 גם כשהדבר שקונים בו הוא \u0003פחות משוה פרוטה, ואשה בפחות משוה פרוטה\u0004"],["\u0003לא מקניא נפשה\u0004 \u0005[אינה מקנה את עצמה].\u0006","\u0003מניינא דסיפא למעוטי מאי\u0004 \u0005[המניין שבסוף\u0006 המשנה \"וקונה את עצמה בשתי דרכים\" \u0005למעט\u0006 את \u0005מה\u0006 בא\u0005]\u0006 — \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003חליצה,\u0004 שאין אשה קונה את עצמה מבעלה על ידי חליצה. כי בלי המיעוט \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 הלכה זו \u0003בקל וחומר מיבמה,\u0004 וכך נאמר: \u0003מה יבמה שאינה יוצאה\u0004 מן היבם \u0003בגט\u0004 — על כל פנים \u0003יוצאה\u0004 ממנו \u0003בחליצה, זו\u0004 סתם אשה \u0003שיוצאה\u0004 מבעלה \u0003בגט, אינו דין שיוצאה\u0004 ממנו \u0003בחליצה!\u0004 — על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 התנא שסתם אשה הנשואה לאיש אינה יוצאה ממנו בחליצה.","ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור\u0006 ש\u0005כך\u0006 הוא \u0005גם כן]\u0006 ותצא אשה בחליצה! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי גירושי אשה \u0003\"ספר כריתת\"\u0004 (דברים כד, ג), ללמדנו: \u0003ספר,\u0004 כלומר, גט \u0003כורתה\u0004 מבעלה, \u0003ואין דבר אחר כורתה.\u0004","שנינו במשנה שהאשה נקנית \u0003בכסף.\u0004 ושואלים: \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 שהאשה נקנית בכסף? \u0003ותו הא דתנן\u0004 \u0005[ועוד, זו ששנינו]\u0006 במשנה אחרת: \u0003האב זכאי בבתו בקדושיה בכסף בשטר ובביאה, מנלן דמיקניא\u0004 \u0005[מנין לנו ש\u0006היא \u0005נקנית]\u0006 לבעלה \u0003בכסף\u0004 \u0003ו\u0004ש\u0003כסף\u0004 זה \u0003דאבוה\u0004 \u0005[של אביה]\u0006 \u0003הוא?\u0004","\u0003אמר רב יהודה אמר רב: דאמר קרא\u0004 \u0005[שאמר הכתוב]\u0006 לגבי אמה העבריה, שאם אין אדוניה מקיים אחד משלושת החיובים שלו כלפיה — \u0003\"ויצאה חנם אין כסף\"\u0004 (שמות כא, יא), ומייתור לשון המקרא \"אין כסף\" אנו מדייקים: \u0003אין כסף לאדון זה,\u0004 כלומר, במקרה זה האדון שיוצאת ממנו מפסיד את הכסף ששילם בעדה, \u0003אבל\u0004 לעומת זאת \u0003יש כסף לאדון אחר\u0004 כאשר יוצאת מרשותו, \u0003ומאן ניהו\u0004 \u0005[ומי הוא]\u0006 האדון האחר שיכול למסור אותה ולקבל כסף בעדה — ה\u0003אב.\u0004","ומקשים: \u0003ואימא לדידה\u0004 \u0005[ואמור\u0006 שהכסף הזה יהיה \u0005שלה]!\u0006 ודוחים: \u0003הכי השתא\u0004 \u0005[איך אפשר]\u0006 לומר כך, הלא \u0003אביה מקבל קידושיה,\u0004 שהוא המשיא אותה לבעלה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"את בתי נתתי לאיש הזה\"\u0004 (דברים כב, טז), \u0003ואיהי שקלה כספא\u0004 \u0005[והיא נוטלת\u0006 את \u0005הכסף]?!\u0006 שכיון שהוא הנותן אותה לאשה, הרי בוודאי הוא גם המקבל את הכסף.","ושואלים: \u0003ואימא הני מילי\u0004 \u0005[ואמור\u0006 ש\u0005דברים אלה]\u0006 אמורים כשהיא \u0003קטנה דלית לה יד\u0004 \u0005[שאין לה יד,\u0006 כוח\u0005]\u0006 \u0003לקבל קידושין\u0004 שכיון שאינה בת דעת, ממילא אין ביכולתה להיות בעלת כוח משפטי (\"יד\") לקבל קידושין, \u0003אבל נערה דאית\u0004 \u0005[שיש]\u0006 \u0003לה יד לקבל קידושין,\u0004 שהרי כבר עברה את שנתה השתים עשרה והיא נחשבת כגדולה, אם כן \u0003תקדיש איהי נפשה ותשקול כספא\u0004 \u0005[\u0006ש\u0005תקדש היא\u0006 את \u0005עצמה ותיטול\u0006 את \u0005הכסף]!\u0006 ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"בנעריה בית אביה\"\u0004 (במדבר ל, יז) ללמדנו: \u0003כל שבח נעורים\u0004 שמשביחה (שמרויחה) הנערה בבית אביה — \u0003לאביה\u0004 הוא.","ומקשים: \u0003ואלא הא דאמר\u0004 \u0005[זו שאמר]\u0006 \u0003רב הונא אמר רב: מנין שמעשה הבת,\u0004 הכסף שהיא מרויחה בעבודתה, שייך \u0003לאב\u0004 — \u0003שנאמר: \"וכי ימכר איש את בתו לאמה\"\u0004 (שמות כא, ז), ולמדים מההיקש של בת לאמה: \u0003מה אמה מעשה ידיה לרבה\u0004 (בעליה, האדון) \u0003אף בת נמי\u0004 \u0005[גם כן]\u0006 \u0003מעשה ידיה לאביה,\u0004 שהרי כשהוא מוכרה הוא יכול לתת לקונה רק זכות שהיתה בידו. ויש לשאול: למה נזקק רב הונא ללימוד זה? \u0003תיפוק ליה\u0004 \u0005[תצא,\u0006 תלמד, \u0005לו]\u0006 גם הלכה זו \u0003מ\u0004מה שנאמר \u0003\"בנעריה בית אביה\",\u0004 שכל שבח נעורים — לאביה!","\u0003אלא\u0004 מדוע לא אמר כן רב הונא בשם רב — משום שהוא סבור כי פסוק זה \u0003בהפרת נדרים הוא דכתיב\u0004 \u0005[שנאמר],\u0006 ולא בדיני קניינים. אם כן \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 לעניננו נאמר: \u0003בהפרת נדרים הוא דכתיב\u0004 \u0005[שנאמר]\u0006 ולא בענין אחר. \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003נילף מיניה\u0004 \u0005[נלמד\u0006 דבר זה \u0005ממנו],\u0006 מדין הפרת נדרים, שכמו שיש כוח לאב להפר נדרי בתו בעודה נערה, כך יש לו זכות לגבי ממונה — הרי כלל בידינו: \u0003ממונא מאיסורא לא ילפינן\u0004 \u0005[\u0006דין של \u0005ממון מ\u0006דין של \u0005איסור אין אנו למדים].\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003נילף מקנסא\u0004 \u0005[נלמד\u0006 דבר זה \u0005מקנס],\u0006 שהרי מפורש בתורה שהקנס שמשלם האונס את הנערה ניתן לאב, אולם גם כאן יש כלל: \u0003ממונא מקנסא לא ילפינן\u0004 \u0005[ממון מקנס אין אנו למדים],\u0006 שהקנס היא הלכה מיוחדת לעצמה, ואין ללמוד ממנה לענין זכויות ממוניות רגילות.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003נילף\u0004 \u0005[נלמד]\u0006 דבר זה \u0003מ\u0004תשלומי \u0003בושת ופגם\u0004 של נערה שנאנסה שגם הם ניתנים לאב, גם כאן יש לחלק: שכן \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003בושת ופגם דאבוה\u0004 \u0005[שאביה]\u0006 \u0003שייך בגוייהו\u0004 \u0005[בהם],\u0006 שהרי גם בבושת וגם בפגם הנובע מחמת האונס יש בושת ופגם למשפחה כולה ולאב בפרט, ואין ללמוד מכאן לגבי דברים שאין לאב שייכות בהם.","\u0003אלא\u0004 על כרחנו למדים אנו דין זה שכסף קידושי הנערה לאביה מהדגשת הכתוב \"ויצאה חנם אין כסף\" וכפי שדייקנו לעיל. ולענין שהקשינו: מדוע לא נדייק שיהא הכסף שלה, יש לתרץ ולומר כך: \u0003מסתברא דכי קא\u0004 \u0005[מסתבר שכאשר]\u0006 \u0003ממעט\u0004 הכתוב שאין כסף לאדון זה אבל יש כסף לאדון אחר,"],["\u0003יציאה דכוותה קא\u0004 \u0005[שכמותה הוא]\u0006 \u0003ממעט,\u0004 שאף שביציאתה מאדון זה (בעליה) אין לו כסף, הרי ביציאתה מאדון אחר (האב) יש לו כסף.","ומקשים: \u0003והא לא דמיא האי יציאה להאי יציאה\u0004 \u0005[והרי אינה דומה יציאה זו ליציאה זו],\u0006 כי \u0003התם נפקא\u0004 \u0005[שם,\u0006 בשיחרורה, \u0005יצאה]\u0006 \u0003לה מרשות\u0004 ה\u0003אדון לגמרי\u0004 ואין לה עוד כל קשר עימו, \u0003והכא אכתי מיחסרא\u0004 \u0005[וכאן עדיין מחוסרת\u0006 היא\u0005]\u0006 \u0003מסירה לחופה\u0004 ועד אז לא יצאה מרשות האב! ומשיבים: בכל זאת יש דמיון בין שתי היציאות, שכן \u0003בהפרת נדרים מיהא נפקא לה מרשותיה\u0004 \u0005[על כל פנים יצאה לה מרשותו\u0006 של אביה\u0005].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003נערה המאורסה אביה ובעלה מפירין נדריה\u0004 ואין האב מפר לבדו.","ושואלים מצד אחר: \u0003והאי\u0004 \u0005[ו\u0006כי \u0005זה]\u0006 הכתוב \u0003\"ויצאה חנם\"\u0004 (שמות כא, יא) \u0003להכי הוא דאתא\u0004 \u0005[לכך,\u0006 לדבר זה \u0005הוא שבא]\u0006 ללמדנו? \u0003הא מבעי ליה\u0004 \u0005[הרי צריך אותו]\u0006 \u0003לכדתניא\u0004 \u0005[למה ששנינו\u0006 בברייתא\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"ויצאה חנם\"\u0004 — \u0003אלו ימי בגרות\u0004 שאמה עבריה יוצאת מרשות האדון בהגיעה לבגרות, \u0003\"אין כסף\"\u0004 — \u0003אלו ימי נערות,\u0004 שבהגיעה לגיל הנערות יוצאת מרשותו.","\u0003אמר רבינא: אם כן\u0004 שרק לשם לימוד זה בא הפסוק, \u0003לימא קרא\u0004 \u0005[יאמר הכתוב]\u0006 \u0003\"אן כסף\",\u0004 בכתיב חסר, \u0003מאי\u0004 \u0005[מה]\u0006 משמעות הכתוב המלא, ביו\"ד, \u0003\"אין כסף\"\u0004 — הרי זה בא להדגיש וללמדנו דבר נוסף: \u0003אין כסף לאדון זה אבל יש כסף לאדון אחר, ומאן ניהו\u0004 \u0005[ומי הוא\u0006 זה\u0005]\u0006 — \u0003ה\u0004\u0003אב,\u0004 שלו יש זכות בכסף כאשר בתו יוצאת מרשותו כשמתקדשת.","ומסבירים: \u0003וממאי דדרשינן הכי\u0004 \u0005[וממה,\u0006 מנין, \u0005שאנו דורשים כך]\u0006 לומר שהמלה \"אין\" בכתיב מלא מלמדת שיש כאן הדגשה מיוחדת — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 לענין בת כהן שנישאה לישראל ונתאלמנה או נתגרשה: על מה שנאמר \u0003\"וזרע אין לה\u0004 ושבה אל בית אביה כנעוריה מלחם אביה תאכל\u0003\"\u0004 (ויקרא כב, יג), שאם אין לה זרע מבעלה הישראלי מותרת לחזור ולאכול תרומה, דורשים:","\u0003אין לי אלא זרעה\u0004 ממש, \u0003זרע זרעה מנין\u0004 שאף הוא בכלל זה? — \u0003תלמוד לומר: \"זרע אין לה\"\u0004 — \u0003עיין לה,\u0004 כלומר, חפש אחר זרע המתייחס אחריה. ועוד אמרו: \u0003אין לי אלא זרע כשר, זרע פסול\u0004 (כגון ממזר) \u0003מנין\u0004 שאף הוא נחשב כזרע? — \u0003תלמוד לומר: \"זרע אין לה\",\u0004 וכוונתו — \u0003עיין לה\u0004 כמבואר.","ועל הלימוד האחרון שואלים: \u0003והא אפיקתיה\u0004 \u0005[והרי הוצאת אותו],\u0006 את הלימוד הזה, \u0003ל\u0004ענין \u0003זרע זרעה!\u0004 ומשיבים: באמת \u0003זרע זרעה לא איצטריך קרא\u0004 \u0005[הוצרך\u0006 ל\u0005כתוב\u0006 מיוחד\u0005]\u0006 שילמדנו דבר זה, כי כלל ידוע לנו ש\u0003בני בנים הרי הן\u0004 נחשבים \u0003כבנים,\u0004 ולכן \u0003כי איצטריך קרא\u0004 \u0005[כאשר הוצרך הכתוב]\u0006 שממנו דרשנו \"עיין לה\" — הרי זה \u0003ל\u0004ענין \u0003זרע פסול.\u0004","ושואלים: \u0003ותנא גופיה מנליה דדריש הכי\u0004 \u0005[והתנא עצמו מנין לו ש\u0006הוא \u0005דורש כך]\u0006 את המלה \"אין\" לשון \"עיין\"? ומשיבים: \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"מאן בלעם\"\u0004 (במדבר כב, יד) \u0003ו\u0004כן נאמר \u0003\"מאן יבמי\"\u0004 (דברים כה, ז) ש\u0003לא כתיב בהו\u0004 \u0005[נאמר בהם]\u0006 \u0003יו\"ד\u0004 שמכאן משמע שהמלה \"אן\" עצמה היא לשון שלילה. \u0003והכא כתיב ביה\u0004 \u0005[וכאן נאמר בו]\u0006 \u0003יו\"ד\u0004 (\"אין\"), \u0003שמע מינה לדרשא\u0004 \u0005[למד מכאן\u0006 ש\u0005לדרשה]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 ללמוד מכאן גם לשון \"עיין\".","ומעירים: \u0003ואיצטריך למכתב\u0004 \u0005[והוצרך\u0006 הכתוב \u0005לכתוב]\u0006 פסוק המלמד ש\u0003קידושיה לאביה, ואיצטריך למכתב\u0004 \u0005[והוצרך לכתוב]\u0006 גם פסוק אחר המלמד ש\u0003מעשה ידיה לאביה\u0004 ואין ללמוד אחד מהשני; \u0003דאי כתב רחמנא\u0004 \u0005[שאילו היתה כותבת התורה]\u0006 רק ש\u0003קידושיה לאביה, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שהדין כן \u0003משום\u0004 ש\u0003לא טרחא בהו\u0004 \u0005[טרחה בהם]\u0006 להשיגם ולכן הם לאביה, \u0003אבל מעשה ידיה דקא טרחא בהו אימא דידה הוו\u0004 \u0005[שטרחה\u0006 ועמלה \u0005בהם אמור\u0006 ש\u0005שלה הם],\u0006 לכן צריך לכתוב שאף מעשה ידיה לאביה.","\u0003ו\u0004להיפך: \u0003אי אשמעינן\u0004 \u0005[אילו היה משמיע לנו]\u0006 הכתוב רק לענין \u0003מעשה ידיה\u0004 היינו אומרים שהם שייכים לאב משום \u0003דקא מתזנא מיניה\u0004 \u0005[שהיא,\u0006 הבת, \u0005ניזונת ממנו],\u0006 מנכסיו של האב, \u0003אבל קידושיה דמעלמא קאתי\u0004 \u0005[שמן העולם,\u0006 ממקום אחר, \u0005באים הם]\u0006 \u0003לה אימא דידה הוו\u0004 \u0005[אמור\u0006 ש\u0005שלה הם],\u0006 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני הדברים.","\u0003גופא,\u0004 לגופה של הברייתא שהבאנו בענין אמה העבריה: \u0003\"ויצאה חנם\"\u0004 שנאמר בכתוב — \u0003אלו ימי בגרות,\u0004 שבהגיעה לבגרות הריהי יוצאת מרשות האדון, \u0003\"אין כסף\"\u0004 — \u0003אלו ימי נערות.\u0004 ושואלים: \u0003ולכתוב רחמנא\u0004 \u0005[ושתכתוב התורה]\u0006 שיוצאת כשמגיעה ל\u0003נערות, ולא בעי\u0004 \u0005[יצטרך]\u0006 לומר שיוצאת ב\u0003בגרות,\u0004 שהרי אם בנערות יוצאה — בבגרות לא כל שכן!","\u0003אמר רבה: בא זה ולמד על זה,\u0004 שמאחר שלא נאמר במפורש שמדובר ביציאה בסימני נערות, לכן אילו היה רק כתוב אחד, היינו למדים ממנו על סימני בגרות בלבד, וסימני נערות יודעים אנו רק מפני הכפילות שבפסוק.","\u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 בלימוד לגבי \u0003תושב ושכיר. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב בענין אכילת תרומה נאמר: \"תושב כהן ושכיר לא יאכל קודש\" (ויקרא כב, י): \u0003\"תושב\"\u0004 — \u0003זה\u0004 עבד עברי ה\u0003קנוי קנין עולם\u0004 (עבד נרצע), \u0003\"שכיר\"\u0004 — \u0003זה\u0004 עבד ה\u0003קנוי קנין שנים\u0004 (שש שנים).","ושואלים במדרש ההלכה: \u0003יאמר תושב ולא יאמר שכיר, ואני אומר:\u0004 אם זה שהוא \u0003קנוי קנין עולם אינו אוכל\u0004 בתרומה של בעליו הכהן, משום שאינו נחשב כרכושו, זה שהוא \u0003קנוי קנין שנים לא כל שכן\u0004 שאינו אוכל?","ומשיבים: \u0003אילו\u0004 היה נאמר \u0003כן, הייתי אומר: \"תושב\"\u0004 — \u0003זה קנוי קנין שנים,\u0004 שלא היינו מבינים את משמעות המלה לעצמה. \u0003אבל קנוי קנין עולם\u0004 — \u0003אוכל.\u0004 ולכן \u0003בא שכיר\u0004 (שהוא הקנוי לזמן מוגבל) \u0003ולימד על\u0004 משמעות המלה \u0003תושב,\u0004 ומכאן אנו יודעים \u0003שאף על פי שקנוי קנין עולם\u0004 — \u0003אינו אוכל,\u0004 וכך גם למדים מן הכפילות בכתוב לענין נערות ובגרות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מי דמי\u0004 \u0005[האם דומים]\u0006 הדברים? \u0003התם\u0004 \u0005[שם]\u0006 התושב והשכיר \u0003תרי גופי נינהו\u0004 \u0005[שני גופים הם]\u0006 \u0003דכי נמי כתב רחמנא\u0004 \u0005[שגם אם היתה כותבת התורה]\u0006 במפורש \u0003תושב נרצע לא יאכל\u0004 בתרומה שאז היתה משמעות הדברים ברורה לגמרי \u0003והדר כתב אידך\u0004 \u0005[ואחר כך היה כותב את האחר]\u0006 קנין שנים, אף שהוא מיותר שהרי קל וחומר הוא, לא היה בכך קושי חמור, כי אמנם \u0003הוה\u0004 \u0005[הרי\u0006 נמצא\u0005]\u0006 ה\u0003שכיר מילתא דאתיא\u0004 \u0005[דבר שבא,\u0006 נלמד\u0005]\u0006 \u0003בקל וחומר,\u0004 שאינו צריך להכתב, \u0003ו\u0004בכל זאת אין זה קשה כי כלל הוא: \u0003מילתא דאתיא בקל וחומר טרח וכתב לה קרא\u0004 \u0005[דבר הבא,\u0006 הנלמד, \u0005בקל וחומר\u0006 לעיתים \u0005טורח וכותב אותו המקרא]\u0006 ואין זה נחשב לייתור.","\u0003אלא הכא\u0004 — \u0003חד גופא היא\u0004 \u0005[כאן, גוף אחד הוא]\u0006 אותה שפחה \u0003כי נפקא\u0004 \u0005[כאשר\u0006 היא \u0005יוצאה]\u0006 \u0003לה בנערות,\u0004 בזמן \u0003בגרות מאי בעיא גביה\u0004 \u0005[מה צריכה\u0006 היא להיות עוד \u0005אצלו]?\u0006 ואין טעם לומר שתצא בבגרות.","\u0003אלא אמר אביי:\u0004 יש לדחות את ההסבר הקודם שבא כתוב אחד ולימד על רעהו, ו\u0003לא נצרכה\u0004 הלכה זו ש\"ויצאה חינם\" בבגרות \u0003אלא לבגר\u0004 (בגרות) \u0003דאילונית.\u0004 שהאיילונית אינה מביאה כלל סימני נערות (שתי שערות), ואינה מגיעה איפוא לכלל נערה, אלא שבהגיעה לגיל עשרים היא נחשבת מיד בוגרת.","ואילו לא היתה מלמדת אותנו התורה שיוצאה גם בבגרות \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]:\u0006 דווקא \u0003בנערות תיפוק\u0004 \u0005[תצא]\u0006 האמה, אולם \u0003בבגרות\u0004 בלבד \u0003לא תיפוק\u0004 \u0005[תצא].\u0006 וכיון שלאיילונית אין נערות על כן לא תצא לעולם, לכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הכתוב שיש גם יציאה בבגרות לבד.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003מר בר רב אשי: ולאו\u0004 \u0005[ו\u0006האם \u0005לא]\u0006 \u0003קל וחומר הוא? ומה סימנין\u0004 של נערות \u0003שאין מוציאין\u0004 את הנערה \u0003מרשות\u0004 ה\u0003אב\u0004 לגמרי ועדיין יכול הוא לקדשה, בכל זאת \u0003מוציאין\u0004 אותה \u0003מרשות אדון, בגרות שמוציאה\u0004 אותה לגמרי \u0003מרשות אב\u0004 — \u0003אינו דין שמוציאה\u0004 אותה \u0003מרשות\u0004 ה\u0003אדון?\u0004 ואם כן מן הסברה נדע שיוצאה בבגרות, ואין צורך בפסוק מיוחד לצורך זה.","\u0003אלא אמר מר בר רב אשי: לא נצרכה\u0004 הלכה זו \u0003אלא לעיקר זבינא\u0004 \u0005[המכירה]\u0006 של \u0003אילונית\u0004 לאמה. שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כך: זו \u0003דאתיא\u0004 \u0005[שמביאה]\u0006 \u0003סימני נערות\u0004 — \u0003הוי זבינא\u0004 \u0005[יש\u0006 בה \u0005מכירה],\u0006 וזו \u0003דלא אתיא\u0004 \u0005[שאין מביאה]\u0006 \u0003סימני נערות לא הוי זבינה זבינא\u0004 \u0005[אין מכירתה מכירה]\u0006 משום שאי אפשר לקיים בה את כל האמור בכתוב, שהרי אין לה שחרור בזמן נערות."],["על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כפל הכתוב \u0003\"ויצאה חנם\u0004 אין כסף\u0003\"\u0004 (שמות כא, יא) שאף איילונית נמכרת לאמה ויוצאת בבגרות.","ושואלים: \u0003ולמר בר רב אשי\u0004 ש\u0003אמר,\u0004 שהקשה קודם: \u0003ולאו\u0004 \u0005[ו\u0006האם \u0005לא]\u0006 \u0003קל וחומר הוא\u0004 ואין צורך בכתוב הנוסף ללמדנו שאיילונית יוצאת בבגרות — הלא אין זה בעצם קושי, \u0003הא אמרינן\u0004 \u0005[\u0006ש\u0005הרי\u0006 כבר \u0005אמרנו]:\u0006 \u0003מילתא דאתיא\u0004 \u0005[דבר הבא,\u0006 הנלמד\u0005]\u0006 \u0003בקל וחומר\u0004 לפעמים \u0003טרח וכתב לה קרא\u0004 \u0005[אותו הכתוב],\u0006 משמע שאף שאפשר ללמוד את הדבר מקל וחומר, מכל מקום נכתב! ומשיבים: \u0003הני מילי היכא דליכא לשנויי\u0004 \u0005[דברים אלה\u0006 אמורים דווקא במקום \u0005שאין\u0006 כל דרך \u0005לתרץ]\u0006 ולהסביר מפני מה נכתב דבר שאפשר ללמדו בקל וחומר, \u0003אבל היכא דאיכא לשנויי\u0004 \u0005[במקום שאפשר לתרץ]\u0006 — \u0003משנינן\u0004 \u0005[מתרצים].\u0006","ומעירים: \u0003ותנא מייתי לה מהכא\u0004 \u0005[והתנא מביא,\u0006 לומד \u0005אותה מכאן],\u0006 שמביא מקור אחר לקידושי אשה בכסף, ולומד שאר קנייני האשה בדרך אחרת. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר \u0003\"כי יקח איש אשה ובעלה והיה אם לא תמצא חן בעיניו כי מצא בה\u0004 ערות דבר וגו'\u0003\"\u0004 (דברים כד, א), ואמרו חכמים: \u0003אין קיחה אלא בכסף. וכן הוא אומר: \"נתתי כסף השדה קח ממני\"\u0004 (בראשית כג, יג).","\u0003ו\u0004שואלים: הלא אין צורך כלל בלימוד אחר, ש\u0003הלא דין\u0004 (קל וחומר) \u0003הוא: ומה אמה העב\u0004 \u0003ריה שאינה נקנית\u0004 להיות אמה \u0003בביאה\u0004 — \u0003נקנית בכסף, זו,\u0004 סתם אשה, \u0003שנקנית\u0004 לאישות \u0003בביאה\u0004 — \u0003אינו דין שתקנה בכסף?\u0004","ואולם קל וחומר זה אפשר לדחותו: \u0003יבמה תוכיח, שנקנית\u0004 ליבם דווקא \u0003בביאה, ו\u0004אף על פי כן \u0003אינה נקנית בכסף!\u0004 ויש לדחות את הדחיה ולומר: \u0003מה ליבמה\u0004 — \u0003שכן אין נקנית בשטר, תאמר בזו,\u0004 בסתם אשה \u0003שנקנית בשטר,\u0004 ומסתבר שיש בה גם קנין בכסף!","\u0003תלמוד לומר: \"כי יקח איש\u0004 אשה \u0003\".\u0004 ושואלים אם כן: \u0003הא למה לי קרא\u0004 \u0005[זה למה לו כתוב]\u0006 לשם כך \u0003הא אתיא לה\u0004 \u0005[הרי\u0006 כבר \u0005בא,\u0006 נלמד \u0005לו]\u0006 הלימוד הזה מקל וחומר. ואף שניסינו לדחותו, הרי הוכחנו שיש אפשרות לקיימו! \u0003אמר רב אשי: משום דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]\u0006 \u0003מעיקרא דדינא פירכא\u0004 \u0005[מעיקר הדין\u0006 יש בו \u0005פירכא,\u0006 טעות\u0005];\u0006","\u0003מהיכא קא מייתית לה\u0004 \u0005[מהיכן אתה מביא,\u0006 למד \u0005אותה]\u0006 את ההוכחה לקנין כסף — מקל וחומר \u0003מאמה העבריה,\u0004 ואולם עדיין יש לפרוך \u0003מה לאמה העבריה שכן יוצאה\u0004 (משתחררת) \u0003בכסף,\u0004 ולכן גם נקנית בכסף, \u0003תאמר בזו,\u0004 באשת איש, \u0003שאינה יוצאה\u0004 (מתגרשת) \u0003בכסף.\u0004 וכיון שפרכנו את ההוכחה, יש צורך להזדקק לראיה מן הכתוב כפי שאמרה הברייתא: \u0003תלמוד לומר \"כי יקח איש\".\u0004","ולאחר שהבאנו מקור נוסף לקידושי כסף מעירים: \u0003ואיצטריך למיכתב\u0004 \u0005[וצריך\u0006 היה \u0005לכתוב]\u0006 \u0003\"ויצאה חנם\"\u0004 באמה עבריה, \u0003ואיצטריך למיכתב\u0004 \u0005[וצריך\u0006 היה \u0005לכתוב]\u0006 גם \u0003\"כי יקח איש\u0004 אשה \u0003\".\u0004 \u0003דאי כתב רחמנא\u0004 \u0005[שאילו כתבה התורה]\u0006 רק \u0003\"כי יקח\" הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 בכל מקרה \u0003קידושין דיהב\u0004 \u0005[שנותן]\u0006 \u0003לה בעל\u0004 — \u0003דידה הוו\u0004 \u0005[שלה הם],\u0006 ולכן \u0003כתב רחמנא\u0004 \u0005[כתבה תור\u0006 \u0005ה]\u0006 \u0003\"ויצאה חנם\"\u0004 ללמד שהאב זוכה בכסף קידושי בתו שאינה בוגרת.","\u0003ו\u0004להיפך, \u0003אי כתב רחמנא\u0004 \u0005[אילו כתבה התורה]\u0006 רק \u0003\"ויצאה חנם\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003היכא דיהבה ליה איהי לדידיה וקידשתו\u0004 \u0005[במקום שנתנה היא לו\u0006 כסף \u0005וקידשה אותו]\u0006 \u0003הוו קידושי\u0004 \u0005[הרי הם קידושין]\u0006 לכן \u0003כתב רחמנא\u0004 \u0005[כתבה תורה]\u0006 \u0003\"כי יקח\"\u0004 — \u0003ולא כי תקח,\u0004 שרק האיש יכול לקדש אשה ולא להיפך.","ועוד ממשיכה הברייתא: מה שנאמר \u0003\"ובעלה\" מלמד ש\u0004האשה \u0003נקנית בביאה.\u0004 ולכאורה מה צורך בפסוק \u0003והלא דין\u0004 (קל וחומר) \u0003הוא: ומה יבמה שאין נקנית בכסף\u0004 — \u0003נקנית בביאה, זו,\u0004 אשה סתם, \u0003שנקנית בכסף\u0004 כפי שהוכחנו, \u0003אינו דין שנקנית בביאה?\u0004","ויש לדחות: \u0003אמה העבריה תוכיח, שנקנית בכסף ו\u0004אף על פי כן \u0003אין נקנית בביאה.\u0004 את הדחיה הזו דוחים: \u0003מה לאמה העבריה\u0004 — \u0003שאין קנינה לשום\u0004 (לשם) \u0003אישות,\u0004 שמעיקרה נקנית לשם עבדות, \u0003תאמר בזו,\u0004 באשה, \u0003שקנינה לשום אישות\u0004 ולכן מסתבר שתקנה בביאה.","\u0003תלמוד לומר: \"ובעלה\".\u0004 וגם כאן תוהים: אם כן, \u0003ולמה לי קרא\u0004 \u0005[פסוק]?\u0006 \u0003הא אתיא לה\u0004 \u0005[הרי באה לו],\u0006 כלומר, הרי עלתה בידו הוכחה מקל וחומר! \u0003אמר רב אשי: משום דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]\u0006 \u0003מעיקרא דדינא פירכא\u0004 \u0005[מעיקרו של הדין,\u0006 הקל וחומר, יש בו \u0005פירכא]\u0006 \u0003מהיכא קא מייתית לה\u0004 \u0005[מהיכן אתה מביא\u0006 לומד \u0005אותה,\u0006 את ההוכחה\u0005]\u0006 שביאה קונה — \u0003מיבמה,\u0004 ואולם יכול אתה לומר:","\u0003מה ליבמה\u0004 — \u0003שכן זקוקה\u0004 (קשורה) \u0003ועומדת\u0004 ליבם, ובגלל זיקתה לו די בביאה לעשותה אשתו ממש, \u0003תאמר בזו,\u0004 בסתם אשה, \u0003שאין זקוקה ועומדת\u0004 ויתכן שאין די בכך כדי לקנותה, ואם כן נפרך כל הלימוד כולו. וכיון שכך יש להזקק לראיה אחרת. \u0003תלמוד לומר\u0004 מן הכתוב: \u0003\"ובעלה\".\u0004"],["וממשיכה הברייתא בענין קנייני קידושין: \u0003ומנין שאף בשטר\u0004 האשה נקנית? ומשיבה: \u0003ודין הוא\u0004 הנלמד בקל וחומר משיקול הדעת: \u0003ומה כסף שאין מוציא\u0004 את האשה מבעלה, שאינה מתגרשת בו — \u0003מכניס,\u0004 שהאשה נקנית לבעלה בכסף, \u0003שטר שמוציא,\u0004 שהרי האשה יוצאת מבעלה בגט, שהוא שטר — \u0003אינו דין שמכניס?\u0004","ויש לדחות: \u0003מה לכסף\u0004 שיש לו כוח קנין גדול, \u0003שכן פודין בו הקדש ומעשר שני תאמר\u0004 לכן גם ב\u0003שטר שאין פודין בו הקדש ומעשר שני.\u0004 וראיה שאין פודים אלא בכסף — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ונתן הכסף וקם לו\"!\u0004 (ראה ויקרא כז, יט) ואם כן אי אפשר ללמוד דין זה מסברה.","ואולם \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויצאה\u0004 מביתו והלכה \u0003והיתה\u0004 לאיש אחר\u0003\"\u0004 (דברים כד, ב) — \u0003מקיש\u0004 \u0005[משווה]\u0006 הכתוב \u0003הויה,\u0004 כלומר, קידושין, \u0003ליציאה\u0004 ממנו: \u0003מה יציאה\u0004 נעשית \u0003בשטר\u0004 (גט) — \u0003אף הויה נמי\u0004 \u0005[גם כן]\u0006 יכולה להיעשות \u0003בשטר.\u0004 ושואלים: \u0003ואקיש נמי\u0004 \u0005[והקש,\u0006 השוה \u0005גם כן]\u0006 להיפך, \u0003יציאה להויה: מה הויה בכסף\u0004 — \u0003אף יציאה\u0004 תהא \u0003בכסף!\u0004","\u0003אמר אביי:\u0004 אם כן \u0003יאמרו\u0004 האנשים: \u0003כסף מכניס, כסף מוציא,\u0004 וכי \u0003סניגור יעשה קטיגור?\u0004 ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה דן, \u0003שטר נמי\u0004 \u0005[גם כן]\u0006 \u0003יאמרו: שטר מוציא, שטר מכניס,\u0004 וכי \u0003קטיגור יעשה סניגור?\u0004","ומשיבים: \u0003מילי דהאי שטרא\u0004 \u0005[דברי,\u0006 ענייני, \u0005שטר זה]\u0006 של קידושין הם \u0003לחוד ומילי דהאי שטרא\u0004 \u0005[דברי,\u0006 ענייני, \u0005שטר זה]\u0006 של גירושין הם \u0003לחוד\u0004 ואינם דומים בתוכנם זה לזה. ומקשים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003האי כספא\u0004 \u0005[זה כסף]\u0006 \u0003לחוד והאי כספא\u0004 \u0005[וזה כסף]\u0006 \u0003לחוד,\u0004 שזה כסף קידושין, וזה כסף גירושין! ומשיבים: \u0003טיבעא מיהא חד\u0004 \u0005[המטבע על כל פנים אחד]\u0006 \u0003הוא,\u0004 שאין הבדל בין מטבע של קידושין לזה של גירושין, מה שאין כן בשטר, שיש הבדל בגוף השטר עצמו, שאין אותו נוסח שטר של קידושין משמש גם לגירושין.","\u0003רבא אמר:\u0004 זה שאין אשה מתגרשת בכסף נלמד ממקום אחר, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וכתב לה\u0004 ספר כריתות\u0003\"\u0004 (שם ג) ללמד: רק \u0003בכתיבה\u0004 (בשטר) האשה \u0003מתגרשת, ואינה מתגרשת בכסף.\u0004 ומקשים: כיון שלא נאמר הדבר במפורש ואנו למדים אותו רק מדיוק בלשון הכתוב, \u0003ואימא\u0004 \u0005[ואמור]\u0006 באופן אחר: \u0003בכתיבה מתגרשת\u0004 — \u0003ואינה מתקדשת בכתיבה!\u0004 ודוחים: \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"ויצאה והיתה\"\u0004 ובמפורש \u0003מקיש\u0004 \u0005[משווה]\u0006 הויה ליציאה שאף קידושין יכולים להיות בשטר.","ושואלים: \u0003ומה ראית\u0004 לומר שהמיעוט \"וכתב לה\" בא למעט שאינה יוצאה בכסף; וההיקש בא לרבות שמתקדשת בכתיבה (בשטר)? והרי אפשר לומר: שמיעוט זה בא לומר שמתגרשת בכתיבה אך אינה מתקדשת בכתיבה, ומההיקש נלמד דברים אחרים! ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר\u0006 הדבר\u0005]\u0006 כאשר הכתוב \u0003קאי\u0004 \u0005[עומד,\u0006 עוסק\u0005]\u0006 \u0003בגירושין\u0004 הריהו \u0003ממעט גירושין\u0004 בכל אופן אחר, אבל לא להיפך, וכי \u0003קאי\u0004 \u0005[עומד]\u0006 \u0003בגירושין וממעט קידושין?!\u0004","ושואלים: \u0003ול\u0004שיטת \u0003ר' יוסי הגלילי דאפיק ליה להאי קרא לדרשא אחרינא\u0004 \u0005[שהוציא אותו, את הכתוב הזה\u0006 \"וכתב לה ספר כריתות\" \u0005לדרשה אחרת],\u0006 דין זה \u0003שאינה מתגרשת בכסף מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ספר כריתות\",\u0004 ללמד: \u0003ספר\u0004 (דבר כתוב) \u0003כורתה, ואין דבר אחר כורתה.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים על ר' יוסי, \u0003האי\u0004 \u0005[זה]\u0006 הלימוד של \u0003\"\u0004ספר \u0003כריתות\", מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בו]?\u0006 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריכים\u0006 הם \u0005אותו]\u0006 \u0003ל\u0004למדנו שיהא הגט \u0003דבר הכורת\u0004 לגמרי \u0003בינו לבינה,\u0004 שהגט צריך להיות מנוסח כך שמנתק לגמרי את הקשר ביניהם.","\u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 האומר לאשה \u0003\"הרי זה גיטיך על מנת שלא תשתי יין\",\u0004 או \u0003\"על מנת שלא תלכי לבית אביך לעולם\"\u0004 — \u0003אין זה\u0004 גט \u0003כריתות,\u0004 שהרי לענין זה היא נשארת מוגבלת ועדיין היא קשורה בכך לבעלה כל ימי חייה ואין זו כריתות. אבל אם אמר לה תנאי כלשהו והגבילו בזמן כגון: \u0003\"כל שלשים יום\" — הרי זה כריתות.\u0004","ושואלים: \u0003ור' יוסי הגלילי\u0004 מנין למד הוא הלכה זו? ומשיבים: דבר זה \u0003מ\u0004שינוי הלשון \u0003\"כרת\" \"כריתת\" קא נפקא ליה\u0004 \u0005[יוצא לו]\u0006 שמכיון שיכול היה להיאמר \"ספר כרת\" ונאמר \"ספר כריתות\" הרי זה בא ללמד שני דברים. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מדוע גם הם אינם לומדים כך — הלימוד הזה משינוי הלשון של \u0003\"כרת\" \"כריתת\" לא משמע להו\u0004 \u0005[אינו נשמע להם],\u0006 אין הם חושבים שיש בו משמעות ללמוד ממנו. לאחר שלמדה הברייתא את שלוש דרכי הקנין באשה שואלים: מדוע נצרך לימוד מיוחד לכל אחת מדרכי הקנין?","אמנם \u0003חדא מחדא לא אתיא\u0004 \u0005[אחת מאחת אינה באה,\u0006 נלמדת\u0005],\u0006 שאי אפשר ללמוד דרך קנין אחת מדרך אחרת כפי שביארה הברייתא, ואולם מכל מקום \u0003תיתי חדא מתרתי\u0004 \u0005[\u0006ש\u0005תבוא,\u0006 תילמד, דרך \u0005אחת משתים\u0006 האחרות\u0005]!\u0006 ומשיבים: אין הדבר אפשרי, כי \u0003הי תיתי\u0004 \u0005[איזו תבוא,\u0006 תילמד\u0005]\u0006 מן האחרות? אם נאמר ש\u0003לא ליכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 שמתקדשת \u0003בשטר ותיתי מהנך\u0004 \u0005[ותבוא\u0006 תילמד דרך זו \u0005מההן\u0006 האחרות, ביאה וכסף\u0005]\u0006 אולם אפשר לדחות: \u0003מה להנך\u0004 \u0005[לההן\u0006 האחרות\u0005]\u0006 \u0003שכן הנאתן מרובה,\u0004 מה שאין כן בשטר שאין האשה נהנית כלל בקבלת השטר.","ואם תאמר: \u0003לא ניכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 שנקנית \u0003בביאה ותיתי מהנך\u0004 \u0005[ותבוא,\u0006 תילמד \u0005מההן\u0006 האחרות שהן כסף ושטר\u0005],\u0006 ואולם \u0003מה להנך\u0004 \u0005[לההן]\u0006 — \u0003שכן קנינן מרובה,\u0004 שהן דרכי קנין הקונות בכל מקום, לפיכך קונות גם באשה.","ואם תאמר: \u0003לא ניכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 שנקנית \u0003בכסף ותיתי מהנך\u0004 \u0005[ותבוא,\u0006 תילמד הדרך הזו \u0005מההן\u0006 האחרות\u0005],\u0006 ואולם \u0003מה להנך\u0004 \u0005[לההן]\u0006 \u0003שכן ישנן בעל כרחה,\u0004 שכן ביאה קונה ביבמה בעל כרחה, וגט מוציא את האשה בעל כרחה.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003כסף נמי\u0004 \u0005[גם כן]\u0006 ישנו \u0003בעל כרחה,\u0004 וכגון \u0003באמה העבריה\u0004 שאביה מוכרה לאדון אף שלא ברצונה, ואם כן, אפשר ללמוד כסף מביאה ומשטר — \u0003ב\u0004דיני \u0003אישות מיהא\u0004 \u0005[על כל פנים]\u0006 \u0003לא אשכחן\u0004 \u0005[מצאנו]\u0006 קנין בכסף בעל כרחה. ומשום כך יש צורך ללמוד כל אחת מדרכי הקנין ממקור מיוחד.","\u0003אמר רב הונא: חופה\u0004 עצמה, שהבעל כונס את אשתו אליה \u0003קונה\u0004 את האשה \u0003מקל וחומר\u0004 זה: \u0003ומה כסף שאינו מאכיל בתרומה,\u0004 שאשה ישראלית שנתקדשה לכהן — עדיין אינה רשאית לאכול בתרומה, ומכל מקום הכסף \u0003קונה\u0004 את האשה להיות מקודשת, \u0003חופה שמאכלת בתרומה,\u0004 שלאחר שנכנסה האשה לחופה מותרת לאכול בתרומה מכוח בעלה הכהן — \u0003אינו דין שתקנה\u0004 אשה לבעלה על ידה?","ושואלים: \u0003ו\u0004כי \u0003כסף אינו מאכיל\u0004 את האשה בתרומה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003עולא: דבר תורה,\u0004 לפי דין התורה היסודי, \u0003ארוסה בת ישראל אוכלת בתרומה\u0004 מיד כשנתקדשה לכהן, \u0003שנאמר: \"וכהן כי יקנה נפש קנין כספו\u0004 הוא יאכל בו\u0003\"\u0004 (ויקרא כב, יא) \u0003והאי\u0004 \u0005[וזו]\u0006 האשה גם היא בכלל \u0003\"קנין כספו הוא\".\u0004","\u0003ומה טעם אמרו\u0004 חכמים \u0003אינה אוכלת\u0004 בתרומה — \u0003גזירה שמא ימזגו לה כוס\u0004 יין של תרומה \u0003בבית אביה\u0004 שהיא מצויה שם לפני שנישאה, \u0003ותשקנו לאחיה ולאחותיה\u0004 והם אסורים בתרומה. הרי שמדין תורה, מאז נתקדשה האשה בכסף היא זכאית לאכול בתרומה. ואם כן מכאן אין הוכחה לקנין החופה.","\u0003אלא\u0004 צריך לתקן ולומר כי \u0003פריך הכי\u0004 \u0005[הקשה כך]:\u0006 \u0003ומה כסף שאינו גומר\u0004 את הקנין באשה, שהרי אף לאחר קידושין היא ברשות אביה במקצת דברים, מכל מקום \u0003קונה\u0004 בה קנין קידושין,"],["\u0003חופה שגומרת\u0004 את הנישואין ומוציאה את האשה לגמרי מרשות אביה \u0003אינו דין שתקנה\u0004 לבדה? ודוחים: \u0003מה לכסף\u0004 שכן יש בו כוח קנין גדול \u0003שכן פודין בו הקדשות ומעשר שני,\u0004 מה שאין כן חופה שאין לה כוח קנין בעניינים אחרים, ולכן, אף בקידושין דווקא כסף קונה ולא חופה. על כך מביאים ראיה מצד אחר: \u0003ביאה תוכיח,\u0004 שקונה באשה, אף על פי שאינה קונה במקום אחר.","ודוחים: \u0003מה לביאה שכן קונה ביבמה\u0004 מה שאין כן חופה! ומשיבים: על כך \u0003כסף יוכיח,\u0004 שאינו קונה ביבמה, ובכל זאת עושה קנין באשה. \u0003וחזר\u0004 (פנה, סבב) \u0003הדין\u0004 של קל וחומר מצד זה לצד זה \u0003לא ראי\u0004 (מראהו, טיבו) של \u0003זה כראי זה, ולא ראי זה כראי זה,\u0004 שני הדברים, כסף וביאה, אינם דומים, אך \u0003הצד השוה שבהן: שקונין בעלמא\u0004 \u0005[בכלל]\u0006 \u0003וקונין כאן\u0004 בקידושין, \u0003אף אני אביא חופה שקונה בעלמא\u0004 \u0005[בכלל]\u0006 כנשואה, \u0003וקונה כאן.\u0004","ודוחים: \u0003מה להצד השוה שבהן\u0004 בכסף ובביאה \u0003שכן הנאתן מרובה.\u0004 ואומרים: אם כן \u0003שטר יוכיח,\u0004 שאין הנאתו מרובה, שהרי אין הנאה בקבלת השטר, ובכל זאת הוא קונה באשה. ודוחים: \u0003מה לשטר\u0004 שכוחו גדול \u0003שכן מוציא בבת ישראל,\u0004 שהרי מכוח שטר (גט) מתגרשת האשה. ומשיבים: אם כן \u0003כסף וביאה יוכיחו,\u0004 שאינם מוציאים, ועושים קנין קידושין.","\u0003וחזר הדין, לא ראי זה כראי זה, ולא ראי זה כראי זה,\u0004 אך \u0003הצד השוה שבהן: שקונין בעלמא\u0004 \u0005[בכלל]\u0006 \u0003וקונין כאן\u0004 — \u0003אף אני אביא חופה שקונה בעלמא\u0004 \u0005[בכלל]\u0006 \u0003וקונה כאן.\u0004","ודוחים שוב: \u0003מה להצד השוה שבהן שכן ישנן בעל כרחה,\u0004 שגם שטר (גט) גם ביאה (ביבמה) וגם כסף (באמה העבריה) יש בהם כוח של קנין בעל כרחה של האשה, ואין להוכיח מהם לקנין חופה שאינה אלא מרצון. \u0003ו\u0004על כך משיב \u0003רב הונא: כסף מיהא\u0004 \u0005[על כל פנים]\u0006 לענין קנין \u0003באישות לא אשכחן\u0004 \u0005[מצאנו]\u0006 שקונה \u0003בעל כרחה\u0004 ואם כן אפשר ללמוד מכסף שטר וביאה יחד שגם חופה קונה.","\u0003אמר רבא: שתי תשובות\u0004 (דחיות) \u0003בדבר\u0004 לפרוך את שיטת רב הונא, דחיה \u0003חדא\u0004 \u0005[אחת]\u0006 — שהלא \u0003\"שלש\"\u0004 דרכים של קנין \u0003תנן\u0004 \u0005[שנינו]\u0006 במשנתנו (\"האשה נקנית בשלשה דרכים\") \u0003ו\"ארבע\" לא תנן\u0004 \u0005[שנינו],\u0006 משמע שאין דרך קנין נוספת באשה.","\u0003ועוד\u0004 כנגד עיקר הראיה: \u0003כלום חופה גומרת\u0004 להוציא את האשה מכוח אביה \u0003אלא על ידי קידושין\u0004 שקדמו לחופה, ואם כן אין החופה לבדה עושה קנין נישואין אלא מכוח הקידושין, \u0003וכי גמרינן\u0004 \u0005[\u0006יכולים \u0005אנו\u0006 \u0005ללמוד]\u0006 \u0003חופה\u0004 שתקנה \u0003שלא על ידי קידושין מחופה ש\u0004קונה \u0003על ידי קידושין?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי,\u0004 שתי תשובות אלה יש מקום לפורכן כך: \u0003הא דקאמרת\u0004 \u0005[זה שאמרת]\u0006 \u0003\"שלש\" תנן\u0004 \u0005[שנינו]\u0006 \u0003ו\"ארבע\" לא תנן\u0004 \u0005[שנינו]\u0006 — אין זו הוכחה, כי ה\u0003תנא מילתא דכתיבא בהדיא קתני\u0004 \u0005[\u0006את \u0005הדבר הכתוב\u0006 בתורה \u0005במפורש שנה],\u0006 ואילו \u0003מילתא דלא כתיבא בהדיא\u0004 \u0005[הדבר שאינו כתוב במפורש\u0006 בתורה\u0005]\u0006 \u0003לא קתני\u0004 \u0005[שנה].\u0006","\u0003ודקאמרת\u0004 \u0005[ו\u0006מה \u0005שאמרת]\u0006 \u0003כלום חופה גומרת אלא על ידי קידושין\u0004 שקדמו לה — \u0003רב הונא נמי הכי קאמר\u0004 \u0005[גם כן כך אמר]:\u0006 \u0003ומה כסף שאינו גומר אחר כסף,\u0004 שלאחר קנין קידושין של כסף, אין מתן כסף אחר יכול לגמור את הקנין ולעשותה לנשואה, בכל זאת \u0003קונה\u0004 את האשה בקנין קידושין, \u0003חופה ש\u0004גדול כוחה ו\u0003גומרת אחר כסף\u0004 — \u0003אינו דין שתקנה\u0004 בעצמה?","לאחר הדיון בכללים שבמשנה ובמקורם בתורה, מתחילים לדון בגופי ההלכות. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כיצד\u0004 דרך הקידושין \u0003בכסף?\u0004 — \u0003נתן לה כסף או שוה כסף, ואמר לה \"הרי את מקודשת לי\",\u0004 או \u0003\"הרי את מאורסת לי\",\u0004 או \u0003\"הרי את לי לאינתו\"\u0004 \u0005[לאשה]\u0006 — \u0003הרי זו מקודשת. אבל\u0004 אם \u0003היא\u0004 זו \u0003שנתנה, ואמרה היא \"הריני מקודשת לך\",\u0004 או \u0003\"הריני מאורסת לך\",\u0004 או \u0003\"הריני לך לאינתו\"\u0004 \u0005[לאשה]\u0006 — \u0003אינה מקודשת.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא:\u0004 ברייתא זו יש בה סתירה פנימית, שכן בתחילת הברייתא שנינו \"נתן לה כסף ואמר לה וגו'\" ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 כאשר \u0003נתן הוא ואמר הוא,\u0004 אזי האשה מקודש ת, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003נתן הוא ואמרה היא\u0004 — \u0003אינה מקודשת.\u0004 ולעומת זאת \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של הברייתא: \u0003אבל היא שנתנה לו ואמרה היא\u0004 — \u0003לא הוו\u0004 \u0005[אינם]\u0006 \u0003קידושין.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 במקרה ש\u0003נתנה היא ואמרה היא, הא\u0004 \u0005[הרי]\u0006 אם \u0003נתן הוא ואמרה היא\u0004 — \u0003הוו\u0004 \u0005[הריהם]\u0006 \u0003קידושין!\u0004","ומשיבים: לא, \u0003רישא\u0004 \u0005[תחילת\u0006 הברייתא\u0005]\u0006 ב\u0003דוקא\u0004 נאמרה ובאה גם לשלול מה שלא נאמר בה, \u0003סיפא כדי נסבה\u0004 \u0005[סוף\u0006 הברייתא \u0005סתם, לחינם הביא אותה]\u0006 ואין לדייק ממנה שרק באופן זה אינם קידושין. ותוהים: \u0003ותני סיפא מילתא דסתרא לה לרישא\u0004 \u0005[ו\u0006כי \u0005שונה בסוף דבר הסותר את ההתחלה]?\u0006","\u0003אלא\u0004 יש לחזור מן ההסבר הקודם ולומר כי \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 אם \u0003נתן הוא ואמר הוא\u0004 — \u0003פשיטא דהוו\u0004 \u0005[פשוט,\u0006 ברור \u0005שהם]\u0006 \u0003קידושין. נתן הוא ואמרה היא\u0004 — \u0003נעשה כמי שנתנה היא ואמרה היא, ולא הוו\u0004 \u0005[ואינם]\u0006 \u0003קידושין. ואי בעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 והסבר את הברייתא באופן אחר: \u0003נתן הוא ואמר הוא\u0004 —\u0003 מקודשת\u0004. \u0003נתנה היא ואמרה היא\u0004 — \u0003אינה מקודשת\u0004 כלל. אך כאשר \u0003נתן הוא ואמרה היא\u0004 — \u0003ספיקא היא\u0004 \u0005[ספק הוא]\u0006 \u0003וחיישינן מדרבנן\u0004 \u0005[וחוששים אנו מדברי סופרים]\u0006 שמא יש בכך קידושין.","ועוד בענין לשונות קידושין, \u0003אמר שמואל: בקידושין, נתן לה כסף,\u0004 או \u0003שוה כסף ואמר לה \"הרי את מקודשת\",\u0004 או \u0003\"הרי את מאורסת\",\u0004 או \u0003\"הרי את לי לאינתו\"\u0004 \u0005[לאשה]\u0006 — \u0003הרי זו מקודשת.\u0004 ואם אמר \u0003\"הריני אישך\",\u0004 או \u0003\"הריני בעליך\",\u0004 או \u0003\"הריני ארוסיך\"\u0004 — \u0003אין כאן בית מיחוש\u0004 (מקום לחשוש). שאין כאן אפילו ספק קידושין, שאין קידושין אלא בלקיחת האשה לאיש ולא להיפך.","\u0003וכן בגירושין,\u0004 אם \u0003נתן לה\u0004 גט \u0003ואמר לה \"הרי את משולחת\",\u0004 או \u0003\"הרי את מגורשת\",\u0004 או \u0003\"הרי את מותרת לכל אדם\"\u0004 — \u0003הרי זו מגורשת.\u0004 אך אם אמר \u0003\"איני אישך\",\u0004 או \u0003\"איני בעליך\",\u0004 או \u0003\"איני ארוסיך\"\u0004 — \u0003אין כאן בית מיחוש,\u0004 שהרי זה גירוש האיש ולא גירוש האשה, ואינם גירושין כלל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: למימרא דסבר\u0004 \u0005[האם לומר,\u0006 ללמוד, מכאן \u0005שסבור]\u0006 \u0003שמואל\u0004 כי \u0003ידים שאין מוכיחות,\u0004 כלומר, ביטוי בלתי מושלם, שכשלעצמו אי אפשר להוכיח ממנו דבר, אלא שהוא מובן מתוך הקשר הדברים, \u0003הויין\u0004 \u0005[הריהן\u0006 נחשבות\u0005]\u0006 ל\u0003ידים?\u0004 (לדבר שאפשר להיאחז בו כביטוי שלם), שהרי באותם מקרים שאמר שמואל שהאשה מקודשת לא אמר האיש \"הרי את מקודשת לי\", אלא \"הרי את מקודשת\" וביטוי זה לכשעצמו אין בו הוכחה שכוונתו לעצמו, ובכל זאת סבור שמואל שיש לו תוקף.","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 במסכת נזיר: \u0003האומר \"אהא\"\u0004 סתם — \u0003הרי זה נזיר. והוינן בה\u0004 \u0005[והיינו עוסקים,\u0006 מתקשים\u0005]\u0006 \u0003בה,\u0004 בבעיה זו: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003\"אהא בתענית\" קאמר\u0004 \u0005[היה אומר,\u0006 התכוון לומר\u0005]?\u0006 \u0003ואמר שמואל\u0004 שכאן מדובר במקרה מיוחד, שאמר \"אהא\" \u0003והוא שהיה נזיר עובר לפניו,\u0004 ומתוך כך מובן שהתכוון לומר שיהא אף הוא נזיר. ומכאן נדייק כי \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003נזיר עובר לפניו, הא לאו הכי\u0004 \u0005[הרי אם לא כך]\u0006 — \u0003לא,\u0004 ולא היה זה נחשב לנדר נזירות. משמע ששמואל סבור כי ידים שאינן מוכיחות — אינן נחשבות ידים!","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 באופן ש\u0003אמר\u0004 והוסיף את המלה \u0003\"לי\",\u0004 כגון שאמר לאשה \"הרי את מקודשת לי\". ותוהים: \u0003אי הכי מאי קא משמע לן\u0004 \u0005[אם כך מה השמיע לנו]\u0006 בדבר זה? הרי מובן שהיא מקודשת, שזהו נוסח הקידושין! ומשיבים: \u0003הני\u0004"],["\u0003לישני בתראי קא משמע לן\u0004 \u0005[אותן הלשונות האחרונות השמיע לנו],\u0006 החידוש בדברי שמואל שאין בהן חשש לקידושין ולגירושין. ומסבירים מדוע סבור שמואל שאין בהן אפילו חשש: \u0003הכא כתיב\u0004 \u0005[כאן,\u0006 בענין קידושין, \u0005נאמר]\u0006 \u0003\"כי יקח\u0004 איש אשה\u0003\"\u0004 (דברים כד, א) — שהבעל לוקח אותה לאשה \u0003ולא שיקח את עצמו,\u0004 שמשייך את עצמו לה, כמו האומר: \"הריני אישך\". \u0003והכא כתיב\u0004 \u0005[וכאן\u0006 בגירושין \u0005נאמר]\u0006 \u0003\"ושלחה\"\u0004 (שם) — \u0003ולא שישלח את עצמו\u0004 ממנה, כמו האומר \"איני אישך\".","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 האומר לאשה \u0003\"הרי את אשתי\",\u0004 או \u0003\"הרי את ארוסתי\",\u0004 או \u0003\"הרי את קנויה לי\"\u0004 — הרי זו \u0003מקודשת.\u0004 אמר לה \u0003\"הרי את שלי\",\u0004 או \u0003\"הרי את ברשותי\",\u0004 או \u0003\"הרי את זקוקה לי\"\u0004 — \u0003מקודשת.\u0004 ושואלים: כיון שבשני החלקים של הברייתא דינה שהיא מקודשת, \u0003וליתנינהו כולהו כחדא\u0004 \u0005[ושישנה\u0006 את \u0005כולם כאחת]\u0006 ומדוע מחולקת הברייתא לשני חלקים? ומשיבים: \u0003תנא תלת תלת שמעינהו וגרסינהו\u0004 \u0005[התנא שלוש שלוש שמע אותן ו\u0006כך גם \u0005גרס אותן],\u0006 שכל פסקה שבה שלושה מקרים שמע מרבותיו כהלכה בפני עצמה, ומשום כך גם כאשר צירף אותן גרס אותן כשתי פסקות נפרדות.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 אם אמר האיש המקדש לאשה \u0003\"\u0004הרי את \u0003מיוחדת לי\" מהו\u0004 הדין, האם האשה מקודשת בכך? וכן אם אמר לה \u0003\"\u0004הרי את \u0003מיועדת לי\" מהו?\u0004 או שאמר לה \u0003\"עזרתי\",\u0004 כאמור ביצירת האשה לאיש \"אעשה לו עזר כנגדו\" (בראשית ב, יח), \u0003מהו?\u0004 שאמר לה \u0003\"נגדתי\"\u0004 מלשון האמור (שם) \"עזר כנגדו\" \u0003מהו? \"עצורתי\"\u0004 שמשמעה לשון כניסה (כמו \"עצרת\") והכוונה שהוא כונסה להיות עימו. \u0003מהו?\u0004 וכן האומר לה \u0003\"צלעתי\"\u0004 שהוא רמז ללשון הכתוב \"ויקח אחת מצלעותיו ויסגור בשר תחתנה\" (שם, כא) \u0003מהו? \"סגורתי\"\u0004 (כלשון \"ויסגור בשר\") \u0003מהו? \"תחתי\"\u0004 (שהוא רמז ל\"תחתנה\") \u0003מהו? \"תפושתי\" מהו? \"לקוחתי\" מהו?\u0004","ומציעים: \u0003פשוט מיהא חדא\u0004 \u0005[פתור לפחות\u0006 בעיה \u0005אחת]\u0006 מאלה ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר\u0004 לאשה \u0003\"\u0004הרי את \u0003לקוחתי\"\u0004 — \u0003הרי זו מקודשת, משום שנאמר \"כי יקח איש אשה\"\u0004 (דברים כד, א).","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]:\u0006 ללומדים שאלה זו: אם אמר לאשה \u0003\"\u0004הרי את \u0003חרופתי\" מהו? תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר \"\u0004הרי את \u0003חרופתי\"\u0004 — הרי זו \u0003מקודשת, שכן ביהודה קורין לארוסה \"חרופה\".\u0004 ותוהים: \u0003ו\u0004כי \u0003יהודה הויא רובא דעלמא\u0004 \u0005[היא רוב העולם]?\u0006 ואף אם הדבר נכון לגבי ארץ יהודה, מדוע תהא זאת הלכה כללית?","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003האומר \"\u0004הרי את \u0003חרופתי\"\u0004 — הרי זו \u0003מקודשת,\u0004 לפי \u0003שנאמר: \"והיא שפחה נחרפת לאיש\"\u0004 (ויקרא יט, כ) שמשמעות הכתוב שהיא מקודשת לאיש מסויים. \u0003ועוד\u0004 סמך ללשון זו: שכן \u0003ביהודה קורין לארוסה \"חרופה\".\u0004 ותוהים: \u0003ויהודה\u0004 צריכה להיות \u0003ועוד\u0004 (תוספת) \u0003לקרא\u0004 \u0005[לכתוב]?!\u0006 וכי צריך להביא ראיה נוספת ללשון הכתוב ממנהגם של בני יהודה?! \u0003אלא\u0004 יש לחזור מן ההסבר הזה ולומר כי \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003האומר \"\u0004הרי את \u0003חרופה\"\u0004 (\"חרופתי\") \u0003ביהודה\u0004 — \u0003מקודשת, שכן ביהודה קורין לארוסה \"חרופה\".\u0004","לגבי כל הלשונות שדנים עליהן שואלים שאלה כללית: \u0003במאי עסקינן\u0004 \u0005[במה,\u0006 באיזה אופן \u0005אנו עוסקים]\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003ב\u0004אופן \u0003שאין מדבר עמה על עסקי גיטה וקידושיה\u0004 ולפתע אמר לה ביטוי כגון זה — \u0003מנא ידעה מאי קאמר\u0004 \u0005[מנין\u0006 היא \u0005יודעת מה\u0006 הוא \u0005אומר]\u0006 \u0003לה?\u0004 הרי לשונות אלה כפשוטן אינן לשונות של קידושין. \u0003ואלא\u0004 תאמר שמדובר \u0003ב\u0004מקרה שהיה \u0003מדבר עמה על עסקי גיטה וקידושיה\u0004 — במקרה כזה \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא אמר לה\u0004 שום לשון \u0003נמי\u0004 \u0005[גם כן]\u0006 יהיו אלה קידושין אם נתן לה כסף קידושין.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003היה מדבר עם אשה על עסקי גיטה\u0004 או \u0003קידושיה ונתן לה גיטה,\u0004 או \u0003קידושיה ולא פירש\u0004 דבר — \u0003ר' יוסי אומר: דיו,\u0004 די בכך להשלמת הענין, שהרי מתוך הקשר הדברים היא מבינה במה הם עוסקים. \u0003ר' יהודה אומר: צריך לפרש. ואמר רב הונא אמר שמואל: הלכה כר' יוסי\u0004 ולפי זה גם אם לא אמר לה דבר היתה מקודשת ובוודאי שכאשר אמר לה אחת מן הלשונות הנזכרות הריהי מקודשת בכך!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בהסברת הדברים: \u0003לעולם\u0004 מדובר \u0003במדבר עמה על עסקי גיטה וקידושיה, ואי דיהיב\u0004 \u0005[ואם\u0006 היה \u0005נותן]\u0006 \u0003לה ושתיק\u0004 \u0005[ושותק]\u0006 ולא אומר דבר \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 היו הקידושין מועילים, אלא \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 באופן \u0003דיהב\u0004 \u0005[שנתן]\u0006 \u0003לה\u0004 דבר \u0003ואמר לה בהני לישני\u0004 \u0005[בלשונות הללו],\u0006","\u0003והכי קא מיבעי ליה\u0004 \u0005[וכך נשאלה לו]:\u0006 האם \u0003הני לישני לקידושי קאמר\u0004 \u0005[לשונות אלה לקידושין אמר]\u0006 \u0003לה, או דילמא\u0004 \u0005[שמא]\u0006 \u0003למלאכה קאמר\u0004 \u0005[אמר]\u0006 \u0003לה,\u0004 שלשונות אלה משמען שהוא שוכר אותה לעבודה כלשהי, וביטל כוונתו להתקדש עימה, ואם כן לשונות אלה גרועות יותר מאילו היה שותק. ולא נפתרו רוב הבעיות ועל כן \u0003תיקו\u0004 \u0005[תעמודנה]\u0006 במקומן.","\u0003גופא\u0004 (לגופה) של ההלכה שהזכרנו: \u0003היה מדבר עם האשה על עיסקי גיטה\u0004 או \u0003קידושיה, ונתן לה גיטה\u0004 או \u0003קידושיה ולא פירש\u0004 — \u0003ר' יוסי אומר: דיו\u0004 בכך. \u0003ר' יהודה אומר: צריך לפרש. אמר רב יהודה אמר שמואל: והוא שעסוקין באותו ענין\u0004 ולא עברו לדבר בנושא אחר.","\u0003וכן אמר ר' אלעזר אמר ר' אושעיא: והוא שעסוקין באותו ענין.\u0004 ומעירים: מחלוקת זו הריהי \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 בענין זה: \u0003רבי אומר: והוא שעסוקין באותו ענין. ר' אלעזר בר ר' שמעון אומר: אף על פי שאין עסוקין באותו ענין.\u0004","ושואלים: \u0003ואי לאו\u0004 \u0005[ואם לא]\u0006 ש\u0003עסוקין\u0004 \u0003באותו ענין, מנא ידעה מאי קאמר\u0004 \u0005[מנין\u0006 היא \u0005יודעת מה הוא\u0006 \u0003אומר]\u0004 \u0003לה?\u0004 שהרי עברו לדבר בענין אחר ולשונות אלה ודאי אינן בעלות משמעות ברורה! \u0003אמר אביי:\u0004 הכוונה היא שלא עברו לענין שונה לגמרי אלא \u0003מענין לענין באותו ענין,\u0004 כלומר, לא דיברו במישרין על גט או קידושין אבל עדיין דיברו בנושאים הקשורים לכך, שהיה מובן בעת שאמר לה מה שאמר, למה הוא מתכוון.","\u0003אמר רב הונא אמר שמואל: הלכה כ\u0004שיטת \u0003ר' יוסי. אמר לו רב יימר לרב אשי: ואלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב יהודה אמר שמואל: כל שאינו יודע בטיב גיטין וקידושין לא יהא לו עסק עמהם,\u0004 ואסור לו להיות דיין בכך, שמא יבוא להתיר את האסור, \u0003אפילו לא שמיע ליה\u0004 \u0005[שמע]\u0006 אותו אדם \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 של \u0003רב הונא אמר שמואל,\u0004 למרות שאינה דבר מצוי ביותר גם כן ייחשב שאינו יודע? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין, הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן]\u0006 שדבר חשוב הוא בדיני קידושין, ומי שאינו יודע זאת יכול להכשל.","על דברי שמואל (בדף הקודם) \u0003וכן בגירושין, נתן לה גיטה ואמר לה: \"הרי את משולחת\"\u0004 או \u0003\"הרי את מגורשת\",\u0004 או \u0003\"הרי את מותרת לכל אדם\"\u0004 — \u0003הרי היא מגורשת.\u0004 מעירים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 לנו שאם \u0003נתן לה גיטה, ואמר לה לאשתו: \"הרי את בת חורין\"\u0004"],["\u0003לא אמר ולא כלום,\u0004 שאין זו לשון גירושין. וכן אם \u0003אמר לה לשפחתו\u0004 כשרוצה לשחררה בלשון \u0003\"הרי את מותרת לכל אדם\"\u0004 — \u0003לא אמר ולא כלום.\u0004","ולאחר שהקדמנו דברים אלה הברורים לנו, יש לשאול: אם \u0003אמר לה לאשתו \"הרי את לעצמך\" מהו\u0004 דינו? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 שרק \u0003ל\u0004ענין \u0003מלאכה קאמר\u0004 \u0005[אומר]\u0006 \u0003לה,\u0004 כלומר, ששכר מלאכתה יהיה לעצמה, ולא תעשה מלאכה עבורו, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003לגמרי קאמר\u0004 \u0005[אמר]\u0006 \u0003לה\u0004 שהיא לעצמה, כלומר, שהיא מגורשת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003גופו\u0004 (עיקרו) \u0003של גט\u0004 (שטר) \u0003שחרור\u0004 הוא הלשון: \u0003\"הרי אתה בן חורין\",\u0004 או \u0003\"הרי אתה לעצמך\".\u0004 ומכאן נלמד: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ומה עבד כנעני דקני ליה גופיה\u0004 \u0005[שקנוי לו\u0006 לאדון \u0005גופו]\u0006 של העבד, \u0003כי אמר ליה\u0004 \u0005[כאשר אומר לו]\u0006 האדון \u0003\"הרי אתה לעצמך\"\u0004 — שהוא לעצמו \u0003לגמרי קאמר ליה\u0004 \u0005[אומר לו]\u0006 ומשתחרר בכך, \u0003אשה\u0004 ש\u0003לא קני ליה\u0004 \u0005[קנוי לו\u0006 לבעלה\u0005]\u0006 \u0003גופה, לא כל שכן,\u0004 שמגרשה לגמרי?","ובאותו ענין \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: אמר לעבדו \"אין לי עסק בך\" מאי\u0004 \u0005[מה]\u0006 דינו? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 \u0003אין לי עסק בך\u0004 — \u0003לגמרי קאמר ליה\u0004 \u0005[אומר לו]\u0006 ושחררו בכך, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003למלאכה קאמר ליה\u0004 \u0005[אומר לו],\u0006 כלומר, שהוא משחרר אותו מן החובה לעשות לו מלאכה, אבל לא שחרר אותו מעצם העבדות?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לרב אשי ואמרי\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 שאמר \u0003לה\u0004 \u0005[זאת]\u0006 \u0003רב חנין מחוזאה לרב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו: \u0003המוכר עבדו לגוי\u0004 — \u0003יצא\u0004 העבד \u0003לחירות,\u0004 שקנסו את האדון משום שהוא מפקיע בכך את העבד מן המצוות, \u0003וצריך\u0004 העבד בכל זאת \u0003גט שחרור מרבו ראשון\u0004 כדי שייחשב כבן חורין לגמרי,","\u0003אמר רבן שמעון בן גמליאל\u0004 והוסיף על דין זה: \u0003במה דברים אמורים שלא כתב עליו\u0004 על העבד \u0003אונו\u0004 (שטר) כאשר מכרו לגוי, \u0003אבל\u0004 אם \u0003כתב עליו אונו\u0004 — \u0003זה\u0004 עצמו \u0003שחרורו.\u0004 שואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003אונו?\u0004 ומשיבים: \u0003אמר רב ששת: דכתב ליה\u0004 \u0005[שכותב לו]\u0006 \u0003\"כשתברח ממנו\u0004 — \u0003אין לי עסק בך\"\u0004 ומכאן משמע שלשון \"אין לי עסק בך\" היא לשון שחרור.","\u0003אמר אביי: המקדש\u0004 אשה \u0003במלוה\u0004 שהלווה בזמנו כסף לאשה ואומר לה שבסכום הזה שהלווה לה תתקדש לו — \u0003אינה מקודשת,\u0004 לפי שאינו יכול לקדש אלא במתן כסף או שווה כסף בשעת קידושין, ואף שהיא חייבת לו כסף, אין המלוה עתה כסף ממש אלא רק התחייבות מצד האשה, ובשעת קידושין בעצם אינו נותן לה דבר. אבל אם מקדשה \u0003בהנאת מלוה\u0004 שהלווה לה — \u0003מקודשת, ואסור לעשות כן מפני הערמת רבית,\u0004 שנמצא הבעל מרוויח דבר מן ההלוואה.","שהלווה ומבררים: \u0003האי\u0004 \u0005[זו]\u0006 \u0003הנאת מלוה, היכי דמי\u0004 \u0005[כיצד היא בדיוק]?\u0006 \u0003אילימא דאזקפה\u0004 \u0005[אם תאמר שזקף,\u0006 קבע \u0005עליה]\u0006 רבית בשעת ההלוואה, כגון ש\u0003אמר לה\u0004 שמלווה לה \u0003ארבע\u0004 מטבעות \u0003ב\u0004תמורה ל\u0003חמשה\u0004 שתתן לו בזמן הפרעון והוא מקדשה בשכר הויתור שמוותר לה על המטבע הנוסף — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003רבית מעלייתא הוא\u0004 \u0005[מעולה,\u0006 גמורה, \u0005היא]\u0006 ולא \"הערמת ריבית\" בלבד. \u0003ועוד,\u0004 כאשר מוותר לה על המטבע הנוספת, הרי מכל מקום הוא מוותר בכך רק על התחייבות שיש לה כלפיו, אבל אין הוא נותן לה דבר משלו, ואם כן \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003מלוה\u0004 שבו, כאמור, אינה מקודשת!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דארווח\u0004 \u0005[שריווח,\u0006 הרחיב, דחה\u0005]\u0006 \u0003לה זימנא\u0004 \u0005[\u0006את \u0005הזמן],\u0006 שהגיע זמן הפרעון בזמן מסויים, והוא אומר לה שבשכר ההנאה שיש לה, מדחיית זמן הפרעון, תתקדש לו, ואם כן נמצא שהוא מקדש אותה במה שנותן לה עכשיו.","\u0003אמר רבא:\u0004 אם אמר אדם לחבירו \u0003\"הילך\u0004 (הרי לך) \u0003מנה על מנת שתחזירהו לי\"; במכר,\u0004 אם נותן מנה זה על מנת לקנות בו דבר — \u0003לא קנה,\u0004 שהרי לא נתן למוכר דבר, וכן \u0003באשה\u0004 שנתן לה בקידושיה כסף על מנת להחזיר — \u0003אינה מקודשת, בפדיון הבן\u0004 שנתן לכהן דמי פדיון חמישה סלעים על מנת להחזיר — \u0003אין בנו פדוי,\u0004","ואם עשה כן \u0003בתרומה\u0004 שנתנה לכהן על מנת להחזיר \u0003יצא ידי נתינה\u0004 מעיקר הדין, וכאשר מקבל את התרומה בחזרה הריהי מעתה שלו ואף שאסור לו לאוכלה מפני קדושת תרומה — יכול הוא למוכרה לכהנים. \u0003ו\u0004אולם \u0003אסור לעשות כן\u0004 לכתחילה, \u0003מפני ש\u0004כהן זה \u0003נראה ככהן המסייע בבית הגרנות,\u0004 שמן הסתם ישלם לו בעל התרומה עבור שירות זה ונעשה ככהן העובד בגורן על מנת שיתנו לו תרומה, והרי הוא מבזה בכך את כבוד הכהונה.","לעיקרם של הדברים שואלים: \u0003מאי קסבר\u0004 \u0005[מה סבור]\u0006 \u0003רבא? אי קסבר\u0004 \u0005[אם סבור\u0006 הוא\u0005]\u0006 ש\u0003מתנה על מנת להחזיר שמה\u0004 (נחשבת) \u0003מתנה\u0004 — אם כן, לא רק בתרומה אלא \u0003אפילו כולהו נמי\u0004 \u0005[כולם\u0006 בכל שאר המקרים \u0005גם כן]\u0006 תחשב מתנה גמורה, \u0003ואי קסבר\u0004 \u0005[ואם סבור\u0006 הוא\u0005]\u0006 ש\u0003לא שמה מתנה\u0004 — \u0003אפילו\u0004 לענין \u0003תרומה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 תחשב כנתינה כלל.","\u0003ועוד, הא\u0004 \u0005[הרי]\u0006 \u0003רבא\u0004 עצמו \u0003הוא\u0004 ש\u0003אמר: מתנה על מנת להחזיר שמה מתנה!\u0004 ש\u0003אמר רבא:\u0004 האומר לחבירו \u0003\"הילך אתרוג זה על מנת שתחזירהו לי\"\u0004 ו\u0003נטלו\u0004 המקבל ובירך עליו \u0003והחזירו\u0004 — \u0003יצא\u0004 ידי חובה. \u0003ואם לאו\u0004 \u0005[לא]\u0006 החזירו — \u0003לא יצא,\u0004 שהרי לא ניתנה לו המתנה אלא על מנת שיחזיר. ומכל מקום משמע שלדעת רבא מתנה על מנת להחזיר שמה מתנה!","\u0003אלא אמר רב אשי: בכולהו קני\u0004 \u0005[בכולם\u0006 הוא \u0005קונה]\u0006 \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מאשה לפי שאין אשה נקנית בחליפין\u0004 אלא בקנין גמור. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמיה לרב אשי: הכי אמרינן משמיה\u0004 \u0005[כך אומרים אנו משמו]\u0006 של \u0003רבא כוותיך\u0004 \u0005[כשיטתך]\u0006 ולא כנוסח שאמרו תחילה.","\u0003אמר רבא:\u0004 אמרה אשה לאדם \u0003\"תן מנה לפלוני\u0004"],["\u0003ואקדש לך\",\u0004 במנה זה שאתה נותן לפלוני — הרי היא \u0003מקודשת,\u0004 וזאת למדנו \u0003מדין ערב.\u0004 כיצד? \u0003ערב, לאו אף על גב\u0004 \u0005[האם אף על פי]\u0006 ש\u0003לא מטי\u0004 \u0005[מגיעה]\u0006 \u0003הנאה לידיה\u0004 \u0005[לידו],\u0006 שהרי את כסף ההלוואה מקבל הלווה בכל זאת \u0003קא משעביד נפשיה\u0004 \u0005[הוא משעבד\u0006 את \u0005עצמו]\u0006 לתשלום החוב, \u0003האי איתתא נמי\u0004 \u0005[אשה זו גם כן]\u0006 \u0003אף על גב\u0004 \u0005[האם אף על פי]\u0006 ש\u0003לא מטי\u0004 \u0005[מגיעה]\u0006 \u0003הנאה לידה,\u0004 שהרי המנה ניתן לאחר — בכל אופן \u0003קא משעבדא ומקניא נפשה\u0004 \u0005[היא משעבדת ומקנה\u0006 את \u0005עצמה].\u0006","נתן אדם מנה לאשה ואמר לה \u0003\"הילך\u0004 (הרי לך) \u0003מנה והתקדשי\u0004 במנה זה \u0003לפלוני\"\u0004 — \u0003מקודשת,\u0004 וזאת למדנו \u0003מדין\u0004 שחרור \u0003עבד כנעני.\u0004 שאדם אחר נותן לאדוניו כסף והוא משתחרר, ואם כן \u0003עבד כנעני, לאו אף על גב\u0004 \u0005[האם אף על פי]\u0006 \u0003דלא קא\u0004 \u0005[ש\u0006הוא עצמו \u0005אינו]\u0006 \u0003חסר ולא מידי\u0004 \u0005[דבר,\u0006 כלום\u0005]\u0006 ואינו נותן כלום משלו — בכל זאת \u0003קא קני נפשיה\u0004 \u0005[הוא קונה\u0006 את \u0005עצמו]\u0006 ומשתחרר, \u0003האי גברא נמי אף על גב דלא קא\u0004 \u0005[אדם זה,\u0006 האיש השלישי, \u0005אף על פי שאינו]\u0006 \u0003חסר ולא ולא\u0004 \u0005[דבר,\u0006 כלום\u0005]\u0006 — \u0003קא קני לה להאי איתתא\u0004 \u0005[הוא\u0006 \u0005קונה את האשה הזו]\u0006 על ידי נתינת האחר, אף על פי שהוא עצמו אינו נותן דבר.","אמרה אשה לאיש \u0003\"תן מנה לפלוני ואקדש אני לו\"\u0004 לאותו אדם, אם נתן — \u0003מקודשת, מדין שניהם,\u0004 כלומר, מדין ערב ומדין עבד כנעני. כיצד? \u0003ערב, לאו אף על גב דלא קא מטי\u0004 \u0005[אף על פי שאין מגיעה]\u0006 \u0003הנאה לידיה\u0004 \u0005[לידו]\u0006 \u0003קא\u0004 \u0005[הריהו]\u0006 \u0003משעבד נפשיה\u0004 \u0005[\u0006את \u0005עצמו],\u0006 \u0003האי איתתא נמי אף על גב דלא קא מטי\u0004 \u0005[אשה זו גם כן אף על פי שאין מגיעה]\u0006 \u0003הנאה לידה\u0004 — \u0003קא מקניא נפשה\u0004 \u0005[הריהי מקנה\u0006 את \u0005עצמה].\u0006","אלא שזה לא מספיק, שכן יש להקשות: \u0003מי דמי\u0004 \u0005[האם\u0006 הדבר \u0005דומה]?\u0006 הרי ב\u0003ערב, האי דקא קני ליה קא חסר ממונא\u0004 \u0005[זה\u0006 המלווה \u0005שקונה אותו,\u0006 את השיעבוד של הערב, \u0005חסר\u0006 אותו \u0005ממון]\u0006 שהלווה ללווה, ועל ידי כך קנה את השיעבוד של הערב, ואולם \u0003האי גברא קא קני לה להאי איתתא ולא קא\u0004 \u0005[אדם זה\u0006 האיש השלישי \u0005קונה את האשה הזו ואינו\u0006\u0005]\u0006 \u0003חסר ולא מידי\u0004 \u0005[דבר,\u0006 כלום\u0005]\u0006 מעצמו ולכן צריך להוסיף: שחרור \u0003עבד כנעני יוכיח, דלא קא\u0004 \u0005[שאינו]\u0006 \u0003חסר ממונא\u0004 \u0005[ממון]\u0006 משלו \u0003וקא קני נפשיה\u0004 \u0005[ו\u0006בכל זאת \u0005קונה\u0006 את \u0005עצמו].\u0006","ומעבד כנעני לבד גם כן אי אפשר ללמוד לענייננו, שכן \u0003מי דמי\u0004 \u0005[האם דומה\u0006 הדבר\u0005]?\u0006 \u0003התם הך דקא מקני\u0004 \u0005[שם,\u0006 בעבד, \u0005זה שמקנה]\u0006 — \u0003קא קני\u0004 — \u0005[הוא קונה]\u0006 שבעל העבד המקנה לו את עצמו קונה באותה שעה ממון מן הנותן, ואולם \u0003הכא האי איתתא קא מקניא נפשה ולא קא קניא ולא מידי\u0004 \u0005[כאן אשה זו מקנה\u0006 את \u0005עצמה ואינה קונה דבר]!\u0006 אלא שלענין זה \u0003ערב יוכיח, אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא קא מטי\u0004 \u0005[מגיעה]\u0006 \u0003הנאה לידיה\u0004 \u0005[לידו]\u0006 הריהו \u0003משעבד נפשיה\u0004 \u0005[\u0006את \u0005עצמו],\u0006 ומצירוף שני הדינים למדנו על האשה שמקודשת.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 אם אמרה אשה לאיש \u0003\"הילך\u0004 (הרי לך) \u0003מנה ואקדש אני לך\" מהו? אמר מר זוטרא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב פפא: מקודשת. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי למר זוטרא: אם כן הוה ליה\u0004 \u0005[הרי,\u0006 נמצא\u0005]\u0006 ש\u0003נכסים שיש להם אחריות\u0004 (ואדם, כגון עבד, נחשב נכסים שיש להם אחריות ודינו כדין קרקע) \u0003נקנין עם נכסים שאין להם אחריות\u0004 (מטלטלין).","שהרי אגב שקנה את הכסף לעצמו קונה גם את האשה, \u0003ואנן איפכא תנן\u0004 \u0005[ו\u0006הרי \u0005אנו בהיפך שנינו\u0006 במשנה\u0005]:\u0006 \u0003נכסים שאין להם אחריות נקנין עם נכסים שיש להם אחריות בכסף בשטר ובחזקה,\u0004 אבל לא להיפך, שנכסים שיש להם אחריות ייקנו ב\"קנין אגב\"! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי סברת דאמרה ליה\u0004 \u0005[האם אתה סבור ש\u0006מדובר באופן \u0005שהיא אומרת לו]\u0006 בלשון \u0003\"\u0004קנין \u0003אגב\"\u0004 שאגב קנין הכסף יקנה גם אותה? \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003באדם חשוב עסקינן\u0004 \u0005[אנו עוסקים]\u0006 \u0003דבההיא\u0004 \u0005[שבאותה]\u0006 \u0003הנאה\u0004 שיש לה \u0003דקא\u0004 \u0005[שהוא]\u0006 \u0003מקבל מתנה מינה\u0004 \u0005[ממנה]\u0006 \u0003גמרה ומקניא ליה נפשה\u0004 \u0005[היא גומרת\u0006 בליבה \u0005ומקנה לו\u0006 את \u0005עצמה].\u0006","\u0003איתמר נמי משמיה\u0004 \u0005[נאמר גם כן משמו]\u0006 של \u0003רבא: וכן לענין ממונא\u0004 \u0005[ממון]\u0006 יש קנין באופנים אלה שלמדנו מדין ערב ועבד כנעני. ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמר הדבר גם בקידושין וגם בממון, משום","\u0003דאי אשמועינן\u0004 \u0005[שאילו היה משמיע לנו]\u0006 רק ב\u0003קידושין\u0004 היינו אומרים שכך הוא הדין דווקא בקידושין \u0003משום דהא איתתא ניחא\u0004 \u0005[שאשה זו נוח]\u0006 \u0003לה\u0004 להתקדש \u0003בכל\u0004 דבר \u0003דהו\u0004 \u0005[שהוא]\u0006 \u0003וכ\u0004דברי \u0003ריש לקיש.\u0004 ש\u0003אמר ריש לקיש\u0004 פתגם שאומרות הנשים: \u0003\"טב למיתב טן דו מלמיתב ארמלו\"\u0004 \u0005[טוב לשבת בשני גופים מלשבת אלמנה,\u0006 בודדה\u0005],\u0006 שאשה מעדיפה בן זוג כלשהו על פני בדידות ולכן אף בהנאה כלשהי מקנה את עצמה לקידושין. \u0003אבל\u0004 לענין \u0003ממונא\u0004 \u0005[ממון]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יועיל קנין כזה.","\u0003ו\u0004להיפך, \u0003אי אשמועינן ממונא\u0004 \u0005[ואם היה משמיע לנו\u0006 רק לגבי \u0005ממון]\u0006 היינו אומרים שכך הוא הדין דווקא בממון \u0003משום דאיתיהיב\u0004 \u0005[ש\u0006הוא \u0005ניתן]\u0006 \u0003למחילה,\u0004 שיכול אדם לתת או למחול ממונו הנמצא ביד אחר בלא לקבל כל תמורה \u0003אבל\u0004 ב\u0003קידושין\u0004 שאינם תלויים לגמרי ברצון האשה ובהסכמתה, וצריכה לקבל את כסף קידושיה \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יועיל דין ערב ועבד כנעני, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 הדבר להיאמר בשני המקרים.","\u0003אמר רבא:\u0004 האומר לאשה \u0003\"התקדשי לי לחציי\"\u0004 — הרי היא \u0003מקודשת.\u0004 אבל אם אמר לה \u0003\"חצייך מקודשת לי\"\u0004 — \u0003אינה מקודשת.\u0004 הקשה ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבא: מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003\"חצייך מקודשת לי\"\u0004 ש\u0003אינה מקודשת\u0004 — משום ש\u0003\"אשה\" אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 \u0003ולא חצי אשה.\u0004 אם כן \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003\"איש\" אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 \u0003ולא חצי איש!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003הכי השתא\u0004 \u0005[איך אתה משווה]?!\u0006 \u0003התם, איתתא לבי תרי לא חזיא\u0004 \u0005[שם, אשה לשנים אינה ראויה]\u0006 ואם קונה חצי אשה פירושו של דבר שהוא משייר את החצי השני לאחר — וזה אינו יכול לעשות, שאין אשה נישאת לשני גברים, \u0003אלא גברא מי לא חזי לבי תרי\u0004 \u0005[איש האם אינו ראוי לשתי\u0006 נשים\u0005]?\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמר]\u0006 \u0003לה,\u0004 כך התכוון כשאמר \"את מקודשת לחציי\" — \u0003דאי בעינא למינסב אחריתי\u0004 \u0005[שאם אני רוצה לשאת\u0006 אשה \u0005אחרת]\u0006 — \u0003נסיבנא\u0004 \u0005[אשא].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי לרבינא:\u0004 במקרה שאומר לה \"חצייך מקודשת לי\" \u0003וניפשטו לה קידושי\u0004 \u0005[ויתפשטו הקידושין]\u0006 \u0003בכולה\u0004 ותהיה מקודשת כולה? \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר\u0004 על בהמה \u0003\"רגלה של זו עולה\"\u0004 — הרי \u0003תהא כולה עולה,\u0004 שהקדושה שהיתה בחלקה, מתפשטת על כל הבהמה כולה.","\u0003ו\u0004עוד, \u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003אין כולה עולה, הני מילי היכא\u0004 \u0005[דברים אלו\u0006 אמורים דווקא \u0005במקום]\u0006 ש\u0003מקדיש\u0004 את רגלה, שהוא \u0003דבר שאין הנשמה תלויה בו,\u0004 שהרי אפשר לחתוך את רגלה ותחיה, \u0003אבל\u0004 אם \u0003מקדיש דבר שהנשמה תלויה בו\u0004 — \u0003הויא\u0004 \u0005[הרי היא]\u0006 \u0003כולה עולה\u0004 לדעת הכל. ואף כאן, כיון שחציה הוא דבר שהנשמה תלויה בו — מדוע לא יתפשטו הקידושין בכולה?","ודוחים: \u0003מי דמי\u0004 \u0005[האם\u0006 הדברים \u0005דומים]?\u0006 \u0003התם\u0004 \u0005[שם\u0006 מדובר\u0005]\u0006 ב\u0003בהמה\u0004 שהיא בריה שאין בה דעת ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 הלא הדבר תלוי גם ב\u0003דעת אחרת,\u0004 דעת האשה עצמה, והאשה צריכה לגלות דעתה שיתפשט בה קנין הקידושין.","\u0003הא לא דמיא\u0004 \u0005[זו אינה דומה]\u0006 \u0003אלא להא\u0004 \u0005[ל\u0006הלכה \u0005זו]\u0006 ש\u0003אמר ר' יוחנן: בהמה של שני שותפין,\u0004 אם \u0003הקדיש\u0004 אחד מן השותפים את \u0003חציה\u0004 השייך לו, \u0003וחזר ולקחה\u0004 (קנה את חציה האחר) משותפו \u0003והקדישה\u0004 — הרי זו \u0003קדושה,\u0004 משום שבסופו של דבר הקדיש אותה בשלימות בשתי פעמים. \u0003ו\u0004בכל זאת \u0003אינה קריבה\u0004 משום שבשעה שהקדישה בראשונה — לא היתה ראויה להקרבה, ולא התפשטה קדושה בכולה, משום שהיה צורך בדעת השותף האחר ואין לה תקנה.","אבל כיון שהיא מוקדשת עתה, הרי קדושה שבה מספיקה כדי שתהיה בהמה זו \u0003עושה תמורה,\u0004 שאם המיר בה בהמת חולין — הרי גם הבהמה האחרת נתפסת בקדושה, \u0003ו\u0004אולם \u0003תמורתה כיוצא בה,\u0004 שאף התמורה היא קדושה ואינה קריבה.","ומהלכה זו \u0003שמע מינה תלת\u0004 \u0005[למד ממנה שלושה\u0006 דברים\u0005]:\u0006"],["\u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 ש\u0003בעלי חיים נדחים,\u0004 שקרבנות שנדחו מפני טעם כלשהו מלהיקרב על גבי המזבח אף בהיותם חיים, שוב אינם יכולים ליקרב, ואף כאן כשהקדיש רק חציה לא היתה יכולה להיקרב ונדחית, ולא כדעת הסבורים שאין דין דחיה אלא בקרבנות שנשחטו בלבד,","\u0003ושמע מינה\u0004 \u0005[ולמד ממנה\u0006 עוד\u0005]\u0006 כי \u0003דחוי מעיקרא הוי דחוי\u0004 \u0005[\u0006דבר ש\u0005דחוי מתחילה,\u0006 כלומר, מראשית הקדשתו, \u0005הריהו\u0006 נחשב \u0005לדחוי],\u0006 ואין אומרים שאין דין דחיה אלא בדבר שהיה ראוי קודם לכן ואחר כך נדחה, \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003יש דחוי בדמים\u0004 בדבר שלא נתקדש בקדושת הגוף אלא שדמיו יהיו עבור קרבן, שהרי כשהקדיש חצי בהמה הקדישה רק לדמיה, שהרי אי אפשר לו להקריב חצי בהמה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 אמר לאשה \u0003\"\u0004הרי \u0003חצייך\u0004 מקודשת \u0003בחצי פרוטה, וחצייך בחצי פרוטה\" מהו?\u0004 האם לומר \u0003כיון\u0004 ש\u0003אמר לה\u0004 ב\u0003חצי פרוטה\u0004 — \u0003פסקה\u0004 \u0005[חתך אותה],\u0006 כלומר, רצה שיחולו קידושין בשני חצאי פרוטה דווקא, וחצי פרוטה אינו מועיל, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003מונה והולך הוא,\u0004 שכוונתו היתה לפרוטה אלא שהיה מונה חצי פרוטה ועוד חצי פרוטה, ושני החצאים מצטרפים.","\u0003אם תימצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 כי \u0003מונה והולך הוא,\u0004 אם אמר לה \u0003\"חצייך בפרוטה וחצייך בפרוטה\" מהו?\u0004 האם לומר כי \u0003כיון\u0004 ש\u0003אמר לה בפרוטה ופרוטה\u0004 — \u0003פסקה למילתיה\u0004 \u0005[פסק,\u0006 חתך, \u0005את דבריו]\u0006 ונתכוון לקדש כל חצי ממנה בפני עצמו, וכאמור \"חצי אשה\" אינה מתקדשת, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003כל\u0004 דבר שעושה \u0003ביומיה\u0004 \u0005[ביומו,\u0006 באותו יום\u0005]\u0006 \u0003מונה והולך הוא\u0004 והרי הוא כאילו אמר לה שהיא מקודשת בשתי פרוטות.","\u0003אם תימצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 כי \u0003כל\u0004 דבר שעושה \u0003ביומיה\u0004 \u0005[ביומו]\u0006 \u0003מונה והולך הוא,\u0004 אם אמר לה \u0003\"חצייך בפרוטה היום וחצייך בפרוטה למחר\" מהו?\u0004 האם \u0003כיון\u0004 ש\u0003אמר לה למחר\u0004 — \u0003פסקה\u0004 \u0005[חתך אותה]\u0006 ואין לצרף עוד, \u0003או דילמא הכי קאמר\u0004 \u0005[שמא כך אמר]\u0006 \u0003לה: קדושין מתחלו מהאידנא\u0004 \u0005[מתחילים מעכשיו]\u0006 \u0003ומגמר\u0004 \u0005[ולהגמר]\u0006 \u0003לא ניגמרו\u0004 \u0005[ייגמרו]\u0006 אלא \u0003עד למחר.\u0004","ועוד יש לשאול: אם אמר לה \u0003\"שני חצייך בפרוטה\" מהו? הכא\u0004 \u0005[כאן]\u0006 \u0003ודאי בחד זימנא קאמר\u0004 \u0005[בפעם אחת אמר]\u0006 \u0003לה,\u0004 ולכאורה קידושיו קידושין, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003אין אשה מתקדשת לחצאין כלל.\u0004 לכל השאלות הללו לא נמצא פתרון, ולכן \u0003תיקו\u0004 \u0005[תעמודנה]\u0006 במקומן.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 אמר לחבירו: \u0003\"שתי בנותיך\u0004 הקטנות מקודשות \u0003לשני בני בפרוטה\" מהו\u0004 הדין? וצדדי השאלה: האם \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003נותן ומקבל אזלינן\u0004 \u0005[הולכים אנו]\u0006 ומכיון שגם הנותן נותן פרוטה וגם המקבל מקבל פרוטה \u0003והאיכא ממונא\u0004 \u0005[והרי יש כאן ממון],\u0006 שהרי פרוטה נחשבת לממון, \u0003או דילמא בתר דידהו אזלינן\u0004 \u0005[שמא אחריהם,\u0006 אחרי הנוגעים בדבר, הבנים המקדשים והבנות המתקדשות \u0005אנו הולכים]\u0006 \u0003והא ליכא\u0004 \u0005[והרי אין]\u0006 כאן פרוטה לכל אחד ואחד מהם? שאלה זו לא נפתרה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 אמר לחבירו: \u0003\"בתך\u0004 \u0003ופרתך בפרוטה\" מהו? מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 כי כוונתו היתה \u0003בתך\u0004 תתקדש \u0003בחצי פרוטה ופרתך\u0004 תיקנה \u0003בחצי פרוטה\u0004 — ואין כאן לא קידושין ולא קנין בכסף, \u0003או דילמא\u0004 \u0005[שמא]\u0006 כוונתו היתה כי \u0003בתך\u0004 תתקדש \u0003בפרוטה ופרתך\u0004 תיקנה \u0003במשיכה?\u0004 ואף לשאלה זו לא נמצא פתרון ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 אמר \u0003\"בתך וקרקעך בפרוטה\" מהו?\u0004 האם הכוונה היא \u0003בתך בחצי פרוטה וקרקעך בחצי פרוטה, או דילמא\u0004 \u0005[שמא]\u0006 הכוונה בדבריו היא \u0003בתך בפרוטה וקרקעך בחזקה?\u0004 אף שאלה זו לא נפתרה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 אף היא במקומה.","מסופר: \u0003ההוא גברא דאקדיש בשיראי\u0004 \u0005[\u0006מעשה \u0005באדם אחד שקידש\u0006 אשה \u0005ב\u0006בגדי \u0005משי],\u0006 \u0003רבה אמר: לא צריכי שומא\u0004 \u0005[אינם צריכים הערכה]\u0006 לפני נתינתם, שבודאי שווים הם יותר מפרוטה. \u0003רב יוסף אמר: צריכי שומא\u0004 \u0005[צריכים הערכה]\u0006 וכיון שלא העריכום קודם נתינתם — אין הקידושין תופשים. ומעירים: \u0003אי דאמר\u0004 \u0005[אם שאמר]\u0006 \u0003לה בכל דהו\u0004 \u0005[בכלשהו],\u0006 כלומר, שהוא מקדש אותה בשיראין אלה בלי לקבוע להם ערך, \u0003כולי עלמא לא פליגי דלא צריכי שומא\u0004 \u0005[הכל אינם חולקים שאינם צריכים הערכה],\u0006 שהרי ודאי שווים יותר מפרוטה.","ומצד שני \u0003אי דאמר\u0004 \u0005[אם שאמר]\u0006 \u0003לה\u0004 שהם שווים \u0003\"חמשין\"\u0004 \u0005[חמישים]\u0006 דינר \u0003ולא שוו חמשין\u0004 \u0005[ואינם שווים חמישים]\u0006 — \u0003הא לא שוו\u0004 \u0005[הרי אינם שווים]\u0006 ואין כאן קידושין לדעת הכל. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו],\u0006 הרי זה במקרה ש\u0003אמר\u0004 ששווים \u0003חמשין\u0004 \u0005[חמישים]\u0006 \u0003ו\u0004באמת \u0003שוו חמשין\u0004 \u0005[שווים חמישים].\u0006 \u0003רבה אמר: לא צריכי שומא\u0004 \u0005[אינם צריכים הערכה]\u0006 לפני הקידושין \u0003דהא שוו חמשין\u0004 \u0005[שהרי\u0006 הם \u0005שווים\u0006 באמת \u0005חמישים].\u0006 \u0003רב יוסף אמר: צריכי שומא\u0004 \u0005[צריכים הערכה]\u0006 לפני הקידושין ומדוע? \u0003כיון דאיתתא\u0004 \u0005[שהאשה]\u0006 עצמה \u0003לא בקיאה בשומא\u0004 \u0005[בהערכה]\u0006 \u0003לא סמכה דעתה\u0004 \u0005[אין דעתה סומכת\u0006 על הדבר\u0005]\u0006 ומפני שאינה בטוחה שהיו שווים באמת חמישים — לא גמרה בדעתה להתקדש.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שאפילו אם אמר לה התקדשי לי בשיראים אלו \u0003בכל דהו\u0004 \u0005[בכל\u0006 סכום \u0005שהוא]\u0006 שהם שווים \u0003נמי פליגי\u0004 \u0005[גם כן חלוקים\u0006 הם\u0005]\u0006 אם קידשה בשיראים אלה סתם. וטעם המחלוקת, \u0003רב יוסף אמר: שוה כסף הרי הוא ככסף\u0004 לכל דבר, \u0003מה כסף דקיץ\u0004 \u0005[ש\u0006הוא \u0005קצוב]\u0006 ושיש לו ערך קבוע ומסויים"],["\u0003אף שוה כסף נמי דקייץ\u0004 \u0005[גם כן ש\u0006הוא \u0005קצוב].\u0006","\u0003אמר רב יוסף: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה]\u0006 את הסברה הזו — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר בענין פדיון עבד עברי \u0003\"מכסף מקנתו\"\u0004 (ויקרא כה, נא) ללמדנו: דווקא \u0003בכסף הוא נקנה ואינו נקנה בתבואה וכלים.\u0004","ונברר: \u0003האי\u0004 \u0005[\u0006מקרה \u0005זה]\u0006 של \u0003תבואה וכלים היכי דמי\u0004 \u0005[כיצד בדיוק]\u0006 מדובר כאן? \u0003אילימא דלא מקנו בהו\u0004 \u0005[אם תאמר שאין מקנים בהם]\u0006 \u0003כלל\u0004 אלא בכסף בלבד, הלא \u0003\"ישיב גאלתו\"\u0004 (שם) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 והביטוי בא \u0003לרבות\u0004 כל דרך של השבה וגם כל דבר \u0003שוה כסף\u0004 שיהא דינו \u0003ככסף,\u0004 שאין צורך לשלם בכסף דווקא אלא אפשר גם בשווה כסף.","\u0003ואי דלית בהו\u0004 \u0005[ואם\u0006 תאמר משום \u0005שאין בהם]\u0006 \u0003שוה פרוטה, מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003תבואה וכלים? אפילו כסף נמי\u0004 \u0005[גם כן]\u0006 אם אין בו שווה פרוטה אינו קונה! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 מדובר פה באופן \u0003דאית בהו\u0004 \u0005[שיש בהם]\u0006 \u0003שוה פרוטה, וכיון דלא קייצי\u0004 \u0005[שאינם קצובים]\u0006 \u0003לא\u0004 ניתן לפדות בהם עבד עברי. שמן ההשוואה לכסף נלמד שיכול הוא להפדות רק בדבר שיש לו ערך קצוב, ככסף.","\u0003ואידך\u0004 \u0005[ו\u0006החכם \u0005האחר],\u0006 רבה, הסובר שאין צריכים שומא, אומר: אכן מדובר פה ב\"שוה פרוטה\" אך לא בא התנא ללמדנו שאין פודים בדברים שאינם קצובים אלא \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003בתורת כסף הוא נקנה, ואין נקנה בתורת תבואה וכלים, ומאי נינהו\u0004 \u0005[ומה הם]\u0006 הדרכים שמיוחדות לקנות בהן על ידי תבואה וכלים — קנין \u0003חליפין,\u0004 ומלמדנו התנא שאין העבד נקנה בחליפין.","ושואלים: הסבר זה נכון לפי השיטה שתבואה קונה בחליפין בדרך כלל, \u0003ו\u0004אולם \u0003ל\u0004דעת \u0003רב נחמן\u0004 ש\u0003אמר: פירות לא עבדי\u0004 \u0005[אינן עושים]\u0006 \u0003חליפין,\u0004 שאין חליפין אלא בכלים, אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 מדוע הזכיר התנא תבואה והרי תבואה אינה עושה חליפין? \u0003אלא\u0004 יש לחזור מהסבר זה ולפרש אחרת: \u0003לעולם\u0004 מדובר באופן \u0003דלית בהו\u0004 \u0005[שאין בהם]\u0006 בתבואה וכלים אלה \u0003שוה פרוטה. ודקאמרת מאי איריא\u0004 \u0005[ומה שאתה אומר, מה שייך\u0006 מדוע דווקא\u0005]\u0006 \u0003תבואה וכלים\u0004 שהזכיר, והרי \u0003אפילו כסף נמי\u0004 \u0005[גם כן]\u0006 בפחות משווה פרוטה לא יקנה? יש לומר כי בסגנון של \u0003לא מיבעיא קאמר\u0004 \u0005[\"לא נצרכה\" אמר]\u0006 וכך יש להבין את הדברים:","\u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 אין צורך לומר ב\u0003כסף דאי אית ביה\u0004 \u0005[שאם יש בו]\u0006 \u0003שוה פרוטה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אפשר לקנות בו, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא, אבל תבואה וכלים אימא\u0004 \u0005[אמור]\u0006 \u0003מדמקרבא הנאתייהו\u0004 \u0005[מ\u0006כיון \u0005שקרובה הנאתם\u0006\u0005],\u0006 שיכול המקבלם ליהנות מהם מיד כפי שהם, שמא \u0003גמר ומקני נפשיה\u0004 \u0005[גומר ומקנה\u0006 העבד את \u0005עצמו]\u0006 אפילו בפחות משווה פרוטה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל מקרה אין קנין בפחות משווה פרוטה.","ועוד \u0003אמר רב יוסף: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה]\u0006 את הסברה שקידושין הם דווקא בדבר שערכו קצוב — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 האומר לכהן \u0003\"עגל זה\u0004 יהיה \u0003לפדיון בני\",\u0004 או \u0003\"טלית זה\u0004 תהא \u0003לפדיון בני\"\u0004 — \u0003לא אמר כלום,\u0004 אבל אם אמר \u0003\"עגל זה ב\u0004שווי של \u0003חמש סלעים\u0004 יהיה \u0003לפדיון בני\"\u0004 או \u0003\"טלית זו ב\u0004שווי של \u0003חמש סלעים\u0004 תהא \u0003לפדיון בני\"\u0004 — \u0003בנו פדוי.\u0004","ומעתה נברר: \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003פדיון,\u0004 בעגל או טלית שלא קצב את דמיהם, \u0003היכי דמי\u0004 \u0005[\u0006\u0005כיצד היה בדיוק]?\u0006 \u0003אילימא דלא שוי\u0004 \u0005[אם תאמר שאינו שווה]\u0006 חמישה סלעים, \u0003כל כמיניה\u0004 \u0005[וכי בכוחו]\u0006 לתת לכהן פחות מהשיעור הקצוב? ומדוע בסיפא כשקצב את הסכום בנו פדוי! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 מדובר פה \u0003אף על גב דשוי\u0004 \u0005[אף על פי שהם שווים]\u0006 סכום זה, \u0003ו\u0004אולם ברישא \u0003כיון דלא קייצי\u0004 \u0005[שאינם קצובים]\u0006 \u0003לא\u0004 יפדו בהם. הרי שיש לחלק בין דבר שיש לו מחיר קצוב לזה שאין לו ערך כזה.","ודוחים: \u0003לא, לעולם דלא שוי\u0004 \u0005[בכלל\u0006 מדובר באופן \u0005שאינם שווים\u0006 העגל או הטלית\u0005]\u0006 חמישה סלעים \u0003ו\u0004בסיפא מדובר \u0003כגון דקביל\u0004 \u0005[שקיבל]\u0006 ה\u0003כהן עילויה\u0004 \u0005[עליו]\u0006 ואמר שעבורו שווים אלה הדברים סכום זה ולפיכך בנו פדוי. \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב כהנא\u0004 שהיה כהן \u0003שקיל סודרא מבי\u0004 \u0005[נטל סודר מבית]\u0006 אדם שהיה חייב ב\u0003פדיון הבן, אמר ליה\u0004 \u0005[לו]\u0006 לנותן: \u0003לדידי חזי\u0004 \u0005[עבורי ראוי,\u0006 שווה\u0005]\u0006 \u0003לי\u0004 סודר זה כאילו היה מחירו \u0003חמש סלעים.\u0004","\u0003אמר רב אשי: לא אמרן\u0004 \u0005[אמרנו]\u0006 שאפשר לפדות בדרך זו \u0003אלא\u0004 באיש \u0003כגון רב כהנא דגברא רבה\u0004 \u0005[שאדם גדול]\u0006 \u0003הוא ומבעי ליה סודרא ארישיה\u0004 \u0005[וצריך הוא סודר על ראשו],\u0006 שכך היתה דרכם של אנשים חשובים, \u0003אבל כולי עלמא\u0004 \u0005[כל העולם,\u0006 סתם אנשים\u0005]\u0006 שאינם זקוקים לסודר ואינם יכולים לומר שסודר שווה בעיניהם סכום כזה \u0003לא\u0004 יפדו בדרך שכזו. ומביאים ראיה שאדם חשוב הזקוק לסודר משלם הרבה עבורו \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003מר בר רב אשי זבן סודרא מאימיה\u0004 \u0005[קנה סודר מאמו]\u0006 של \u0003רבה מ\u0004המקום \u0003קובי\u0004 שהיה \u0003שוי\u0004 \u0005[שווה]\u0006 \u0003עשרה\u0004 דינרים \u0003בתליסר\u0004 \u0005[\u0006\u0005בשלשה עשר]\u0006 משום שהיה זקוק לסודר.","\u0003אמר ר' אלעזר:\u0004 אמר לאשה \u0003\"התקדשי לי במנה\"\u0004 (מאה דינר) \u0003ונתן לה דינר\u0004 אחד מן המנה — \u0003הרי זו מקודשת\u0004 מיד, \u0003וישלים\u0004 לאחר זמן את המותר שהתחייב בו. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 דבר זה? — \u0003כיון\u0004 ש\u0003אמר לה\u0004 \"ב \u0003מנה\" ויהב\u0004 \u0005[ונתן]\u0006 \u0003לה דינר\u0004 — \u0003כמאן דאמר\u0004 \u0005[כמי שאמר]\u0006 \u0003לה:\u0004 התקדשי לי \u0003\"על מנת\"\u0004 שאתן לך מנה \u0003דמי\u0004 \u0005[נחשב\u0006 הוא\u0005],\u0006 כלומר, שהוא מקדשה עכשיו בדינר, על תנאי שישלים מנה בעתיד, ולכן חלים הקידושין מיד אלא שצריך להשלים את המנה.","\u0003ו\u0004כפי ש\u0003אמר רב הונא אמר רב: כל\u0004 \u0003האומר \"על מנת\" כאומר \"מעכשיו\" דמי\u0004 \u0005[נחשב],\u0006 שהסכם בנוסח של \"על מנת\" משמעו שההסכם חל מיד, אלא שצריך לקיים את התנאי, ואינו כתנאי רגיל שההסכם חל רק אחר מילוי התנאי.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 מברייתא: אמר לאשה \u0003\"התקדשי לי במנה\", והיה מונה והולך\u0004 (ממשיך וסופר) את הכסף, \u0003ורצה אחד מהן לחזור\u0004 מהקידושין \u0003אפילו בדינר האחרון\u0004 — \u0003הרשות בידו.\u0004 משמע שאין הקידושין חלים אלא עד שישלים את המנה כולו!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 כגון \u0003דאמר\u0004 \u0005[שאומר]\u0006 לאשה \u0003\"\u0004התקדשי לי \u0003במנה זו\"\u0004 ואז המנה כולו הוא כסף הקידושין ולא רק הדינר הראשון. ומקשים על תשובה זו: \u0003הא מדסיפא\u0004 \u0005[הרי מ\u0006כיון \u0005שסופה\u0006 של הברייתא\u0005]\u0006 מדבר \u0003\"במנה זו\",\u0004 אם כן \u0003רישא\u0004 \u0005[בתחילתה\u0006 מדובר\u0005]\u0006 \u0003במנה סתם.\u0004","\u0003דקא תני סיפא\u0004 \u0005[ששנה בסופה]\u0006 של אותה ברייתא: \u0003אמר לה\u0004 לאשה \u0003\"התקדשי לי במנה זו\", ונמצא מנה חסר דינר, או\u0004 היה בו \u0003דינר של נחשת\u0004 ולא מכסף — \u0003אינה מקודשת.\u0004 אם היה \u0003דינר רע,\u0004 כלומר, שהיה דינר כסף, אלא שהיה שחוק עד שאין מקבלים אותו בכל מקום ברצון — \u0003הרי זו מקודשת,\u0004 שהרי נתן לה מנה, \u0003ויחליף\u0004 ויתן דינר אחר. ומכך שדורש לשון \"מנה זו\" בסוף הברייתא, יש להבין שבתחילה הכוונה למנה סתם.","ודוחים: \u0003לא,\u0004 אפשר לומר \u0003רישא וסיפא\u0004 \u0005[\u0006ב\u0005תחילתה וסופה]\u0006 מדובר באופן ש\u0003אמר \"במנה זו\", ופרושי קא מפרש\u0004 \u0005[ומפרש הוא]\u0006 את הדברים: \u0003רצה אחד מהן לחזור אפילו בדינר האחרון\u0004 — \u0003הרשות בידו. כיצד\u0004 — \u0003כגון\u0004 ש\u0003אמר לה \"במנה זו\".\u0004","ומעירים: \u0003והכי נמי מסתברא\u0004 \u0005[וכך גם כן מסתבר]\u0006 לפרש, \u0003דאי סלקא דעתך רישא\u0004 \u0005[שאם עולה על דעתך שבתחילה\u0006 מדובר\u0005]\u0006 \u0003במנה סתם, השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אם \u0003במנה סתם לא הוו קידושי\u0004 \u0005[אין הם קידושין]\u0006 ויכולה לחזור בה, אם כן \u0003\"במנה זו\" מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שיכולה לחזור בה? והסיפא מיותרת!","את ההוכחה הזו דוחים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום הא\u0004 \u0005[זה]\u0006 \u0003לא איריא\u0004 \u0005[שייך]\u0006 ואין זו ראיה, שכן אפשר לומר: \u0003תנא סיפא לגלוי רישא\u0004 \u0005[שנה\u0006 את \u0005סופה\u0006 כדי \u0005לגלות\u0006 את משמעות \u0005תחילתה],\u0006 \u0003שלא תאמר רישא\u0004 \u0005[תחילתה]\u0006 מדובר שאמר \u0003\"במנה זו\", אבל במנה סתם הוו\u0004 \u0005[הריהם]\u0006 \u0003קידושין,\u0004 לכן \u0003תנא סיפא\u0004 \u0005[שנה בסוף]\u0006 \u0003\"במנה זו\",\u0004 ונלמד מכאן ו\u0003מכלל\u0004 זה נלמד \u0003דרישא\u0004 \u0005[שבראשה]\u0006 היא מדברת \u0003במנה סתם, ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003לא הוו\u0004 \u0005[אינם]\u0006 \u0003קידושין.\u0004","\u0003רב אשי אמר:\u0004 אין צורך לומר שמדובר בברייתא באופן שאמר \"מנה זו\", אלא אם היה \u0003מונה והולך שאני\u0004 \u0005[שונה],\u0006 \u0003דדעתה אכוליה\u0004 \u0005[שדעתה על\u0006 המנה \u0005כולו],\u0006 שכיון שמונה והולך ולא הסתפק בנתינה של משהו לצורך קידושין, משמע שכוונתם שיתן לה את המנה כולו ולפיכך יכולים לחזור בהם במקרה זה עד תום המנין.","אגב כך שואלים: \u0003האי\u0004 \u0005[זה]\u0006 \u0003דינר של נחשת\u0004 שהוזכר כאן, \u0003היכי דמי\u0004 \u0005[כיצד היה\u0006 הדבר בדיוק\u0005]?\u0006 \u0003אי דידעה ביה\u0004 \u0005[אם שיודעת בו]\u0006 שהוא דינר של נחושת — \u0003הא סברה\u0004 \u0005[הרי ידעה]\u0006 \u0003וקבלה\u0004 את המטבע הזו כדינר, ואינה יכולה לחזור בה משום כך! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דיהביה ניהליה בליליא\u0004 \u0005[\u0006\u0005שנתן לה\u0006 את הדינר הזה \u0005בלילה]\u0006 ולא ראתה באותה שעה שהוא של נחושת, \u0003אי נמי דאשתכח ליה ביני זוזי\u0004 \u0005[או גם כן כשנמצא בין הדינרים]\u0006 ולא הבחינה שדינר זה של נחושת הוא.","ועוד שואלים: \u0003האי\u0004 \u0005[זה]\u0006 \u0003דינר רע\u0004 שנזכר שם \u0003היכי דמי\u0004 \u0005[כיצד היה בדיוק]?\u0006 שהרי \u0003אי דלא נפיק\u0004 \u0005[אם שאיננו יוצא],\u0006 שאי אפשר להשתמש בו כדינר כסף — \u0003היינו\u0004 \u0005[הרי זה]\u0006 בדיוק כמו \u0003דינר של נחשת,\u0004 שהרי אף זה אינו שווה דינר! \u0003אמר רב פפא:\u0004 שם מדובר \u0003כגון דנפיק\u0004 \u0005[שיוצא]\u0006 \u0003על ידי הדחק,\u0004 שצריך לחזר הרבה עד שיימצא מישהו שיקבל אותו.","\u0003אמר רבא אמר רב נחמן: אמר לה,\u0004 לאשה, \u0003\"התקדשי לי במנה\", ו\u0004לא נתנו לה אלא \u0003הניח לה משכון עליה,\u0004 על המנה הזה — \u0003אינה מקודשת\u0004 וטעמו:"],["\u0003מנה אין כאן\u0004 — שהרי עדיין לא נתן לה מנה, ו\u0003משכון אין כאן\u0004 — שהרי המשכון הזה אינו מתנה, אלא ערבון בלבד, ונמצא שלא נתן לה מאומה. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו במפורש: \u0003קידשה במשכון מקודשת!\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003במשכון\u0004 של \u0003אחרים\u0004 שהיה ממושכן בידו של המקדש, \u0003וכ\u0004דברי \u0003ר' יצחק.\u0004","ש\u0003אמר ר' יצחק: מנין לבעל חוב שקונה משכון,\u0004 כלומר, שהמחזיק במשכון יש לו זכות קניינית בו — \u0003שנאמר \"\u0004השב תשיב לו את העבוט... \u0003ולך תהיה צדקה\"\u0004 (דברים כד, יג). \u0003אם\u0004 המלווה \u0003אינו קונה\u0004 את העבוט = המשכון לעצמו — \u0003צדקה מנין\u0004 כשמחזיר אותו? שהרי לא את שלו הוא נותן! אלא \u0003מכאן לבעל חוב שקונה משכון\u0004 במקצת קנין.","מסופר: \u0003בני רב הונא בר אבין זבון ההיא אמתא בפריטי\u0004 \u0005[קנו שפחה אחת\u0006 על מנת לשלם \u0005בפרוטות\u0006 נחושת\u0005],\u0006 \u0003לא הוו בהדייהו\u0004 \u0005[היה בידם]\u0006 הממון באותה שעה, \u0003אותיבי נסכא\u0004 \u0005[נתנו\u0006 כמשכון \u0005חתיכת כסף]\u0006 \u0003עליה. לסוף אייקר אמתא\u0004 \u0005[לבסוף התייקרה האמה]\u0006 ורצו המוכרים לבטל את המיקח. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003ר' אמי\u0004 לשאול, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003פריטי\u0004 \u0005[פרוטות]\u0006 \u0003אין כאן,\u0004 לפיכך גם \u0003נסכא\u0004 \u0005[חתיכת כסף]\u0006 \u0003אין כאן,\u0004 שהרי בפועל לא נתנו את הכסף, והמשכון שנתנו גם כן אינו קונה, ונמצא שלא היה כאן מעשה קנין כלל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אמר לאשה \u0003\"התקדשי לי במנה\", נטלתו\u0004 מידו \u0003וזרקתו לים או לאור\u0004 (לאש) \u0003או לכל דבר האבד\u0004 — \u0003אינה מקודשת.\u0004 ותוהים: מתוך לשון הברייתא משמע כי דווקא במקרים אלו שהלך המנה לאיבוד אינה מקודשת, \u0003הא שדיתינהו קמיה\u0004 \u0005[הרי\u0006 אם \u0005זרקה אותם,\u0006 את המעות, \u0005לפניו]\u0006 ולא איבדה אותו — \u0003הוו\u0004 \u0005[הרי הם]\u0006 \u0003קידושין? הא קאמרה ליה: שקיל, לא בעינא\u0004 \u0005[\u0006ו\u0005הרי היא אומרת לו\u0006 בכך: \u0005קח, אינני רוצה]\u0006 בקידושין!","ומשיבים: בלשון \u0003לא מיבעיא קא אמר\u0004 \u0005[נצרכה אמר],\u0006 וכך יש להבין: \u0003לא מיבעיא\u0004 \u0005[צריך]\u0006 לומר שכאשר \u0003שדיתינהו קמיה דלא הוו\u0004 \u0005[זרקה אותם לפניו שאינם]\u0006 \u0003קידושין,\u0004 שהרי גילתה את דעתה שאינה חפצה בקידושין, \u0003אבל זרקתו לים או לאור אימא\u0004 \u0005[אמור]\u0006 \u0003כיון דמיחייבא בהו\u0004 \u0005[שמחוייבת בהם]\u0006 להחזירם, שמא נאמר כי \u0003קדושי קדיש נפשה\u0004 \u0005[קידשה את עצמה]\u0006 בכסף שקיבלה, \u0003והא דקא עבדא הכי סברא\u0004 \u0005[וזה שהיא עושה כך,\u0006 שזורקת לים — \u0005חשבה]:\u0006 \u0003איבדקיה להאי גברא אי רתחנא\u0004 \u0005[אבדוק את האיש הזה אם כעסן]\u0006 \u0003הוא או לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 התנא שגם במקרה זה אין אלה קידושין.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אמר לאשה \u0003\"התקדשי לי במנה\"\u0004 ואמרה לו: \u0003\"תנם,\u0004 את המעות, \u0003לאבא\u0004 או \u0003לאביך\"\u0004 — \u0003אינה מקודשת.\u0004 ואולם אם אמרה \u0003\"\u0004תנם לאבא או לאביך \u0003על מנת שיקבלום לי\"\u0004 — \u0003מקודשת.\u0004","ומעירים: \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003\"אבא\"\u0004 — \u0003להודיעך,\u0004 כלומר, להדגיש עד היכן מגיע \u0003כח\u0004 הדין \u0003דרישא\u0004 \u0005[שבתחילתה\u0006 של הברייתא\u0005]\u0006 שאם אמרה שיתנם לאחר, אפילו כשאמרה \"לאבא\" שלה, שמן הסתם היא רוצה בהנאתו — אינה מקודשת. \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003\"אביך\" להודיעך כח דסיפא\u0004 \u0005[שבסוף\u0006 הברייתא\u0005]\u0006 שאם אמרה על מנת שיקבלום עבורה — אפילו אמרה שימסרם לאביו של המקדש — הרי אלו קידושין.","עוד שנינו: אם אמר לה \u0003\"התקדשי לי במנה\"\u0004 ואמרה לו \u0003\"תנם לפלוני\"\u0004 — \u0003אינה מקודשת.\u0004 ואולם אם אמרה לו \u0003\"על מנת שיקבלם לי\"\u0004 — הריהי \u0003מקודשת.\u0004 ומעירים: \u0003וצריכא\u0004 \u0005[וצריכה]\u0006 גם פיסקה זו להיאמר אף שלכאורה היא מעין האמור בפיסקה הראשונה;","\u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק את הדין כשאמרה \u0003\"אבא ואביך\"\u0004 היינו אומרים \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא ד\u0004\u0003כי אמרה\u0004 \u0005[שכאשר אומרת]\u0006 \u0003\"על מנת שיקבלום לי\" הוו\u0004 \u0005[הריהם]\u0006 \u0003קידושין,\u0004 משום \u0003דסמכה דעתה עילייהו\u0004 \u0005[שסומכת דעתה עליהם]\u0006 כי \u0003סברה\u0004 \u0005[חושבת\u0006 היא\u0005]:\u0006 \u0003עבדין\u0004 \u0005[יעשו]\u0006 \u0003לי\u0004 הם \u0003שליחותאי\u0004 \u0005[את שליחותי]\u0006 ויחזיקו בכסף עבורי. \u0003אבל\u0004 כאשר אמרה \"תנם ל\u0003פלוני,\u0004 סתם אדם, על מנת שיקבל לי\" — \u0003לא. ו\u0004להיפך,","\u0003אי אשמעינן\u0004 \u0005[אם היה משמיע לנו\u0006 רק\u0005]\u0006 ב\u0003פלוני,\u0004 היינו אומרים: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003הוא דכי אמרה\u0004 \u0005[שכאשר\u0006 היא \u0005אומרת]\u0006 \u0003\"תנם לפלוני\"\u0004 סתם — \u0003לא הוו קידושי\u0004 \u0005[אינם קידושין]\u0006 משום \u0003דלא מקרבא דעתה לגביה\u0004 \u0005[שאין דעתה קרובה אליו]\u0006 ואינה מעוניינת \u0003למיתבה ליה\u0004 \u0005[לתת לו]\u0006 \u0003במתנה\u0004 כסף זה. \u0003אבל \"אבא ואביך\" דמקרבא דעתה לגבייהו\u0004 \u0005[שקרובה דעתה לגביהם]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003במתנה יהביתיה ניהלייהו\u0004 \u0005[נתנה אותה להם],\u0006 שקיבלה את המעות ככסף קידושין, והחליטה לתת אותם במתנה וצריכה להיות מקודשת, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שתי הפיסקאות, שבשניהם אינה מקודשת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אמר לאשה \u0003\"התקדשי לי במנה\"\u0004 ואמרה לו \u0003\"תנם על גבי סלע\"\u0004 — \u0003אינה מקודשת. ואם היה סלע\u0004 זה \u0003שלה\u0004 — הריהי \u0003מקודשת. בעי\u0004 \u0005[שאל]\u0006 \u0003רב ביבי:\u0004 אם היה ה\u0003סלע של שניהם, מהו?\u0004 השאלה הזו לא נפתרה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","אמר לה \u0003\"התקדשי לי בככר\",\u0004 אמרה לו: \u0003\"תנהו לכלב\"\u0004 — \u0003אינה מקודשת. ואם היה כלב\u0004 זה \u0003שלה\u0004 — \u0003מקודשת. בעי\u0004 \u0005[שאל]\u0006 \u0003רב מרי:\u0004 ואם היה \u0003כלב רץ אחריה\u0004 לנשכה ואמרה לו תן את הככר לכלב, \u0003מהו\u0004 הדין?","וצדדי השאלה: האם \u0003בההוא\u0004 \u0005[באותה]\u0006 \u0003הנאה דקא מצלה נפשה מיניה\u0004 \u0005[שהיא מצילה את עצמה ממנו,\u0006 מן הכלב\u0005]\u0006 \u0003גמרה ומקניא ליה נפשה\u0004 \u0005[גומרת\u0006 בלבה \u0005ומקנה לו\u0006 לנותן הככר \u0005את עצמה\u0006 לקידושין\u0005],\u0006 \u0003או דלמא מצי אמרה ליה\u0004 \u0005[שמא יכולה לומר לו]:\u0006 \u0003מדאורייתא חיובי מחייבת לאצולן\u0004 \u0005[מ\u0006דין \u0005התורה\u0006 הלא \u0005חייב אתה להציל אותי]\u0006 משום \"לא תעמוד על דם רעך\", ואינה חייבת לו דבר, ואינה מקודשת על ידי ככר זו? אף בעיה זו לא נפתרה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","אמר לאשה \u0003\"התקדשי לי בככר\"\u0004 ואמרה לו \u0003\"תנהו לעני\"\u0004 — \u0003אינה מקודשת, אפילו\u0004 היה זה \u0003עני הסמוך עלה\u0004 \u0005[עליה]\u0006 שהיא רגילה לספק לו את מזונותיו. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אמרה ליה\u0004 \u0005[\u0006יכולה היא \u0005לומר לו]:\u0006 \u0003כי היכי דמחייבנא ביה אנא הכי מחייבת ביה את\u0004 \u0005[כשם שאני מחויבת בו\u0006 לתת לו צדקה \u0005כך מחויב אתה בו]\u0006 ואין זו נחשבת כנתינה לאשה שתתקדש בה.","מסופר: \u0003ההוא גברא דהוה קא מזבין\u0004 \u0005[אדם אחד שהיה מוכר]\u0006"],["\u0003חומרי פתכייתא\u0004 \u0005[מחרוזות\u0006 של \u0005זכוכית].\u0006 \u0003אתאי ההיא איתתא\u0004 \u0005[באה אשה אחת],\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי חד שוכא\u0004 \u0005[ענף\u0006 (מחרוזת) \u0005אחד].\u0006 \u0003אמר לה: אי יהבינא ליך מיקדשת\u0004 \u0005[אם אתן לך\u0006 אותה האם \u0005תתקדשי]\u0006 \u0003לי\u0004 בה? \u0003אמרה ליה\u0004 \u0005[לו]\u0006 בלגלוג: \u0003הבה מיהבה\u0004 \u0005[תן תן]\u0006 והתכוונה שאינה חוששת כלל לתנאי זה. \u0003אמר רב חמא: כל\u0004 שאומרת לשון \u0003\"הבה מיהבה\"\u0004 \u0005[\"תן תן\"]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כלום הוא,\u0004 כלומר, היא אמנם אמרה לו \"תן\", אבל לא הסכימה לתנאי שאמר לה, ואינה מקודשת בכך.","וכן מסופר: \u0003ההוא גברא דהוה קא שתי חמרא בחנותא\u0004 \u0005[אדם אחד שהיה שותה יין בחנות].\u0006 \u0003אתאי ההיא איתתא\u0004 \u0005[נכנסה אשה אחת],\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי חד כסא\u0004 \u0005[כוס\u0006 יין \u0005אחת].\u0006 \u0003אמר לה: אי יהיבנא ליך\u0004 \u0005[אם אתן לך]\u0006 האם \u0003מיקדשת\u0004 \u0005[תתקדשי]\u0006 \u0003לי\u0004 בה? \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003\"אשקויי אשקיין\"\u0004 \u0005[השקה השקה אותי].\u0006 \u0003אמר רב חמא: כל\u0004 שאומרת \u0003\"אשקויי אשקיין\"\u0004 \u0005[\"השקה השקה אותי\"]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כלום הוא,\u0004 שבוודאי אין כוונתה לקבל את התנאי ואינה מקודשת.","מסופר: \u0003ההוא גברא דהוה קא שדי תמרי מדקלא\u0004 \u0005[אדם אחד שהיה זורק,\u0006 קוטף, \u0005תמרים מן הדקל].\u0006 \u0003אתאי ההיא איתתא\u0004 \u0005[באה אשה אחת],\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003שדי\u0004 \u0005[זרוק,\u0006 קטוף\u0005]\u0006 \u0003לי תרתי\u0004 \u0005[שתים]!\u0006 \u0003אמר לה: אי שדינא ליך מיקדשת\u0004 \u0005[אם אזרוק\u0006 \u0003לך\u0004 האם \u0005תתקדשי]\u0006 \u0003לי\u0004 בהן? \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003שדי מישדא\u0004 \u0005[זרוק זרוק].\u0006 \u0003אמר רב זביד: כל \"שדי מישדא\"\u0004 \u0005[\"זרוק זרוק\"]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כלום הוא\u0004 ואינה מקודשת.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 אם אמרה לו בלשון \u0003\"הב\"\u0004 \u0005[\"תן\"],\u0006 או \u0003\"אשקי\"\u0004 \u0005[\"השקה\"],\u0006 או \u0003\"שדי\"\u0004 \u0005[\"זרוק\"]\u0006 בלבד, בלא שכפלה את דיבורה, \u0003מהו\u0004 הדין? האם משמעו שהתכוונה לומר ברצינות — תן כפי התנאי שאמרת, או שאף בדיבור כגון זה לא הסכימה לקידושין, או לא? \u0003אמר רבינא: מקודשת. רב סמא בר רקתא אמר\u0004 בלשון שבועה: \u0003תגא דמלכא\u0004 \u0005[כתר המלך]!\u0006 \u0003אינה מקודשת. והלכתא\u0004 \u0005[והלכה]:\u0006 \u0003אינה מקודשת.\u0004","ואגב פסק זה מסכמים להלכה גם את הבעיות שנשאלו קודם: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003שיראי\u0004 \u0005[שיראין]\u0006 שהיה בהם יותר משווה פרוטה \u0003לא צריכי שומא\u0004 \u0005[אינם צריכים הערכה]\u0006 מיוחדת בשביל לקדש בהם אשה. \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כ\u0004דעת \u0003ר' אלעזר\u0004 שאם הבטיח לה מנה בקידושין ונתן לה רק דינר ממנו מקודשת, \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כ\u0004דעת \u0003רבא\u0004 ש\u0003אמר\u0004 בשם \u0003רב נחמן\u0004 שאם הבטיח מנה ונתן רק משכון אין זה נחשב לקידושין.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 קידושין \u0003בשטר כיצד? כתב לו\u0004 הבעל לאבי הנערה שטר \u0003על הנייר או על החרס אף על פי שאין בו\u0004 בנייר או בחרס \u0003שוה פרוטה\u0004 (שאין כאן קידושין בשווה כסף), בלשון: \u0003\"בתך מקודשת לי\",\u0004 או \u0003\"בתך מאורסת לי\",\u0004 או \u0003\"בתך לי לאינתו\"\u0004 \u0005[לאשה]\u0006 — \u0003הרי זו מקודשת.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא בר ממל: הא\u0004 \u0005[הרי]\u0006 \u0003לא דמי האי שטרא\u0004 \u0005[דומה שטר זה]\u0006 \u0003לשטר זביני\u0004 \u0005[מכר]!\u0006 שכן \u0003התם\u0004 \u0005[שם],\u0006 בשטר מכר, ה\u0003מוכר\u0004 הוא ש\u0003כותב לו\u0004 לקונה \u0003\"שדי מכורה לך\",\u0004 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 ה\u0003בעל\u0004 (שהוא לענין זה כקונה) הוא ש\u0003כותב \"בתך מקודשת לי\"!\u0004","\u0003אמר רבא: התם מעניינא דקרא והכא מעניינא דקרא\u0004 \u0005[שם\u0006 במכר, לשון השטר הוא \u0005מענין הכתוב וכאן\u0006 בקידושין, לשון השטר הוא \u0005מענין הכתוב];\u0006 \u0003התם כתיב\u0004 \u0005[שם\u0006 בענין מכר \u0005נאמר]\u0006 \u0003\"ומכר מאחזתו\"\u0004 (ויקרא כה, כה), לומר: \u0003במוכר תלה רחמנא\u0004 \u0005[תלתה תורה],\u0006 \u0003הכא כתיב\u0004 \u0005[כאן נאמר]\u0006 \u0003\"כי יקח\u0004 איש אשה\" (דברים כב, יג) לומר: \u0003בבעל תלה רחמנא\u0004 \u0005[תלתה התורה].\u0006","ושואלים: \u0003התם נמי כתיב\u0004 \u0005[שם\u0006 במכר הלא \u0005גם כן נאמר]\u0006 \u0003\"שדות בכסף יקנו\"\u0004 (ירמיה לב, מד) ותלה את הדבר בקונה! ומשיבים: \u0003קרי ביה\u0004 \u0005[קרא בו]\u0006 \u0003\"יקנו\".\u0004 ושואלים: \u0003מאי טעמא קרית ביה\u0004 \u0005[מה טעם אתה קורא בו]\u0006 \u0003\"יקנו\"\u0004 — \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ומכר\", הכי נמי קרי ביה\u0004 \u0005[כאן גם כן קרא בו]\u0006 \u0003\"כי יקח\", דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"את בתי נתתי לאיש הזה\"\u0004 (דברים כב, טז).","\u0003אלא אמר רבא:\u0004 יש לחזור מן הנסיונות למצוא מקור בכתוב לדינים אלה, ולומר כי \u0003הלכתא נינהו ואסמכינהו רבנן אקראי\u0004 \u0005[הלכות\u0006 מקובלות \u0005הן\u0006 במסורת, \u0005והסמיכו אותן חכמים על הכתובים].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003התם נמי כתיב\u0004 \u0005[שם,\u0006 במכר, \u0005גם כן נאמר]\u0006 על הקונה \u0003\"ואקח את ספר המקנה\"\u0004 (ירמיה לב, יא), משמע שהמוכר הוא זה שכתב את השטר.","\u0003ואמר רבא אמר רב נחמן: כתב לו על הנייר או על החרס, אף על פי שאין בו שוה פרוטה, \"בתך מקודשת לי\",\u0004 או \u0003\"בתך מאורסת לי\",\u0004 או \u0003\"בתך לי לאינתו\"\u0004 \u0005[לאשה],\u0006 \u0003בין\u0004 שנתנו \u0003על ידי אביה בין\u0004 שנתנו \u0003על ידי עצמה\u0004 — \u0003מקודשת מדעתו\u0004 של אביה, \u0003והוא\u0004 בזמן \u0003שלא בגרה,\u0004 שאז לאביה בלבד יש רשות לקדשה.","ואם \u0003כתב לה על הנייר או על החרס, אף על פי שאין בו שוה פרוטה, \"הרי את מקודשת לי\",\u0004 או \u0003\"הרי את לי לאינתו\"\u0004 \u0005[לאשה],\u0006 או \u0003\"הרי את מאורסת לי\"\u0004 — \u0003מקודשת, בין\u0004 שמסרם \u0003על ידי אביה בין על ידי עצמה\u0004 ובלבד שעשה זאת \u0003מדעתה\u0004 (מרצונה) — \u0003והוא\u0004 דווקא לאחר \u0003שבגרה\u0004 ועומדת ברשות עצמה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' שמעון בן לקיש: שטר אירוסין שכתבו שלא לשמה\u0004 של אשה זו, אלא כתבו סתם \u0003מהו\u0004 דינו? האם \u0003הויות\u0004 (היות האשה לאיש בקידושין) \u0003ליציאות\u0004 (לגירושין) \u0003מקשינן\u0004 \u0005[אנו מקישים,\u0006 משווים\u0005]\u0006 לכל הדינים, ולכן נאמר: \u0003מה\u0004"],["\u0003יציאה\u0004 (גט) \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיה כתוב דווקא \u0003לשמה\u0004 — \u0003אף\u0004 בשטר \u0003הוייה\u0004 של קידושין \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיה השטר כתוב \u0003לשמה, או דלמא\u0004 \u0005[שמא]\u0006 \u0003הויות להדדי\u0004 \u0005[זו לזו]\u0006 \u0003מקשינן\u0004 \u0005[אנו מקישים,\u0006 משווים\u0005]:\u0006 \u0003מה הוייה\u0004 (קידושין) שנעשית על ידי \u0003כסף לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שיהיה הכסף עשוי, מוטבע \u0003לשמה\u0004 — \u0003אף הוייה\u0004 של \u0003שטר לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שתהיה \u0003לשמה?\u0004","\u0003בתר דבעיא הדר פשטה\u0004 \u0005[אחר ששאל\u0006 אותה שאלה \u0005חזר\u0006 ו\u0005פתרה]:\u0006 \u0003הוייה ליציאה מקשינן\u0004 \u0005[משווים אנו],\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ויצאה... והיתה\"\u0004 (דברים כד, ב), וכיון שלמדים את עצם דין שטר קידושין משטר גירושין צריך שיהיה גם הוא, כשטר גירושין, כתוב לשמה.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בבעיה : \u0003כתבו\u0004 את שטר הקידושין \u0003לשמה, ושלא מדעתה\u0004 כשהיא לא ידעה על כך תחילה ואחר כך הסכימה לקבלו, \u0003רבא ורבינא אמרי\u0004 \u0005[אומרים]:\u0006 \u0003מקודשת. רב פפא ורב שרביא אמרי\u0004 \u0005[אומרים]:\u0006 \u0003אינה מקודשת. אמר רב פפא: אימא טעמא דידהו ואימא טעמא דידי\u0004 \u0005[אומר\u0006 את \u0005טעמם שלהם ואומר\u0006 את \u0005הטעם שלי].\u0006 \u0003אימא טעמא דידהו\u0004 \u0005[אומר\u0006 את \u0005הטעם שלהם]\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויצאה... והיתה\", מקיש\u0004 \u0005[משווה]\u0006 הכתוב על ידי כך \u0003הוייה ליציאה, מה יציאה לשמה ושלא מדעתה\u0004 ואף שלא מרצונה, \u0003אף הוייה נמי\u0004 \u0005[גם כן]\u0006 \u0003לשמה ו\u0004אפילו \u0003שלא מדעתה.\u0004","\u0003ואימא טעמא דידי\u0004 \u0005[ואומר\u0006 את \u0005הטעם שלי]:\u0006 נאמר \u0003\"ויצאה... והיתה\"\u0004 — \u0003מקיש הוייה ליציאה, מה יציאה בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003דעת מקנה\u0004 האיש המגרש, המקנה לאשה את עצמה, \u0003אף\u0004 בזמן \u0003הוייה בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003דעת מקנה\u0004 ובקידושין האשה מקנה את עצמה, וצריך שיהיה לדעתה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דעת האומרים מקודשת ממה ששנינו: \u0003אין כותבין שטרי אירוסין ונשואין אלא מדעת שניהן. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר ב\u0003שטרי אירוסין ונשואין ממש,\u0004 כלומר, שטר של קידושין, ומכאן הוכחה שצריך את דעת האשה! ודוחים: \u0003לא,\u0004 מדובר פה ב\u0003שטרי פסיקתא\u0004 \u0005[שטרות פסיקה],\u0006 שפוסקים, קובעים בהם את סכומי הנדוניה. \u0003וכ\u0004דברי \u0003רב גידל אמר רב.\u0004","ש\u0003אמר רב גידל אמר רב:\u0004 אומר מחותן אחד לחבירו \u0003\"כמה אתה נותן לבנך\"?\u0004 ועונה לו: \u0003כך וכך,\u0004 ומוסיף: \u0003\"\u0004כמה אתה נותן \u0003לבתך\"?\u0004 ועונה לו: \u0003\"כך וכך\",\u0004 אם \u0003עמדו\u0004 אחר כך \u0003וקדשו\u0004 — \u0003קנו\u0004 את כל הדברים שהבטיחו, \u0003הן הן הדברים הנקנים באמירה\u0004 ואינם צריכים קנין. ושטרות אירוסין ששנינו שצריכים גם דעת האשה הם שטרות שכותבים בהם התחייבויות אלה ולא שטרי קידושין ממש.","שנינו במשנה שהאשה נקנית בין השאר גם \u0003בביאה,\u0004 שואלים: \u0003מנא לן\u0004 \u0005[מנין לנו\u0006 זאת\u0005]?\u0006 \u0003אמר ר' אבהו אמר ר' יוחנן:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"בעלת בעל\"\u0004 (שם כב, כב), \u0003מלמד שנעשה לה בעל על ידי בעילה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' אבהו ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ריש לקיש לר' יוחנן:\u0004 וכי \u0003כעורה\u0004 הוכחה \u0003זו ששנה רבי\u0004 שדרש את המלה \u0003\"\u0004כי יקח איש אשה \u0003ובעלה\"\u0004 (שם כד, א) — \u0003מלמד שנקנית בביאה?\u0004","על כך משיבים שדברי רבי אינם הוכחה מספקת לקנין ביאה באשה כי \u0003אי מהתם\u0004 \u0005[אם משם]\u0006 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שאינה נחשבת אשתו אלא \u0003עד\u0004 ש\u0003מקדש\u0004 תחילה בכסף \u0003והדר בעיל\u0004 \u0005[וחוזר\u0006 אחר כך ו\u0005בועל]\u0006 ואין קנין אישות אלא בדרך זו, אבל בעילה בלבד אינה קונה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 מהפסוק \"בעולת בעל\" שדי בביאה לקנין אישות.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' אבא בר ממל:\u0004 אינך יכול להעלות על הדעת לפרש כך את הפסוק \"כי יקח איש אשה ובעלה\" ש\u0003אם כן\u0004 אתה אומר שאין קנין באשה אלא באופן שיהיו קידושין וביאה, \u0003נערה המאורסה דאמר רחמנא\u0004 \u0005[שאמרה תורה]\u0006 שהבא עליה חייב \u0003בסקילה, היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותה]?\u0006","\u0003אי דאקדיש והדר בעיל\u0004 \u0005[אם\u0006 כ\u0005שקידש\u0006 אותה \u0005וחזר\u0006 אחר כך ו\u0005בעל]\u0006 אם כן הרי \u0003בעולה היא,\u0004 ואין עונש סקילה אלא בנערה מאורסה בתולה, \u0003אי דאקדיש\u0004 \u0005[שאם שקידש]\u0006 אותה \u0003ולא בעיל\u0004 \u0005[בעל]\u0006 הרי לשיטה זו \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כלום הוא,\u0004 שעדיין לא נשלם הקנין? \u0003אמרוה רבנן קמיה\u0004 \u0005[אמרו חכמים לפני]\u0006 \u0003אביי: משכחת לה\u0004 \u0005[\u0006יכול \u0005אתה למצוא אותה],\u0006 את האפשרות לכך, \u0003כגון ש\u0004קידש ואחר כך \u0003בא עליה ארוס שלא כדרכה,\u0004 ואם כן עדיין היא בתולה, אבל קנה אותה הארוס בבעילה זו.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003אביי:\u0004 אין אפשרות להעמיד כשיטתכם שהרי \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003רבי ורבנן אלא ב\u0004אדם \u0003אחר,\u0004 שבא על אשה שלא כדרכה האם נחשבת היא בכך כבעולה, \u0003אבל בעל\u0004 — \u0003דברי הכל אם בא עליה שלא כדרכה עשאה בעולה\u0004 ושוב אינה \"בתולה\" לענין נערה המאורסה!","ומבררים: ו\u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 אותה מחלוקת שאביי רומז לה? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 ברייתא\u0005]:\u0006 \u0003באו עליה\u0004 על נערה המאורסה \u0003עשרה אנשים, ועדיין היא בתולה,\u0004 כגון שבאו עליה שלא כדרכה — \u0003כולן\u0004 נידונים \u0003בסקילה. רבי אומר, אומר אני: הראשון בסקילה\u0004 כיון שהוא בא על נערה בתולה, \u0003ו\u0004אילו האחרים \u0003כולן בחנק,\u0004 משום שלאחר שבעל אותה הראשון שוב אינה קרויה עוד בתולה, אף שבעל אותה שלא כדרכה.","\u0003אמר רב נחמן בר יצחק\u0004 תירוץ אחר לקושיית ר' אבא בר ממל: \u0003משכחת לה\u0004 \u0005[\u0006יכול \u0005אתה למצוא אותה]\u0006 נערה מאורסה שחייבים עליה סקילה \u0003כגון\u0004 באופן \u0003שקדשה בשטר,\u0004 שלכל הדעות \u0003הואיל\u0004 והשטר כוחו גדול \u0003וגומר ומוציא\u0004 את האשה מבעלה ואינה צריכה מעשה נוסף, הוא גם \u0003גומר ומכניס,\u0004 ואם נתקדשה בשטר יכולה היא להיות נערה מאורסה בתולה.","ושואלים: \u0003ור' יוחנן\u0004 הסבור כי למדנו קידושין בביאה מ\"בעולת בעל\" \u0003האי\u0004 \u0005[\u0006הכתוב \u0005הזה]\u0006 \u0003\"ובעלה\", מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה בו]?\u0006 ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 כתוב \u0005נצרך לו]\u0006 לענין אחר, לדייק ולהדגיש: \"ובעלה\" — \u0003זו\u0004 האשה \u0003נקנית בביאה, ואין אמה העבריה נקנית בביאה.\u0004","שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 אמה עבריה \u0003בקל וחומר מיבמה: ומה יבמה שאין נקנית בכסף\u0004 כלל, ומכל מקום \u0003נקנית בביאה,\u0004 ומכאן לכאורה שכוח קנין של ביאה גדול יותר, \u0003זו,\u0004 האמה העבריה, \u0003שנקנית בכסף, אינו דין שנקנית בביאה?\u0004","ויש לדחות: \u0003מה ליבמה — שכן זקוקה ועומדת\u0004 ליבם, ויש איפוא קשר קודם ביניהם, ושמא משום כך הבעילה קונה בה, מה שאין כן באמה. אלא \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 באופן אחר: \u0003הואיל וכתב\u0004 באמה העבריה \u0003\"אם אחרת יקח לו\"\u0004 (שמות כא, י), לכאורה \u0003הקישה\u0004 (השווה אותה) \u0003הכתוב ל\u0004אשה \u0003אחרת\u0004 שלוקח לו אותו אדון, \u0003מה אחרת מיקניא\u0004 \u0005[נקנית]\u0006 \u0003בביאה\u0004 — \u0003אף אמה העבריה מיקניא\u0004 \u0005[נקנית]\u0006 \u0003בביאה, על כן קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הכתוב מדיוק \"ובעלה\" שאינו כך.","הסברנו איפוא את משמעות \"ובעלה\" לדברי ר' יוחנן, ויש לשאול: \u0003ורבי\u0004 שלומד עיקר הדין של קידושי בעילה מפסוק זה, \u0003האי סברא\u0004 \u0005[סברה זו]\u0006 שאמה אינה נקנית בביאה \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003אם כן לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 רק \u0003\"ובעל\", מאי\u0004 \u0005[מה]\u0006 לשון \u0003\"ובעלה\"\u0004 שיש בה גם משמעות דיוק והגבלה — \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שני דברים],\u0006 הן שבעילה קונה באשה, והן שבעילה קונה רק באשה ולא באמה.","ושואלים עוד: \u0003ול\u0004שיטת \u0003רבא\u0004 ש\u0003אמר: בר אהינא אסברה\u0004 \u0005[הסביר אתה]\u0006 \u0003לי\u0004 והביא לי ראיה ממה שנאמר בכתוב: \u0003\"כי יקח איש אשה ובעלה\"\u0004 (דברים כד, א) — בא הדבר לומר: \u0003קידושין המסורין לביאה,\u0004 כלומר, שיש אפשרות חוקית שיבואו לידי ביאה — קידושין כאלה \u0003הוו\u0004 \u0005[הריהם]\u0006 \u0003קידושין,\u0004 אבל \u0003קידושין שאין מסורין לביאה,\u0004 שיש בעיה חוקית בקידושין עד שהביאה אסורה עליהם — \u0003לא הוו\u0004 \u0005[אינם]\u0006 \u0003קידושין,\u0004 ואף על פי שיש מחלוקת, בדבר מכל מקום זו שיטת רבא. אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 ומנין לו שאשה נקנית בביאה ואין אמה עבריה נקנית בביאה? שהרי לשיטתו אף הדיוק של \"ובעלה\" נצרך ללימוד אחר!","ומשיבים: \u0003אם כן נכתוב קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"\u0004כי יקח איש אשה \u0003או בעלה\", מאי \"ובעלה\"\u0004 שהוא המשך ותנאי של הדבר האמור קודם — \u0003שמע מינה כולהו\u0004 \u0005[למד ממנה את כל\u0006 הדברים\u0005]\u0006 שבעילה קונה, וקונה רק באשה ולא באמה, ושקידושין צריכים להיות ראויים לביאה.","ושואלים: \u0003ורבי, האי\u0004 \u0005[\u0006הכתוב \u0005הזה]\u0006 \u0003\"בעלת בעל\",\u0004 שממנו למד ר' יוחנן קידושין בביאה, \u0003מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 שהרי הוא לומד דין זה מ\"ובעלה\"? ומשיבים: \u0003האי מיבעי ליה\u0004 \u0005[זה נצרך לו]\u0006 ללמד כי \u0003בעל עושה אותה בעולה\u0004 גם אם בעל אותה \u0003שלא כדרכה, ואין אחר עושה אותה בעולה\u0004 אם בא עליה \u0003שלא כדרכה.\u0004","ותוהים: \u0003ומי אית ליה לרבי האי סברא\u0004 \u0005[האם יש לו,\u0006 מקבל, \u0005רבי סברה זו]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003באו עליה,\u0004 על נערה המאורסה, \u0003עשרה אנשים ועדיין היא בתולה\u0004 — \u0003כולם\u0004 נידונים \u0003בסקילה. רבי אומר: אומר אני הראשון בסקילה, וכולם בחנק\u0004 משמע שהוא סבור שאפילו אחר שאיננו בעלה עושה אותה בעולה שלא כדרכה!"],["\u0003אמר ר' זירא:\u0004 מכל מקום \u0003מודה רבי לענין קנס,\u0004 של אונס ומפתה \u0003דכולהו משלמי\u0004 \u0005[שכולם משלמים]\u0006 ואין אומרים שייפטרו משום שבאו על בעולה. ושואלים: \u0003מאי שנא מקטלא\u0004 \u0005[מה שונה\u0006 הדבר \u0005ממיתה]?\u0006 ומדוע לענין עונש מיתה שנענשים על שבאו על הארוסה דנים אותה כבעולה, ולענין קנס משלמים כאילו באו על בתולה? ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בענין מיתה ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ומת האיש אשר שכב עמה לבדו\"\u0004 (דברים כב, כה) לומר שרק איש אחד נהרג עליה, ולא יותר.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003האי\u0004 \u0005[זה,\u0006 הכתוב\u0005]\u0006 \u0003\"לבדו\" מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בו]?\u0006 ומשיבים: \u0003מיבעי להו לכדתניא\u0004 \u0005[צריך\u0006 הוא \u0005להם לכפי ששנינו\u0006 בברייתא\u0005],\u0006 מה שנאמר \u0003\"ומתו גם שניהם\"\u0004 (שם כב) לומר: \u0003עד שיהיו\u0004 שניהם \u0003שוין כאחד,\u0004 כלומר, שיהיו שניהם בני עונשין, אבל אם אחד מהם לא היה בן עונשין (כגון שהוא קטן) גם השני אינו נהרג, אלו \u0003דברי ר' אושעיא.\u0004 ואילו \u0003ר' יונתן אומר,\u0004 נאמר: \u0003\"ומת האיש אשר שכב עמה לבדו\",\u0004 משמע שייתכן שרק האיש בלבד יהיה חייב מיתה (או שרק האשה תהיה חייבת).","ושואלים: \u0003ור' יוחנן האי סברא מנא ליה\u0004 \u0005[סברה זו\u0006 שרק בעלה עושה אותה בעולה בביאה שלא כדרכה \u0005מניין לו]?\u0006 שהרי הוא לומד מפסוק זה את עצם קידושי ביאה באשה, ומשיבים: \u0003אם כן נכתוב קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"בעולת איש\", מאי\u0004 \u0005[מה\u0006 הלשון\u0005]\u0006 \u0003\"בעולת בעל\"\u0004 — \u0003שמע מינה תרתי\u0004 \u0005[למד ממנה שתים],\u0006 גם לענין קנין אשה בביאה, וגם שרק הבעל בכוחו לקנות אותה בכל בעילה שהיא.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: כיון שהביאה אינה מעשה רגעי אלא יש בה שלבים שונים, האם \u0003תחילת ביאה קונה או סוף ביאה קונה?\u0004 כלומר, מתי בדיוק הוא רגע הקנין? ומסבירים: \u0003נפקא מינה\u0004 \u0005[יוצא ממנה\u0006 משאלה זו\u0005]\u0006 הבדל למעשה \u0003כגון\u0004 שזה \u0003ש\u0004קידש אותה בביאה \u0003הערה בה,\u0004 כלומר, רק התחיל לבוא עליה, \u0003ו\u0004בינתיים \u0003פשטה ידה וקבלה קדושין מאחר.\u0004 שאם התחלת ביאה קונה — לא חלו קידושיו של האחר, ואם רק סוף ביאה קונה הרי היא מתקדשת בקידושיו של האחר.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יש הבדל \u0003ל\u0004מקרה של \u0003כהן גדול\u0004 \u0003דקא קני\u0004 \u0005[שקנה]\u0006 \u0003בתולה ב\u0004קנין \u0003ביאה,\u0004 שאם רק סוף ביאה קונה הרי אז כבר איננה בתולה, ואם כן לא יוכל כהן גדול לקנות אשה בביאה כלל, שהרי בעולה אסורה לו. \u0003מאי\u0004 \u0005[מה\u0006 אם כן הדין\u0005]?\u0006 \u0003אמר אמימר משמיה\u0004 \u0005[משמו\u0006 של\u0005]\u0006 \u0003רבא: כל הבועל\u0004 — \u0003דעתו על גמר ביאה\u0004 ולא על תחילתה, ולכן יש לומר אף כאן שהקנין נגמר רק בגמר ביאה.","ועוד \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: \u0003ביאה\u0004 של קידושין האם \u0003נשואין\u0004 היא \u0003עושה,\u0004 שהביאה נחשבת כמעשה קידושין ונישואין הבאים בבת אחת, \u0003או\u0004 רק \u0003אירוסין\u0004 היא \u0003עושה?\u0004 ולמעשה \u0003נפקא מינה\u0004 \u0005[יוצא מכאן]\u0006 הבדל לגבי הדינים שבהם יש הבדל בין ארוסה ונשואה — \u0003ליורשה,\u0004 שאם קידש אותה בביאה, האם הוא יורש אותה כשמתה כדין נשואה או לא.","\u0003ו\u0004אם הוא כהן האם חייב הוא \u0003ליטמא לה\u0004 כאשתו, \u0003ולהפר\u0004 לבדו, בלא האב, את \u0003נדריה. אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שהביאה \u0003נשואין עושה\u0004 אם כן \u0003יורשה ומיטמא לה ומיפר נדריה\u0004 לבדו, \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003אירוסין\u0004 בלבד היא \u0003עושה\u0004 — \u0003אינו יורשה ואינו מיטמא לה ואינו מיפר\u0004 את \u0003נדריה\u0004 לבדו. אם כן \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006","\u0003אמר אביי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003האב זכאי בבתו בקדושיה בכסף בשטר ובביאה, וזכאי במציאתה\u0004 של בתו \u0003ובמעשה ידיה, ובהפרת נדריה, ומקבל את גיטה\u0004 בשבילה כל זמן שהיא קטנה, \u0003ואינו אוכל פירות\u0004 נכסיה (שנפלו לה מבית אמה וכגון שירשה מבית אמה) \u0003בחייה.\u0004 אם \u0003נישאת\u0004 — \u0003יתר עליו הבעל\u0004 בזכויות \u0003שאוכל\u0004 גם \u0003פירות\u0004 נכסיה \u0003בחייה.\u0004","על כל פנים \u0003קתני\u0004 \u0005[שנה]\u0006 שזכאי בבתו ב\u0003ביאה, וקתני\u0004 \u0005[ושנה]\u0006 אחר כך \u0003\"נישאת\",\u0004 משמע שהביאה בלבד עושה רק אירוסין. ודוחים: \u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 \u0003\"נישאת\"\u0004 — \u0003אשארא\u0004 \u0005[\u0006הוא \u0005לגבי שאר\u0006 הדברים\u0005]\u0006 המוזכרים שם, כגון בקידושי כסף ושטר, שיש בהם הבדל בין קידושין ונישואין, ושמא בקידושי ביאה נעשים גם הנישואין.","\u0003אמר רבא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה, ממה ששנינו: \u0003בת שלש שנים ויום אחד מתקדשת בביאה, ואם בא עליה יבם\u0004 — \u0003קנאה, ו\u0004אם היתה נשואה — \u0003חייבין עליה משום אשת איש ומטמאה את בועלה\u0004 לשבעה ימים אם היא היתה נדה כדין הבועל את הנדה"],["\u0003לטמא משכב תחתון כעליון,\u0004 שהבועל נדה נטמא טומאה חמורה ומטמא כל מה ששוכב עליו גם אם לא נגע בו במישרין.","\u0003ואם נישאת לכהן\u0004 — הריהי \u0003אוכלת בתרומה\u0004 מאותה שעה, \u0003ואם בא עליה אחד מכל עריות שבתורה\u0004 — הם, האסורים לה \u0003מומתין על ידה\u0004 בעוון זה, \u0003והיא פטורה\u0004 שהרי קטנה היא ואינה בת עונשין. \u0003ואם בא עליה אחד מן הפסולין\u0004 (הפוסלים אשה לכהונה על ידי ביאתם) — \u0003פסלה מן הכהונה.\u0004 עד כאן לשון הברייתא.","ונדייק: \u0003קתני\u0004 \u0005[שנה\u0006 שם\u0005]\u0006 מתקדשת ב\u0003ביאה, וקתני\u0004 \u0005[ושנה]\u0006 בנפרד ואם \u0003נישאת\u0004 לכהן, משמע שעצם הביאה אינה עושה נישואין. ודוחים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 זו כוונת הברייתא: \u0003אי הני\u0004 \u0005[אם אלה]\u0006 קידושי הביאה \u0003נשואין\u0004 של \u0003כהן נינהו\u0004 \u0005[הם]\u0006 — \u0003אוכלת בתרומה.\u0004 ואין כאן איפוא שני דברים הבאים בזה אחר זה, ואין להוכיח מכאן שביאה אינה עושה נישואין.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003וכבר שלח יוחנן בן בג בג אצל ר' יהודה בן בתירה ל\u0004עיר \u0003נציבין,\u0004 וכך שלח לו: \u0003שמעתי עליך שאתה אומר ארוסה בת ישראל\u0004 שנתארסה לכהן \u0003אוכלת בתרומה. שלח לו\u0004 ר' יהודה בן בתירה בתשובה: \u0003ואתה אי\u0004 (אין) \u0003אתה אומר כן?\u0004 הלא \u0003מוחזקני\u0004 ויודע אני \u0003בך שאתה בקי בחדרי תורה,\u0004 וכי \u0003לדרוש בקל וחומר אי\u0004 (אין) \u0003אתה יודע?!\u0004","והרי קל וחומר הוא: \u0003ומה שפחה כנענית שאין ביאתה\u0004 שבא עליה כהן \u0003מאכילתה ב\u0004כך \u0003תרומה\u0004 ואינה מתקדשת לו, ובכל זאת \u0003כספה\u0004 (אם קונה אותה הכהן בכסף) \u0003מאכילתה בתרומה. זו\u0004 הארוסה, \u0003שביאתה\u0004 לכהן \u0003מאכילתה בתרומה\u0004 — \u0003אינו דין שכספה\u0004 (קידושי כסף שקידשה הכהן) \u0003מאכילתה בתרומה?\u0004 ואם כן מן התורה ארוסה בת ישראל אוכלת בתרומה, \u0003אבל מה אעשה שהרי אמרו חכמים: אין ארוסה בת ישראל אוכלת בתרומה עד שתכנס לחופה.\u0004","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 מדובר פה\u0005]\u0006 בהשוואה בין כסף לביאה? \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003בביאה שעל ידי\u0004 (כלומר, שלאחר) \u0003חופה, ו\u0004קידושי \u0003כסף ש\u0004הושלמו לנישואין \u0003על ידי חופה\u0004 — הלא \u0003בתרוייהו\u0004 \u0005[ב\u0006צירוף \u0005שניהם]\u0006 כסף וחופה על פי הדין \u0003מיכל אכלה\u0004 \u0005[היא אוכלת]\u0006 בתרומה גם מדברי סופרים?","\u0003ואלא\u0004 באיזה מקרה אמר בן בתירה שיש גזירת חכמים שלא תאכל — \u0003בביאה שעל ידי חופה, ו\u0004קידושי \u0003כסף שלא על ידי חופה.\u0004 ואומרים: אם כן הוא המקרה הרי אין כאן קל וחומר, כי \u0003הכא תרתי\u0004 \u0005[כאן\u0006 בביאה יש \u0005שתי\u0006 דרכי קנין\u0005],\u0006 ביאה וחופה, \u0003והכא חדא\u0004 \u0005[וכאן,\u0006 בכסף, רק דרך \u0005אחת].\u0006 \u0003אלא לאו\u0004 \u0005[אין\u0006 זאת אלא\u0005]\u0006 שההשוואה בין כסף לביאה היתה \u0003בביאה שלא על ידי חופה, וכסף שלא על ידי חופה.\u0004","ומכאן לענייננו: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שביאה בלבד \u0003נשואין עושה\u0004 — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 לר' יהודה בן בתירה \u0003דאלימא לה\u0004 \u0005[שחזקה\u0006 יותר\u0005]\u0006 \u0003ביאה מכסף. אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שביאה רק \u0003קדושין עושה,\u0004 אם כן \u0003מאי שנא הכא דפשיטא ליה\u0004 \u0005[מה\u0006 (מדוע) \u0005שונה כאן\u0006 בקידושי ביאה \u0005שפשוט לו]\u0006 שאוכלת בתרומה, \u0003ומאי שנא הכא דמספקא ליה\u0004 \u0005[ומה\u0006 (מדוע) \u0005שונה כאן\u0006 בקידושי כסף \u0005שמסופק לו]\u0006 וצריך ללמוד מקל וחומר, והרי בשני המקרים היא כארוסה בלבד.","\u0003אמר רב נחמן בר יצחק: לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 שכאן מדובר \u0003בביאה שעל ידי חופה וכסף שלא על ידי חופה. ודקאמרת\u0004 \u0005[ומה שאתה אומר]\u0006 כנגד קל וחומר זה: \u0003הכא תרתי והכא חדא\u0004 \u0005[כאן\u0006 יש \u0005שתי\u0006 דרכי קנין \u0005וכאן\u0006 יש רק \u0005אחת]\u0006 — \u0003קל וחומר מיהא איתיה\u0004 \u0005[מכל מקום ישנו].\u0006","\u0003והכי שלח ליה\u0004 \u0005[וכך שלח לו],\u0006 כך יש להסביר את דברי ר' יהודה בן בתירה: \u0003ומה שפחה כנענית שאין ביאתה מאכילתה בתרומה אפילו על ידי חופה\u0004 — בכל זאת \u0003כספה מאכילתה בלא חופה, זו,\u0004 ארוסה בת ישראל, \u0003שביאתה מאכילתה בתרומה על ידי חופה\u0004 — \u0003אינו דין שכספה מאכילתה בתרומה\u0004 אפילו \u0003בלא חופה?\u0004","\u0003אבל מה אעשה שהרי אמרו חכמים: אין ארוסה בת ישראל אוכלת בתרומה עד שתכנס לחופה משום\u0004 טעמו של \u0003עולא\u0004 שאנו חוששים שמא בבית אביה יאכלו אחיה ובני משפחתה מן התרומה שברשותה.","\u0003ובן בג בג\u0004 מסביר מדוע אין ללמוד קל וחומר זה משפחה כנענית, שכן \u0003גבי\u0004 (אצל) \u0003שפחה כנענית\u0004 כשקונה אותה בכסף \u0003לא שייר בקנינה\u0004 וגמר את כל מעשה הקנין שיכול לחול עליה, אבל \u0003הכא\u0004 \u0005[כאן]\u0006 בקידושין, \u0003שייר בקנינה,\u0004 שקנין האירוסין הוא רק קנין ראשון, ועדיין יש קנין נוסף של נישואין, ואין הדברים דומים.","\u0003רבינא אמר\u0004 שלדעתו יש להבין את כל הענין באופן אחר, ואפילו אם ביאה אינה עושה נישואין \u0003מדאורייתא\u0004 \u0005[מן התורה]\u0006 — \u0003מיפשט פשיטא ליה דאכלה\u0004 \u0005[פשוט לו\u0006 לר' יוחנן בן בג בג \u0005ש\u0006היא \u0005אוכלת]\u0006 בתרומה גם כשנתקדשה בכסף בלבד, שכן היא \"קנין כספו\" \u0003ומדרבנן\u0004 \u0005[ו\u0006לגבי ההלכה \u0005מדברי סופרים]\u0006 \u0003הוא\u0004 ש\u0003שלח ליה\u0004 \u0005[לו].\u0006","\u0003והכי\u0004 \u0005[וכך]\u0006 \u0003שלח ליה\u0004 \u0005[לו]:\u0006 \u0003שמעתי עליך שאתה אומר\u0004 הלכה למעשה \u0003ארוסה בת ישראל אוכלת בתרומה, ולא חיישת לסימפון\u0004 \u0005[ואין אתה חושש לביטול\u0006 הקנין\u0005]\u0006 שמא ימצא בה מום ויתגלה שהיו אלה קידושי טעות ונמצא שאכלה תרומה שלא כדין. ועל כך \u0003שלח ליה\u0004 \u0005[לו]\u0006 ר' יהודה בן בתירה: \u0003ואתה אי\u0004 (אין) \u0003אתה אומר כן? מוחזקני בך שאתה בקי בחדרי תורה, לדרוש בקל וחומר אי\u0004 (אין) \u0003אתה יודע?!\u0004","וכך תאמר: \u0003ומה שפחה כנענית שאין ביאתה מאכילתה בתרומה\u0004 — בכל זאת \u0003כספה מאכילתה בתרומה, ולא חיישינן לסימפון\u0004 \u0005[ואין אנו חוששים לביטול\u0006 מיקח\u0005],\u0006 \u0003זו שביאתה מאכילתה בתרומה\u0004 שבודאי בדקה קודם הביאה, ואין כאן חשש לביטול — \u0003אינו דין שכספה מאכילתה בתרומה, ולא ניחוש לסימפון\u0004 \u0005[נחשוש לביטול\u0006 מיקח\u0005]\u0006 פה? \u0003אבל מה אעשה שהרי אמרו חכמים: ארוסה בת ישראל אינה אוכלת בתרומה\u0004"],["\u0003עד שתכנס לחופה, משום\u0004 טעמו של \u0003עולא\u0004 שמא יאכלו גם בני משפחתה שאינם כהנים מן התרומה שניתנה לארוסה.","ושואלים: \u0003ובן בג בג\u0004 מה הוא אומר על קל וחומר זה? ומשיבים כי לדעתו אין מקום להשוואה ולקל וחומר כי \u0003סימפון\u0004 \u0005[ביטול\u0006 מיקח\u0005]\u0006 בעבדים, \u0003לית ליה\u0004 \u0005[אין לו],\u0006 אינו יכול להיות. כי \u0003אי\u0004 \u0005[אם]\u0006 \u0003מומין שבגלוי הוא\u0004 שמצא בעבד — \u0003הא קא חזי ליה\u0004 \u0005[הרי ראה אותו]\u0006 קודם לכן וראה גם את מומיו ועל דעת כן קנה אותו, ולכן אין לו אחר כך זכות טענת מיקח טעות. \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום מומין שבסתר\u0004 שמצא בו — \u0003מאי נפקא ליה מיניה\u0004 \u0005[מה יוצא לו מזה]\u0006 אם יש בעבד מומים שבסתר? הלא רק \u0003למלאכה קא בעי ליה\u0004 \u0005[צריך אותו]\u0006 ו\u0003לא איכפת ליה\u0004 \u0005[לו]\u0006 אם יש לו מומים בסתר שאינם מגבילים אותו בעבודה.","ואף אם \u0003נמצא\u0004 שהעבד הוא \u0003גנב או קוביוסטוס\u0004 (משחק בקוביה) שהם מומים שבסתר, ומפריעים גם למלאכה — \u0003הגיעו\u0004 (\"נשאר בידו\") העבד, ללוקח, שאינו יכול לחזור בו, והקונה הפסיד, משום שהיה הקונה צריך לחשוש לפגם כזה שרוב העבדים לוקים בו. \u0003מאי אמרת\u0004 \u0005[מה אתה אומר]\u0006 שהמום שגילה רק לאחר הקניה היה שהעבד הוא \u0003לסטים\u0004 (שודד) \u0003מזויין\u0004 החייב מיתה, \u0003או נכתב למלכות\u0004 שחייב מיתה ומבוקש על ידי השלטונות — \u0003הנהו קלא אית להו\u0004 \u0005[אלה קול\u0006 (פירסום) \u0005יש להם],\u0006 ובודאי קיבל עליו סיכון זה, כשקנה אותו.","ושואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003בין למר\u0004 \u0005[ל\u0006דעת \u0005חכם\u0006 זה\u0005],\u0006 ר' יוחנן בן בג בג, \u0003ובין למר\u0004 \u0005[ל\u0006דעת \u0005חכם\u0006 זה\u0005],\u0006 ר' יהודה בן בתירה, ארוסה \u0003לא אכלה\u0004 \u0005[אינה אוכלת]\u0006 בתרומה מגזירת חכמים, ואם כן \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל למעשה \u0005ביניהם]?\u0006","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה לגבי ההלכות שסימנן: \"קיבל\", \"מסר\" ו\"הלך\". שאם \u0003קיבל\u0004 עליו הבעל את המומים מראש, שאז אין חשש לסימפון אך יש חשש שתאכיל את בני משפחתה בתרומה, או אם \u0003מסר\u0004 האב את האשה לשלוחי הבעל, או ש\u0003הלך\u0004 שליח האב עם שלוחי הבעל ואינה עוד בבית אביה, שבשני מקרים אלה אין חשש שתבוא להאכיל בתרומה את בני משפחתה אך יש חשש לסימפון.","מכאן שבים לביאור עיקרי הדינים שבמשנה. שנינו שאם מקדש \u0003בכסף, בית שמאי אומרים\u0004 שעליו לקדש לפחות \u0003בדינר,\u0004 ולבית הלל די בפרוטה. ושואלים: \u0003מאי טעמייהו\u0004 \u0005[מה טעמם]\u0006 של \u0003בית שמאי? אמר ר' זירא: שכן אשה מקפדת על עצמה\u0004 ומזולזל בעיניה שתהא נקנית בסכום פעוט, \u0003ו\u0004לכן \u0003אין\u0004 היא \u0003מתקדשת בפחות מדינר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה\u0004 לפי נימוק זה \u0003כגון בנתיה\u0004 \u0005[בנותיו]\u0006 של \u0003ר' ינאי, דקפדן אנפשייהו\u0004 \u0005[שמקפידות על עצמן]\u0006 ועל כבודן ביותר, \u0003ולא מקדשי בפחות מתרקבא דדינרי\u0004 \u0005[ואינן מתקדשות\u0006 לפי חשיבותן \u0005בפחות מכלי\u0006 מלא \u0005דינרים]\u0006 \u0003הכי נמי דאי פשטה\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שאם תפשוט]\u0006 \u0003ידה וקבלה חד זוזא\u0004 \u0005[ותקבל דינר אחד]\u0006 \u0003מאחר הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003לא הוו\u0004 \u0005[יהיו]\u0006 אלה \u0003קדושין?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 במקרה ש\u0003פשטה ידה וקבלה לא קאמינא\u0004 \u0005[אינני אומר],\u0006 שאם היא מוותרת מרצונה על כבודה — היא יכולה לוותר כמה שהיא רוצה, \u0003כי קאמינא\u0004 \u0005[כאשר אני אומר]\u0006 הוא כגון ש\u0003קדשה בליליא\u0004 \u0005[בלילה]\u0006 והיא לא ראתה במה הוא מקדש אותה, \u0003אי נמי דשויה\u0004 \u0005[או גם כן שמינתה]\u0006 \u0003שליח\u0004 להתקדש, ולא אמרה לשליח במפורש בכמה כסף רצונה להתקדש, שמן הסתם מקפידה היא על כבודה ואינה מתקדשת בפחות מדינר.","\u0003רב יוסף אמר\u0004 טעם אחר: \u0003טעמיהו\u0004 \u0005[טעמם]\u0006 של \u0003בית שמאי כ\u0004דברי \u0003רב יהודה אמר רב אסי.\u0004 ש\u0003אמר רב יהודה אמר רב אסי: כל\u0004 סכום \u0003כסף האמור בתורה\u0004 הוא \u0003כסף צורי\u0004 (בדינרים צוריים) שערכם רב, \u0003ו\u0004סכום כסף \u0003של דבריהם\u0004 שקבעוהו חכמים, נקוב \u0003בכסף מדינה,\u0004 שכל מטבע שבו ערכו רק שמינית מערכו של המטבע הצורית. ובית שמאי הולכים לפי השיעור האמור בתורה, והמטבע הקטנה ביותר בכסף צורי הוא מטבע כסף, השווה בערכו לדינר.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של הלכה זו שהזכרנו \u0003אמר רב יהודה אמר רב אסי: כל כסף האמור בתורה\u0004 הוא \u0003כסף צורי ו\u0004כל כסף \u0003של דבריהם\u0004 הוא \u0003כסף מדינה.\u0004 שואלים: \u0003וכללא\u0004 \u0005[ו\u0006האם \u0005כלל]\u0006 \u0003הוא\u0004 שכל כסף האמור בתורה הוא מטבע כסף דווקא ולפחות דינר?"],["\u0003והרי\u0004 דין זה של \u0003טענה\u0004 שטוען אדם על חבירו שחייב לו כסף אם משום שלא החזיר לו את פקדונו או הלוואתו, וחבירו מודה לו רק במקצת הטענה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי יתן איש אל רעהו כסף או כלים לשמור\u0004 וגנב מבית האיש...\u0003\"\u0004 (שמות כב, ו), \"...עד האלהים יבוא דבר שניהם\" (שם, ח) ופירושו שדין זה בא לפני הדיינים, ומשביעים את הנתבע. \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 בדין מודה מקצת הטענה: \u0003שבועת הדיינין,\u0004 כלומר, שבועה זו שהדיינים משביעים את זה שהודה במקצת היא כאשר \u0003הטענה\u0004 (התביעה) היא על \u0003שתי\u0004 מעות \u0003כסף\u0004 לפחות, \u0003וההודאה\u0004 שמודה הנתבע אפילו ב\u0003שוה פרוטה.\u0004 ואם כל \"כסף\" האמור בתורה הוא כסף צורי, כיצד הגיעו חכמים לסכום זה של שתי מעות דווקא?","ודוחים: \u0003התם\u0004 \u0005[שם]\u0006 יש לימוד מיוחד בגלל ההיקש, ש\"כסף\" שנזכר שם הוא \u0003דומיא\u0004 \u0005[\u0006ב\u0005דומה]\u0006 ל\u0003כלים, מה כלים\u0004 משמע לפחות \u0003שנים\u0004 — \u0003אף כסף שנים, ומה כסף\u0004 הוא \u0003דבר חשוב\u0004 — \u0003אף\u0004 ב\u0003כלים\u0004 מדובר דווקא ב\u0003דבר חשוב.\u0004","ומקשים: \u0003והרי מעשר דכתיב\u0004 \u0005[שנאמר]\u0006 בו, בפדיונו \u0003\"וצרת הכסף בידך\"\u0004 (דברים יד, כה) \u0003ותנן\u0004 \u0005[ו\u0006אף על פי כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הפורט סלע ממעות מעשר שני,\u0004 משמע שאפשר לפרוט את כסף המעשר אף לפרוטות נחושת, ולאו דווקא מעות כסף! ומשיבים: כיון שלא נאמר \u0003\"כסף\"\u0004 אלא \u0003\"הכסף\"\u0004 הה\"א היתירה \u0003ריבה,\u0004 שהיא באה ללמדנו שאפשר לפדותו בכל מיני כסף, ואף בפרוטות של נחושת.","ומקשים: \u0003והרי הקדש דכתיב\u0004 \u0005[שנאמר]\u0006 בו \u0003\"ונתן הכסף וקם לו\"\u0004 (ראה ויקרא כז, יט) \u0003ואמר שמואל: הקדש,\u0004 אפילו היה \u0003שוה מנה, שחיללו על שוה פרוטה\u0004 — \u0003מחולל!\u0004 והרי, \"כסף\" נאמר במקרא, ובכל אופן יוצא ידי חובה בפרוטות נחושת! ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 יש לימוד מיוחד המלמד דין זה, שכן \u0003\"כסף\" \"כסף\" יליף\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003ממעשר,\u0004 ולכן גם שם מדובר בכסף (ממון) כלשהו.","ומקשים: \u0003והרי קידושי אשה דכתיב\u0004 \u0005[שנאמר]\u0006 בהם \u0003\"כי יקח איש אשה ובעלה\"\u0004 (דברים כד, א) \u0003וגמר\u0004 \u0005[ולמד]\u0006 קידושי כסף בגזירה שווה \u0003\"קיחה\" \"קיחה\" משדה עפרון,\u0004 ושם נזכר \"כסף\", \u0003ו\u0004בכל זאת \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 \u0003בית הלל אומרים: בפרוטה ובשוה פרוטה.\u0004 ואם כן \u0003נימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 ש\u0003רב אסי\u0004 שאמר שכל כסף האמור בתורה הוא כסף צורי הוא ש\u0003אמר כבית שמאי\u0004 דווקא?!","\u0003אלא\u0004 יש לדחות את כל מה שאמרנו ולפרש כך: \u0003אי איתמר, הכי איתמר\u0004 \u0005[אם נאמר, כך נאמר]:\u0006 \u0003אמר רב יהודה אמר רב אסי: כל\u0004 סכום \u0003כסף קצוב\u0004 (שמפורש בו סכום מסויים) \u0003האמור בתורה\u0004 הריהו \u0003כסף צורי, ו\u0004כסף \u0003של דבריהם\u0004 — \u0003כסף מדינה.\u0004","ומקשים: אם כן הוא \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך? הלא \u0003תנינא\u0004 \u0005[שנינו]\u0006 כל דינים אלה במפורש: תשלומי \u0003חמש סלעים של\u0004 פדיון ה\u0003בן, שלשים של עבד\u0004 שנהרג על ידי שור שמשלם בעל השור, \u0003חמשים של אונס ושל מפתה, מאה של מוציא שם רע\u0004 — \u0003כולם בשקל הקודש, במנה צורי,\u0004 הרי שכל המקומות שנאמר בהם בתורה סכום קצוב כבר פורשו כאן ומה השמיע לנו רבי אסי!","ומשיבים: מה שאמר \u0003ושל דבריהם כסף מדינה איצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 לומר, ש\u0003לא תנן\u0004 \u0005[שנינו]\u0006 כלל זה במשנה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003התוקע\u0004 (מכה) \u0003לחבירו\u0004 בדרך בזיון — \u0003נותן לו\u0004 כקנס \u0003סלע,\u0004 שכך קבעו חכמים. \u0003ולא תימא\u0004 \u0005[ואל תאמר]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003סלע\u0004 שהוא סלע צורי שהוא \u0003ארבע זוזי\u0004 (ארבעה דינרים) \u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003סלע\u0004 — סלע מדינה ששוויו \u0003פלגא דזוזא\u0004 \u0005[חצי זוז],\u0006 \u0003דעבידי אינשי דקרו לפלגא דזוזא איסתירא\u0004 \u0005[שעשויים אנשים לקרוא לחצי זוז\u0006 גם כן \u0005סלע].\u0006","\u0003ר' שמעון בן לקיש אומר\u0004 הסבר אחר: \u0003טעמייהו\u0004 \u0005[טעמם]\u0006 של \u0003בית שמאי\u0004 שקידושי אשה הם בדינר, \u0003כ\u0004דברי \u0003חזקיה.\u0004 ש\u0003אמר חזקיה: אמר קרא\u0004 \u0005[הכתוב]\u0006 באמה העבריה (שהיא אמנם שפחה, אלא שברשות האדון גם לעשותה לאשתו): \u0003\"והפדה\"\u0004 (שמות כא, ח) — \u0003מלמד שמגרעת\u0004 (מנכה) \u0003מפדיונה,\u0004 שאם הגיע לידה כסף הריהי משלמת לאדון בניכוי שווי העבודה שעשתה \u0003ויוצאה\u0004 טרם זמנה.","\u0003אי אמרת בשלמא דיהב\u0004 \u0005[אם נניח אתה אומר\u0006 שהוא \u0005נותן]\u0006 \u0003לה\u0004 בשעת קנייתה \u0003דינר\u0004 לפחות, \u0003היינו דמגרעה ואזלה\u0004 \u0005[זהו ש\u0006היא \u0005מגרעת\u0006 מהסכום הזה \u0005והולכת]\u0006 \u0003עד\u0004 כדי \u0003פרוטה, אלא אי אמרת דיהב\u0004 \u0005[אם אתה אומר ש\u0006הוא \u0005נותן]\u0006 \u0003לה פרוטה\u0004 בקנין ראשון כשקנה אותה לשפחה, \u0003מפרוטה מי מגרעה\u0004 \u0005[האם\u0006 יכולה היא \u0005לגרוע]?\u0006 והרי פרוטה הוא השיעור הקטן ביותר של כסף! ודוחים: \u0003ודלמא הכי קאמר רחמנא\u0004 \u0005[ושמא כך אמרה תורה],\u0006 זה כוונת העניין: \u0003היכא דיהב\u0004 \u0005[\u0006ב\u0005מקום שנתן]\u0006 \u0003לה דינר\u0004 — \u0003תיגרע\u0004 את הסכום הזה \u0003עד פרוטה, היכא דיהב\u0004 \u0005[\u0006ב\u0005מקום שנתן]\u0006 \u0003לה פרוטה\u0004 — \u0003לא תיגרע כלל!\u0004 ובמקרה זה לא יתקיים דין \"והפדה\"."],["ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[\u0006יכול \u0005לעלות על דעתך]\u0006 הסבר זה, ומדוע? — כי דין גרעון צריך להיות \u0003דומיא\u0004 \u0005[בדומה]\u0006 לדין \u0003ייעוד,\u0004 שהאדון רשאי לייעדה לו לאשה, \u0003מה ייעוד אף על גב\u0004 (אף על פי) \u0003דאי בעי\u0004 \u0005[שאם רוצה]\u0006 הריהו \u0003מייעד ואי בעי לא\u0004 \u0005[ואם רוצה אינו]\u0006 \u0003מייעד,\u0004 ומכל מקום \u0003כל היכא דלא מצי מייעד לא הוו זבינא זביני\u0004 \u0005[כל מקום שאינו יכול לייעד,\u0006 כגון שאסורה לו משום קירבת משפחה, \u0005אין קנינו קנין],\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003כל היכא דלא מצי מיגרעא\u0004 \u0005[מקום\u0006 שאינה יכולה לגרוע] — \u0003לא הוו זבינא זביני\u0004 \u0005[אין מכירתה מכר].\u0006","\u0003ו\u0004לענייננו: \u0003קידושי אשה\u0004 בכסף \u0003לבית שמאי נפקא להו\u0004 \u0005[יוצא להם]\u0006 למדים הם \u0003מאמה העבריה,\u0004 אם כן יש גם ללמוד: \u0003מה אמה העבריה בפרוטה לא מקניא\u0004 \u0005[אינה נקנית],\u0006 \u0003אף אשה בפרוטה לא מיקדשא\u0004 \u0005[אינה מתקדשת].\u0006","ושואלים: גם אם בית שמאי למדו מכאן, מכל מקום מהיכן למדו שאין מתקדשים אלא בדינר דווקא? \u0003ואימא\u0004 \u0005[ו\u0006אולי \u0005אומר]\u0006 שתתקדש ב\u0003פלגא דדינר\u0004 \u0005[חצי דינר],\u0006 \u0003ואימא\u0004 \u0005[ואומר]\u0006 \u0003שתי פרוטות\u0004 שעדיין יש בהן כדי לקיים דין גרעון באמה עבריה! ומשיבים: \u0003כיון דאפיקתיה\u0004 \u0005[שהוצאת אותו]\u0006 את הדין הזה \u0003מפרוטה\u0004 — שאינה יכולה להתקדש בה וצריך אתה להעמיד את הדין על כסף שיש בו חשיבות, \u0003אוקמה אדינר\u0004 \u0005[העמידנו על דינר]\u0006 שהוא מטבע חשוב.","\u0003רבא אמר: היינו טעמא\u0004 \u0005[זהו טעמם]\u0006 של \u0003בית שמאי:\u0004 שמתקדשת דווקא בדינר כדי \u0003שלא יהו בנות ישראל כהפקר,\u0004 כי אם מקדשים אותן בסכום קטן כלשהו יש בדבר צד זלזול והן נעשות בכך כהפקר לכל.","על מה ששנינו במשנה \u0003ובית הלל אומרים בפרוטה\u0004 ובשוה פרוטה, \u0003סבר\u0004 \u0005[חשב]\u0006 \u0003רב יוסף למימר\u0004 \u0005[לומר]:\u0006 \u0003פרוטה\u0004 הכוונה \u0003כל דהו\u0004 \u0005[כלשהו],\u0006 כלומר, אין לכך ערך קצוב אלא מטבע קטן כלשהו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא עלה קתני\u0004 \u0005[והרי עליה שנינו\u0006 בברייתא\u0005]\u0006 כהסבר: \u0003כמה היא פרוטה\u0004 — \u0003אחד משמנה באיסר האיטלקי.\u0004 הרי שיש שיעור לפרוטה!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 כי \u0003הני מילי\u0004 \u0005[אלו הדברים]\u0006 אמורים דווקא \u0003בדורו של משה,\u0004 שזה היה ערך הפרוטה בזמן התורה \u0003אבל הכא כדחשבה להו לאינשי\u0004 \u0005[כאן,\u0006 עכשיו ובכל זמן, \u0005כמו ש\u0006היא \u0005נחשבת לבני אדם]\u0006 כל שיהיה המטבע הקטן ביותר — \u0003והא\u0004 \u0005[והרי]\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר: שיער ר' סימאי בדורו כמה היא פרוטה: אחד משמנה באיסר האיטלקי, וכי אתא\u0004 \u0005[וכאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר: ר' דוסתאי ור' ינאי ור' אושעיא שיערו כמה הוי פרוטה\u0004 — \u0003אחד מששה באיסר האיטלקי!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף: אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003היינו דתנינא\u0004 \u0005[זהו ששנינו]\u0006 \u0003צא וחשוב כמה פרוטות בשני סלעים\u0004 — \u0003יותר מאלפים, השתא\u0004 \u0005[עכשיו]\u0006 הרי \u0003אלפים לא הויין\u0004 \u0005[אינן],\u0006 \u0003יתר מאלפים\u0004 אתה \u0003קרי להו\u0004 \u0005[קורא אותן]?\u0006 אלא ודאי שהפרוטה היא מטבע קטנה יותר! \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ההוא סבא\u0004 \u0005[זקן אחד]:\u0006 \u0003אנא תנינא לה\u0004 \u0005[אני שונה\u0006 ברייתא \u0005זו]\u0006 \u0003קרוב לאלפים.\u0004 ומקשים גם על כך: \u0003סוף סוף\u0004 לפי החשבון של אחד משמונה באיסר \u0003אלפא וחמש מאה ותלתין ושיתא הוא דהויין\u0004 \u0005[אלף וחמש מאות ושלושים ושש הן]\u0006 ולא אלפיים! ומשיבים: \u0003כיון דנפקא להו מפלגא\u0004 \u0005[שיוצא,\u0006 עובר יותר \u0005מחצי]\u0006 האלף השני — \u0003קרוב לאלפים קרי ליה\u0004 \u0005[קורא לו].\u0006","\u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה שהזכרנו, \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי אמר: שיער ר' סימאי בדורו כמה היא פרוטה\u0004 — \u0003אחד משמנה באיסר האיטלקי, וכי אתא\u0004 \u0005[וכאשר בא]\u0006 \u0003רבין אמר: שיערו ר' דוסתאי ור' ינאי ור' אושעיא כמה היא פרוטה\u0004 — \u0003אחד מששה באיסר האיטלקי. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב דימי: נימא את\u0004 \u0005[האם נאמר\u0006 ש\u0005אתה]\u0006 \u0003ורבין בפלוגתא דהני תנאי קא מיפלגיתו\u0004 \u0005[במחלוקתם של תנאים אלה אתם חלוקים],\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003פרוטה שאמרו חכמים\u0004 הריהי \u0003אחד משמנה באיסר האיטלקי. שש מעה כסף\u0004 הרי הן \u0003דינר.\u0004 ב\u0003מעה\u0004 יש \u0003שני פונדיונין,\u0004 ב\u0003פונדיון\u0004 יש \u0003שני איסרין,\u0004 ב\u0003איסר\u0004 יש \u0003שני מוסמיסים,\u0004 ב\u0003מסמס\u0004 יש \u0003שני קונטרונקין,\u0004 ב\u0003קונטרנק\u0004 יש \u0003שתי פרוטות. נמצא\u0004 ש\u0003פרוטה\u0004 היא \u0003אחת משמנה באיסר האיטלקי.\u0004","\u0003רבן שמעון בן גמליאל אומר:\u0004 לא כך, אלא \u0003שלשה הדרסין למעה, שני הנצין להדריס, שני שמנין להנץ, שתי פרוטות לשמין, נמצא\u0004 לפי חשבון זה ש\u0003פרוטה\u0004 היא \u0003אחת מששה באיסר האיטלקי. לימא דמר\u0004 \u0005[\u0006האם \u0005נאמר שאדוני]\u0006 \u0003אמר כ\u0004שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003ורבין\u0004 ש\u0003אמר\u0004 את דבריו היה זה \u0003כ\u0004שיטת \u0003רבן שמעון בן גמליאל?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בין דידי\u0004 \u0005[\u0006דברי \u0005שלי]\u0006 \u0003ובין\u0004 דברי \u0003רבין\u0004 שתיהן \u0003אליבא דתנא קמא\u0004 \u0005[לפי\u0006 שיטת \u0005תנא קמא]\u0006 \u0003ולא קשיא\u0004 \u0005[ואין זה קשה];\u0006 \u0003הא\u0004 \u0005[זה,\u0006 דברי\u0005]\u0006 — \u0003דאיקור איסורי, הא\u0004 \u0005[זה, דברי רבין]\u0006 — \u0003דזול איסורי\u0004 \u0005[שהוזלו האיסרים]\u0006 לגבי מטבעות הכסף. ומפרטים: \u0003הא דאיקור איסורי\u0004 \u0005[זה שהתייקרו האיסרים]\u0006 — \u0003קום עשרים וארבע בזוזא\u0004 \u0005[עמדו עשרים וארבע\u0006 איסרים \u0005בזוז,\u0006 בדינר\u0005],\u0006 \u0003הא דזול\u0004 \u0005[זה שהוזלו]\u0006 — \u0003קום תלתין ותרין בזוזא\u0004 \u0005[עמדו שלושים ושנים\u0006 איסרים \u0005בזוז]\u0006 שיש יחס קבוע בין הפרוטה וערך הכסף, שיש בדינר מאה תשעים ושתים פרוטות, אבל באיסרים, שהם מטבעות נחושת, משתנים הערכים לגבי הכסף, ופעמים שיש באיסר שמונה פרוטות, ופעמים שרק שש.","\u0003אמר שמואל: קידשה\u0004 את האשה \u0003בתמרה\u0004 אחת \u0003אפילו עומד\u0004 (שווה) \u0003כור תמרים בדינר\u0004 ואם כן תמרה אחת שווה הרבה פחות מפרוטה — \u0003מקודשת.\u0004 וטעם הדבר — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 אף שכאן ערכה מועט \u0003שמא שוה פרוטה במדי\u0004 או במקום רחוק אחר ששם הן יקרות והרי היא מקודשת גם כאן.","ומקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003בית הלל אומרים בפרוטה ובשוה פרוטה\u0004 ולא פחות! ודוחים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שנאמר במשנה מדובר \u0003בקידושי ודאי\u0004 שבפרוטה ובשווה פרוטה היא ודאי מקודשת, \u0003הא\u0004 \u0005[זה]\u0006 שאמר שמואל הרי זה \u0003בקידושי ספק,\u0004 שאפילו בפחות מפרוטה יש לחשוש לקידושין.","מסופר: \u0003ההוא גברא דאקדיש בזוודא דאורדי\u0004 \u0005[אדם אחד שקידש\u0006 אשה \u0005בחבילת סמרטוטים],\u0006 \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב שימי בר חייא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב וקא מעיין\u0004 \u0005[והיה בודק]\u0006 \u0003בה\u0004 בחבילה זו \u0003אי אית\u0004 \u0005[אם יש]\u0006 \u0003בה שוה פרוטה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 תהא מקודשת, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא\u0004 מקודשת. ושואלים: \u0003ואי לית\u0004 \u0005[ואם אין]\u0006 \u0003בה שוה פרוטה\u0004 האם היא \u0003לא\u0004 מקודשת? \u0003והאמר\u0004 \u0005[והרי]\u0006 \u0003שמואל חיישינן\u0004 \u0005[\u0006ש\u0005חוששים אנו]\u0006 שמא דבר כגון זה שווה פרוטה במקום אחר! ודוחים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 \u0003בקידושי ודאי\u0004 שרצה לבדוק אם יש בה שווה פרוטה ואז האשה מקודשת קידושי ודאי, \u0003הא\u0004 \u0005[זה]\u0006 שאמר שמואל שמקודשת אפילו בפחות, הוא \u0003בקידושי ספק,\u0004 שיש רק לחשוש לקידושין.","מסופר: \u0003ההוא גברא דאקדיש באבנא דכוחלא\u0004 \u0005[אדם אחד שקידש\u0006 אשה \u0005באבן שיש כחולה]\u0006 \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב חסדא וקא משער ליה\u0004 \u0005[והיה מעריך אותה]\u0006 \u0003אי אית ביה\u0004 \u0005[אם יש בה]\u0006 \u0003שוה פרוטה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 תהא מקודשת, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — הריהי \u0003לא\u0004 מקודשת. ושואלים: \u0003ואי לית ביה\u0004 \u0005[ואם אין בה]\u0006 \u0003שוה פרוטה\u0004 האם \u0003לא\u0004 תהא מקודשת? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר שמואל: חיישינן\u0004 \u0005[חוששים אנו]\u0006 שמא היא שווה פרוטה במקום אחר? ומשיבים: \u0003רב חסדא לא סבר ליה\u0004 \u0005[אינו ססובר]\u0006 כדעת \u0003שמואל\u0004 ולדעתו אם במקום הקידושין אין בה שווה פרוטה — אינה מקודשת כלל.","\u0003אמרה ליה אימיה\u0004 \u0005[אמרה לו אמו]\u0006 של המקדש, לרב חסדא: \u0003והא ההוא יומא\u0004 \u0005[והרי באותו יום]\u0006 ש\u0003קדשה הוה ביה\u0004 \u0005[היה בו]\u0006 בדבר \u0003שוה פרוטה! אמר לה\u0004 לאם: \u0003לאו כל כמינך דאסרת לה אבתרא\u0004 \u0005[אין זה בכוחך לאסור אותה על האחרון],\u0006 שאם יבוא איש אחר ויקדש אותה אין לבטל את קידושיו משום שהיתה מקודשת לראשון, שכיון שעכשיו אין בה שווה פרוטה יש לחשוש לקידושי השני."],["\u0003לאו היינו\u0004 \u0005[\u0006האם \u0005אין זה]\u0006 אותו מעשה של \u0003יהודית דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003ר' חייא, דהוית\u0004 \u0005[שהיה]\u0006 \u0003לה צער לידה,\u0004 שהיתה יולדת בכאבים, ורצתה לצאת בשל כך מר' חייא, \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אמרה לי אם\u0004 (אמי): \u0003קיבל ביך אבוך קידושי כי זוטרת\u0004 \u0005[קיבל בך,\u0006 עבורך, \u0005אביך קידושין\u0006 מאחר \u0005כאשר היית קטנה]\u0006 ויש לחשוש שמא היתה מקודשת מקודם לאיש אחר, ואסורה היא לר' חייא. \u0003אמר לה: לאו כל כמינה דאימך דאסרת ליך עילואי\u0004 \u0005[אין זה בכוחה של אמך שתאסור אותך עלי],\u0006 שאין זו עדות שלימה.","\u0003אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]\u0006 \u0003לרב חסדא: אמאי\u0004 \u0005[מדוע]\u0006 אתה אומר שאינה מקודשת אם אין בה עכשיו שווה פרוטה? \u0003הא איכא סהדי\u0004 \u0005[הרי יש עדים]\u0006 \u0003ב\u0004מקום \u0003אידית דידעי דבההוא יומא הוה ביה\u0004 \u0005[שיודעים שבאותו יום היה בו]\u0006 \u0003שוה פרוטה?\u0004 אמר להם: \u0003השתא מיהא לא ליתנהו קמן\u0004 \u0005[עכשיו על כל פנים אין הם לפנינו]\u0006 ואין אנו צריכים לחשוש לעדותם.","והביא ראיה לדבריו, \u0003לאו היינו\u0004 \u0005[\u0006האם \u0005אין זו]\u0006 כשיטת \u0003ר' חנינא,\u0004 שבאה אשה לפני בית דין ואמרה שנשבתה אבל טהורה היא, ואף שאמרו שהיו עדים במקום אחר המעידים שנשבתה, ואם כן אין לסמוך על דבריה ש\u0003אמר ר' חנינא:\u0004 וכי אם \u0003עידיה\u0004 נמצאים \u0003בצד אסתן\u0004 (צפון) אי שם, \u0003ו\u0004משום כך \u0003תיאסר?!\u0004","ומעירים: \u0003אביי ורבא לא סבירא להו להא\u0004 \u0005[לא סברו,\u0006 לא קיבלו \u0005את\u0006 דעתו \u0005זו]\u0006 של \u0003רב חסדא\u0004 בקידושין, שלדעתם אין ללמוד מדברי ר' חנינא, שכן יש להבדיל בין המקרים: \u0003אם\u0004 בדינו של ר' חנינא \u0003הקילו בשבויה דמנוולה נפשה גבי שבאי\u0004 \u0005[שמנוולת\u0006 את \u0005עצמה אצל\u0006 ה\u0005שבאי]\u0006 ומשתדלת להיראות בפניו דוחה כדי שלא יאנוס אותה, ולכן יש סברה שלא נאנסה ומשום כך לא חשש ר' חנינא לעדי שבייה הנמצאים במקום אחר, והתירה — האם \u0003ניקיל\u0004 \u0005[נקל]\u0006 \u0003ב\u0004איסור חמור של \u0003אשת איש?!\u0004","מספרים: \u0003אישתאר מההיא\u0004 \u0005[נשאר מאותה]\u0006 \u0003משפחה בסורא,\u0004 שאותה בת שפסק רב חסדא שאין קידושיה הראשונים קידושין נישאה לאחר, והיו להם צאצאים, \u0003ופרשו רבנן מינה\u0004 \u0005[\u0006והיו \u0005חכמים פורשים ממנה],\u0006 מאותה משפחה, מלהתחתן בה, שחששו משום ממזרות. ומעירים: \u0003ולאו\u0004 \u0005[ולא]\u0006 \u0003משום דסבירא להו\u0004 \u0005[שהם סבורים]\u0006 כדעת \u0003שמואל\u0004 שחוששים בכל דבר שמא הוא שווה פרוטה במקום אחר, \u0003אלא משום דסבירא להו\u0004 \u0005[שסבורים הם]\u0006 \u0003כאביי ורבא\u0004 האומרים: שכיון שהיו עדים במקום אחר — צריך היה לחשוש להם.","מסופר: \u0003ההוא גברא דאקדיש בשוטיתא דאסא בשוקא\u0004 \u0005[\u0006מעשה ב\u0005אדם אחד שקידש\u0006 אשה \u0005בענף הדס בשוק];\u0006 \u0003שלחה\u0004 לבעיה הזו \u0003רב אחא בר הונא לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב יוסף: כהאי גוונא מאי\u0004 \u0005[כגון זה מה\u0006 עושים\u0005]?\u0006 \u0003שלח ליה\u0004 \u0005[לו]\u0006 כתשובה: \u0003נגדיה\u0004 \u0005[הלקה אותו]\u0006 \u0003כ\u0004דרך שנהג בענין זה \u0003רב, ואצטריך גיטא\u0004 \u0005[והצרך גט]\u0006 לאשה זו \u0003כ\u0004דברי \u0003שמואל\u0004 שחוששים שמא שווה פרוטה במקום אחר.","ומבארים: ש\u0003רב מנגיד\u0004 \u0005[היה מלקה]\u0006 \u0003על\u0004 מי שהיה \u0003מקדש\u0004 אשה \u0003בשוקא\u0004 \u0005[בשוק]\u0006 שהוא דרך הפקרות וזלזול, \u0003ועל\u0004 מי שהיה \u0003מקדש\u0004 אשה \u0003בביאה\u0004 שמגונה הדבר שמעמיד עדים לבעילה, \u0003ועל\u0004 מי שהיה \u0003מקדש\u0004 אשה \u0003בלא שידוכי\u0004 \u0005[שידוך],\u0006 בלי שדיברו עם האשה קודם לכן, שכל אלה הם מדרכי פריצות.","\u0003ו\u0004כן היה מלקה \u0003על\u0004 מי \u0003דמבטיל גיטא\u0004 \u0005[ש\u0006היה \u0005מבטל גט]\u0006 ששלח לאשתו, ולאחר מכן היה מודיע שהוא בטל. \u0003ועל\u0004 זה \u0003דמסר מודעא אגיטא\u0004 \u0005[\u0006\u0005ש\u0006היה \u0005מוסר מודעה על גט],\u0006 שלפני שהיה נותן את הגט היה מוסר מודעה בפני עדים שהוא מגרשה שלא מרצונו, ומבטל איפוא את תוקפו של הגט. שעל ידי ביטול גט ומסירת מודעה על גט עלולה האשה להיכשל באיסור חמור, שתחשוב שהיא פנויה ותינשא לאחר בעוד שבאמת היא עדיין אשת איש. \u0003ו\u0004כן \u0003על\u0004 מי שהיה \u0003מצער שלוחא דרבנן\u0004 \u0005[שליח של חכמים],\u0006 שכל המבזה אותו הריהו כפוגע בכבוד החכמים עצמם, \u0003ועל\u0004 זה \u0003דחלה שמתא עילויה תלתין יומין\u0004 \u0005[\u0006\u0005שחל נידוי עליו שלושים יום]\u0006 ולא הלך לחכמים לבקש מחילה ולהתיר את הנידוי,","\u0003ועל חתנא דדייר בי חמוה\u0004 \u0005[חתן שגר בבית חמיו],\u0006 שיש לחשוש שמא ייכשל בעבירה בחמותו. ומעירים: זה \u0003דדייר\u0004 \u0005[שדר]\u0006 שם בקביעות — \u0003אין\u0004 \u0005[כן]\u0006 מלקים אותו, ואולם זה שרק \u0003חליף\u0004 \u0005[עובר]\u0006 ליד בית חמיו — \u0003לא?!\u0004 ושואלים: \u0003והא ההוא חתנא דחליף אבבא דבי חמוה\u0004 \u0005[והרי\u0006 מעשה היה ב\u0005חתן אחד שהיה עובר על פתח בית חמיו]\u0006 \u0003ונגדיה\u0004 \u0005[והלקה אותו]\u0006 \u0003רב ששת,\u0004 משום חשש זימה! ומשיבים: \u0003ההוא מידם הות דיימא חמתיה מיניה\u0004 \u0005[אותו\u0006 אדם \u0005חשודה היתה חמותו עליו]\u0006 שהיתה שמועה שיש ביניהם יחסי קירבה, וכשעובר על פתח הבית הרי הוא מחזק בכך את החשד, ומשום כך הלקה אותו.","\u0003נהרדעי אמרי\u0004 \u0005[\u0006חכמי \u0005נהרדעא אומרים]:\u0006 \u0003בכולהו\u0004 \u0005[בכולם],\u0006 בכל המקרים שהוזכרו \u0003לא\u0004 היה \u0003מנגיד\u0004 \u0005[מלקה]\u0006 \u0003רב אלא על\u0004 דבר אחד — מי ש\u0003מקדש\u0004 אשה \u0003בביאה בלא שידוכי\u0004 \u0005[שידוכים]\u0006 קודם לכן. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003ואפילו בשידוכי נמי\u0004 \u0005[בשידוכים גם כן]\u0006 היה מלקה את המקדש בביאה \u0003משום\u0004 שיש \u0003פריצותא\u0004 \u0005[פריצות]\u0006 בדבר, שמעמיד עדים לבעילתו.","מסופר: \u0003ההוא גברא דקדיש בציפתא דאסא\u0004 \u0005[אדם אחד שקידש\u0006 אשה \u0005במחצלת של הדסים],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003והא לית\u0004 \u0005[והרי אין]\u0006 \u0003בה שוה פרוטה! אמר להו\u0004 \u0005[להם]:\u0006 אם כן \u0003תיקדוש\u0004 \u0005[שתתקדש]\u0006 \u0003בארבע זוזי דאית\u0004 \u0005[דינרים שיש]\u0006 \u0003בה,\u0004 שהיו כרוכים בתוך המחצלת. \u0003שקלתא ואישתיקא\u0004 \u0005[לקחה\u0006 האשה את המחצלת \u0005ושתקה].\u0006 \u0003אמר רבא: הוה שתיקותא\u0004 \u0005[הרי זו שתיקה]\u0006 ש\u0003לאחר מתן מעות, וכל שתיקותא\u0004 \u0005[שתיקה]\u0006 ש\u0003לאחר מתן מעות, לאו\u0004 \u0005[לא]\u0006 \u0003כלום היא,\u0004 שכיון שבשעת מתן מעות לא היה בה שווה פרוטה אין הוכחה שהסכימה למה שאמר אחר כך, ויתכן שלא שמה לב לדבריו, ולא התכוונה להתקדש.","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה],\u0006 את סברתי זו — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר לה\u0004 לאשה: \u0003כנסי\u0004 (קחי) \u0003סלע זו בפקדון, וחזר ואמר לה: התקדשי לי בו.\u0004 אם אמר כן \u0003בשעת מתן מעות\u0004 — \u0003מקודשת,\u0004 ואם אמר כן \u0003לאחר מתן מעות,\u0004 אם \u0003רצתה\u0004 — \u0003מקודשת, לא רצתה\u0004 — \u0003אינה מקודשת.\u0004","ונברר תחילה: \u0003מאי\u0004 \u0005[מה]\u0006 משמעות \u0003\"רצתה\" ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"לא רצתה\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003\"רצתה\"\u0004 — ש\u0003אמרה אין\u0004 \u0005[כן],\u0006 שמוכנה להתקדש, ו\u0003\"לא רצתה\"\u0004 כוונתו ש\u0003אמרה\u0004 במפורש \u0003לא,\u0004 אם כן \u0003מכלל\u0004 הדברים תלמד \u0003דרישא\u0004 \u0005[שתחילת\u0006 הברייתא\u0005]\u0006 כשאמר לה בשעת מתן מעות, ולא חילקנו בין רצתה ולא רצתה,"],["\u0003כי אמרה\u0004 \u0005[כאשר\u0006 היא \u0005אומרת]\u0006 \u0003\"לא\" נמי הוו\u0004 \u0005[גם כן יהיו]\u0006 \u0003קידושין? אמאי\u0004 \u0005[מדוע],\u0006 \u0003והא קאמרה\u0004 \u0005[והרי\u0006 היא \u0005אומרת]\u0006 \u0003\"לא\"! אלא לאו\u0004 \u0005[אין]\u0006 לפרש אלא כך: \u0003\"רצתה\"\u0004 כוונתו — ש\u0003אמרה \"אין\"\u0004 \u0005[\"כן\"]\u0006 \u0003\"לא רצתה\"\u0004 כוונתו — \u0003דאישתיקה משתקה\u0004 \u0005[ששתקה].\u0006 \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 ש\u0003שתיקה\u0004 ש\u0003לאחר מתן מעות\u0004 — \u0003ולא כלום היא,\u0004 שאינה נחשבת כהסכמה של האשה להתקדש.","\u0003קשו\u0004 \u0005[היו מתקשים]\u0006 \u0003בה,\u0004 בראייתו זו של רבא, \u0003ב\u0004עיר \u0003פום נהרא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: מי דמי\u0004 \u0005[האם דומים]\u0006 הדברים? \u0003התם\u0004 \u0005[שם,\u0006 בברייתא\u0005]\u0006 \u0003בתורת פקדון יהבינהו ניהלה\u0004 \u0005[נתן אותם,\u0006 את המעות, \u0005לה]\u0006 והם שלו, ולכן \u0003סברה\u0004 \u0005[חושבת\u0006 היא\u0005]:\u0006 \u0003אי שדינא להו ומיתברי\u0004 \u0005[אם אזרוק אותם ויישברו]\u0006 — \u0003מחייבנא בהו\u0004 \u0005[אתחייב בהם\u0006 לשלמם\u0005]\u0006 כמאבד ממון חבירו, לכן אין בשתיקתה ראיה שמסכימה, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בתורת קדושין יהבינהו ניהלה\u0004 \u0005[נתן אותם לה]\u0006 מתחילה על מנת שיהיו שלה, \u0003ואי איתא דלא ניחא לה\u0004 \u0005[ואם יש\u0006 סברה \u0005שאינה רוצה\u0006 בכך\u0005]\u0006 — \u0003לישדינהו\u0004 \u0005[שתזרוק אותם].\u0006","\u0003פריך\u0004 \u0005[הקשה]\u0006 על כך \u0003רב אחאי: אטו כולהו נשי דינא גמירי\u0004 \u0005[האם כל הנשים למדו את הדין]?\u0006 \u0003הכי נמי סברה\u0004 \u0005[כאן גם כן חושבת\u0006 היא\u0005]:\u0006 \u0003אי שדינא להו ומיתברי מיתחייבנא באחריותייהו\u0004 \u0005[אם אזרוק אותם ויישברו אתחייב באחריותם]\u0006 ולכן לא זרקה אותם, אבל אין להסיק מהעובדה שלא זרקה את המעות שהסכימה לקבלם בתורת קידושין. \u0003שלחה\u0004 לבעיה זו \u0003רב אחא בר\u0004 \u0005[בנו]\u0006 של \u0003רב לקמיה\u0004 \u0005[לפני]\u0006 \u0003רבינא: כהאי גוונא מאי\u0004 \u0005[כגון זה מה\u0006 יהא הדין\u0005]?\u0006 \u0003שלח ליה\u0004 \u0005[לו]\u0006 בתשובה: \u0003אנן לא שמיע לן הא\u0004 \u0005[אנו לא שמענו,\u0006 לא קיבלנו, את \u0005זו\u0006 שאמר\u0005]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע, אתון דשמיע לכו\u0004 \u0005[אתם ששמעתם אותה]\u0006 — \u0003חושו\u0004 \u0005[תחששו]\u0006 \u0003לה\u0004 לספק קידושין.","מסופר: \u0003ההיא איתתא דהוה קא מזבנה וורשכי\u0004 \u0005[אשה אחת שהיתה מוכרת סרטים],\u0006 \u0003אתא ההוא גברא חטף וורשכא מינה\u0004 \u0005[בא אדם אחד\u0006 ו\u0005חטף סרט ממנה],\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003הבה ניהלי\u0004 \u0005[תן\u0006 אותו \u0005לי]\u0006 \u0003אמר לה: אי יהיבנא ליך מיקדשת\u0004 \u0005[אם אתן לך\u0006 אותו האם \u0005תתקדשי]\u0006 \u0003לי? שקלתיה ואישתיקה\u0004 \u0005[לקחה אותו ושתקה].\u0006 \u0003ואמר רב נחמן: יכולה\u0004 היא \u0003למימר\u0004 \u0005[לומר]:\u0006 \u0003אין, שקלי, ודידי שקלי\u0004 \u0005[כן,\u0006 אכן, \u0005לקחתי, ו\u0006אולם את \u0005שלי לקחתי]\u0006 ולא התכוונתי לקבל זאת בתורת קידושין.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו שאם \u0003קידשה בגזל\u0004 או \u0003בחמס,\u0004 כלומר, בדבר שקנה שלא מרצון המוכר, או \u0003בגניבה, או שחטף סלע מידה וקדשה\u0004 בו — \u0003מקודשת,\u0004 ומדוע אומר הוא כאן שכשחטף ממנה וקידשה שאינה מקודשת! ענה לו: \u0003התם בדשדיך\u0004 \u0005[שם\u0006 מדובר \u0005ב\u0006מקרה \u0005ששידך\u0006 קודם\u0005],\u0006 ולכן יש לומר שאם שתקה ודאי הסכימה לקידושין.","\u0003ומנא תימרא דשני לן בין שדיך ודלא שדיך\u0004 \u0005[ומנין תאמר ששונה לנו\u0006 הדין \u0005בין\u0006 מקרה \u0005ששידך לשלא שידך]\u0006 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר לה\u0004 לאשה \u0003\"כנסי\u0004 (קחי) \u0003סלע זו שאני חייב ליכי\u0004 (לך) \u0003\", וחזר ואמר לה \"התקדשי לי בו\";\u0004 אם היה זה \u0003בשעת מתן מעות, רצתה\u0004 — \u0003מקודשת, לא רצתה\u0004 — \u0003אינה מקודשת. לאחר מתן מעות אפילו רצתה\u0004 בקידושין \u0003אינה מקודשת.\u0004","ונברר: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"רצתה\", ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"לא רצתה\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003\"רצתה\"\u0004 כוונתו — ש\u0003אמרה \"אין\"\u0004 \u0005[\"כן\"]\u0006 ו\u0003\"לא רצתה\"\u0004 כוונתו — ש\u0003אמרה \"לא\",\u0004 ואם כן נסיק מכאן: \u0003הא אישתיקה\u0004 \u0005[הרי\u0006 אם \u0005שתקה]\u0006 — \u0003הוו\u0004 \u0005[הריהם]\u0006 \u0003קידושין. ו\u0004אולם אם כן \u0003נתני\u0004 \u0005[שישנה]\u0006 \u0003מקודשת סתם, כי התם\u0004 \u0005[כמו שם]\u0006 (דף יב,ב) באומר \"כנסי סלע זו בפקדון\" ולא יפרט.","\u0003אלא\u0004 מכיוון שהתנא מפרט, כך יש להבין: \u0003\"רצתה\"\u0004 — ש\u0003אמרה \"אין\"\u0004 \u0005[\"כן\"],\u0006 \u0003\"לא רצתה\" — דאישתיקה\u0004 \u0005[ששתקה],\u0006 \u0003וקא תני\u0004 \u0005[ו\u0006במקרה של שתיקה \u0005שנה]\u0006 ש\u0003אינה מקודשת.\u0004 ו\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 שאם שתקה אינה מקודשת? משום ש\u0003יכולה\u0004 היא \u0003למימר\u0004 \u0005[לומר]:\u0006 \u0003אין, שקלי ודידי שקלי\u0004 \u0005[כן, לקחתי ו\u0006אולם את \u0005שלי לקחתי]\u0006 ולא התכוונתי לקידושין.","\u0003ואלא קשיא הך\u0004 \u0005[קשה\u0006 הלכה \u0005זו]\u0006 ששנינו ש\u0003קדשה בגזל\u0004 או \u0003בחמס\u0004 או \u0003בגניבה או שחטף סלע מידה וקדשה\u0004 — \u0003מקודשת! אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שיש לחלק כמו שחילקתי: \u0003הא\u0004 \u0005[\u0006דין \u0005זה]\u0006 שמקודשת כששתקה — הרי זה מדובר באופן \u0003דשדיך\u0004 \u0005[ששידך]\u0006 תחילה \u0005[\u0006דין \u0005זה\u0006 שמקודשת כששתקה — \u0005כששידך]\u0006 תחילה, ואילו \u0003הא\u0004 \u0005[\u0006דין \u0005זה]\u0006 שאינה מקודשת כששתקה — הרי זה מדובר באופן ש\u0003לא שדיך\u0004 \u0005[שידך].\u0006","מסופר: \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רב אסי, עיילו רבנן לנקוטינהו לשמעתתיה\u0004 \u0005[נכנסו חכמים להחזיק את שמועותיו],\u0006 כלומר, לשוב ולחזור על השמועות שאמר, כדי שלא ישתכחו. \u0003אמר להו ההוא מרבנן\u0004 \u0005[אמר להם אחד החכמים]\u0006 \u0003ור' יעקב שמיה\u0004 \u0005[שמו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' אסי אמר ר' מני: כשם שאין אשה נקנית בפחות משוה פרוטה\u0004 — \u0003כך אין קרקע נקנית בפחות משוה פרוטה. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אף על פי שאין אשה נקנית בפחות משוה פרוטה\u0004 — \u0003קרקע נקנית בפחות משוה פרוטה!\u0004","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כי תניא ההיא\u0004 \u0005[כאשר נשנית אותה\u0006 ברייתא\u0005]\u0006 שקרקע ולא אשה נקנית בפחות משווה פרוטה — הרי זה \u0003ב\u0004קנין של \u0003חליפין. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003קו‍נין\u0004 קרקעות ומטלטלים בחליפין \u0003ב\u0004נתינת \u0003כלי, ואף על פי שאין בו שוה פרוטה.\u0004","\u0003הדר יתבי וקאמרי\u0004 \u0005[חזרו\u0006 לאחר מכן, \u0005ישבו ואמרו]\u0006 עוד שמועות בשם רב אסי, \u0003הא\u0004 \u0005[\u0006את \u0005זו]\u0006 ש\u0003אמר רב יהודה אמר שמואל: כל שאינו יודע בטיב גיטין וקדושין לא יהא לו עסק עמהן,\u0004 שיכול לגרום על ידי חוסר ידיעתו למכשולים רבים. \u0003אמר ר' אסי אמר ר' יוחנן: ו\u0004אלה המתעסקים בנושא זה בלי ידיעה \u0003קשין לעולם יותר מדור המבול, שנאמר: \"אלה וכחש ורצח וגנב ונאף פרצו ודמים בדמים נגעו\"\u0004 (הושע ד, ב).","ושואלים: \u0003מאי משמע\u0004 \u0005[מה משמעות\u0006 הכתוב\u0005],\u0006 כיצד הוא מתייחס לענין שדיברנו בו? ומשיבים: \u0003כדמתרגם\u0004 \u0005[כמו שמתרגם]\u0006 \u0003רב יוסף\u0004 את המילים \"ונאף פרצו ודמים בדמים נגעו\": \u0003מולדין בנין מנשי חבריהון חובין על חובין מוסיפין\u0004 \u0005[מולידים בנים מנשי חבריהם חטאים על חטאים מוסיפים],\u0006","\u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בהמשך הכתוב \u0003\"על כן תאבל הארץ ואמלל כל יושב בה בחית השדה ובעוף השמים וגם דגי הים יאספו\"\u0004 (שם ג), ללמדנו שאלה שחוטאים וגורמים להולדת ממזרים מביאים לאסון גדול כזה, עד שאף דגי הים מתים \u0003ואילו בדור המבול לא נגזרה גזירה על דגים שבים.\u0004 וראיה לדבר ממה \u0003שנאמר: \"מכל אשר בחרבה מתו\"\u0004 (בראשית ז, כב) ו\"בחרבה\" משמעו — ביבשה, ללמד \u0003ולא דגים שבים. ואילו הכא\u0004 \u0005[כאן]\u0006 \u0003אפילו דגים שבים.\u0004","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שלא נגזרה גזירה זו אלא \u0003עד דעביד לכולהו\u0004 \u0005[שיעשה את כולם],\u0006 כלומר, שבועת שקר, רצח, גניבה וכו'! ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כן, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"כי מפני אלה אבלה הארץ\"\u0004 (ירמיהו כג, י), לומר שבגלל שבועת שווא בלבד נהרסת הארץ, משמע שעל כל אחד ואחד מן הדברים האלה בא החורבן.","ועדיין מקשים: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003אלה לחוד,\u0004 שהיא חטא חמור שיש בו חילול השם, \u0003והנך לחודיהון\u0004 \u0005[ואלה לעצמם],\u0006 שעליהם אין בא עונש כבד כל כך אלא אם כן עשה את כולם כאחד"],["\u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"ופרצו\",\u0004 בו\"ו החיבור, לכלול את כל שאר העבירות כיחידה אחת? הלא \u0003\"פרצו\" כתיב\u0004 \u0005[נאמר],\u0006 לומר שעל כל אחת ואחת מעבירות אלה יש עונש זה.","\u0003הדור יתבי וקאמרי\u0004 \u0005[חזרו ישבו ואמרו]\u0006 עוד שמועות בשם רב אסי: \u0003הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003האשה\u0004 היולדת \u0003שהביאה\u0004 קרבן \u0003חטאתה\u0004 לטהרה מטומאת יולדת \u0003ומתה\u0004 — \u0003יביאו יורשין\u0004 קרבן \u0003עולתה,\u0004 להשלים את חובותיה בקרבנות. \u0003אמר רב יהודה אמר שמואל: ו\u0004דין זה \u0003הוא\u0004 דווקא כ\u0003ש\u0004כבר \u0003הפרישתה\u0004 האשה עצמה את העולה הזו \u0003מחיים\u0004 (בחייה). \u0003אבל\u0004 אם עדיין \u0003לא הפרישתה מחיים\u0004 — \u0003לא\u0004 חייבים היורשים להביא קרבן עולה.","ומסיקים: \u0003אלמא קסבר\u0004 \u0005[מכאן ש\u0006הוא \u0005סבור]\u0006 כי \u0003שיעבודא לאו דאורייתא\u0004 \u0005[שיעבוד\u0006 נכסים \u0005אינו מן התורה],\u0006 שאין אומרים שמכיון שהיתה עליה חובה להקריב גם עולה נשתעבדו לכך נכסיה, וחובה זו מוטלת איפוא על הנכסים אף לאחר מותה של האשה, גם אם לא הופרשה העולה על ידי האשה בפועל. ועל שיטה זו יש חולקים, \u0003אמר רב אסי אמר ר' יוחנן: אף על גב\u0004 \u0005[אף על פי]\u0006 \u0003שלא הפרישה\u0004 את העולה \u0003מחיים.\u0004 ומכאן מסיקים \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 שהוא \u0005סבור]:\u0006 \u0003שיעבודא הוה דאורייתא\u0004 \u0005[שיעבוד הוא מן התורה].\u0006","ותוהים: \u0003והא פליגי\u0004 \u0005[והרי\u0006 כבר \u0005נחלקו]\u0006 חכמים אלו \u0003בה,\u0004 בבעיה זו, \u0003חדא זימנא\u0004 \u0005[פעם אחת],\u0006 ש\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מלוה\u0004 \u0003על פה\u0004 שאין עימו שטר שיעבוד קרקעות, אם מת הלווה — \u0003אינה גובה\u0004 את החוב \u0003מן היורשין ולא מן הלקוחות,\u0004 אף שברור שהיה מלוה, ואין החייבים מכחישים זאת. \u0003ו\u0004\u0003ר' יוחנן וריש לקיש דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מלוה על פה גובה בין מן היורשין, בין מן הלקוחות.\u0004 משמע שנחלקו כבר אותם חכמים בשאלה האם השיעבוד עצמו, בלי שטר, הוא מן התורה או לא, ומדוע נשנית המחלוקת פעמיים?","ומשיבים: \u0003צריכא\u0004 \u0005[נצרך]\u0006 הדבר להיאמר בשני המקרים; \u0003דאי איתמר בהא\u0004 \u0005[שאילו\u0006 היה \u0005נאמר\u0006 רק \u0005בזו],\u0006 בענין הלוואה, היינו אומרים: \u0003בהך קאמר\u0004 \u0005[בזו\u0006 בלבד \u0005אומר]\u0006 \u0003שמואל\u0004 שאין כאן שיעבוד, \u0003משום\u0004 ש\u0003לא מלוה כתובה בתורה היא,\u0004 שהרי ההלוואה הזו לא היתה אלא הסכם פרטי בין שני אנשים, \u0003אבל בהך\u0004 \u0005[בההיא],\u0006 בענין חובת היולדת בקרבן עולה — \u0003אימא מודה להו\u0004 \u0005[אמור\u0006 ש\u0005מודה\u0006 הוא \u0005להם],\u0006 \u0003לר' יוחנן ולריש לקיש,\u0004 שכיון שהתחייבות זו שצריכה להביא עולה כתובה בתורה — יש לומר שהיא יוצרת שיעבוד אף שלא נכתבה בשטר.","ולהיפך, \u0003ואי אשמעינן בהא\u0004 \u0005[ואם\u0006 היה \u0005משמיע לנו\u0006 רק \u0005בזו],\u0006 בענין קרבן עולה של יולדת, היינו אומרים כי דווקא \u0003בהא קאמר\u0004 \u0005[בזו אומר]\u0006 \u0003ר' יוחנן\u0004 שהשיעבוד מן התורה, ומדוע — ש\u0003מלוה כתובה בתורה ככתובה בשטר דמיא\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 \u0003אבל בהך\u0004 \u0005[בזו],\u0006 במלוה פרטי — \u0003אימא מודה ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לשמואל\u0004 שאין השיעבוד מן התורה, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמר מחלוקתם בשני המקרים.","\u0003אמר רב פפא: הילכתא\u0004 \u0005[הלכה]\u0006 למעשה היא זו: \u0003מלוה על פה גובה מן היורשין, ואינו גובה מן הלקוחות\u0004 וטעמו של דבר: \u0003גובה מן היורשין\u0004 — משום שאנו מקבלים את השיטה ש\u0003שיעבודא דאורייתא\u0004 \u0005[שיעבוד\u0006 נכסים להלוואה הוא \u0005מן התורה],\u0006 \u0003ואינו גובה מן הלקוחות\u0004 — משום \u0003דלית ליה קלא\u0004 \u0005[שאין לו,\u0006 למלוה על פה \u0005קול],\u0006 שאינו מתפרסם ברבים ואין אנשים נזהרים מלקנות מנכסיו של הלווה ולכן אין לחייב את הלקוחות להתחשב בשיעבוד שלא היה ידוע לרבים.","שנינו במשנה שהאשה \u0003קונה את עצמה בגט ובמיתת הבעל.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003גט\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 בתורה במפורש \u0003\"וכתב לה ספר כריתת...\u0004 והלכה והיתה לאיש אחר\u0003\"\u0004 (דברים כד א–ב), משמע שהגט מתיר לאשה להינשא למי שתרצה לאחר הגירושין,","\u0003אלא מיתת הבעל מנלן\u0004 \u0005[מנין לנו]\u0006 שמתירה את האשה? ומשיבים: דבר זה \u0003סברא הוא: הוא,\u0004 הבעל, \u0003אסרה\u0004 לכל אדם \u0003והוא שרתה\u0004 \u0005[התיר אותה],\u0006 שכיון שאינו קיים עוד בעולם, אין מי שיאסרנה.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003עריות דאסר להו ולא שרי להו\u0004 \u0005[ש\u0006הוא \u0005אוסר אותן ואינו מתיר אותן\u0006 במיתתו\u0005],\u0006 כגון אשת האב שגם אחרי שמת האוסר — אין האשה הזו מותרת למי שנאסרה עליו בחייו! \u0003אלא\u0004 יש ללמוד זאת \u0003מדאמר רחמנא\u0004 \u0005[ממה שאמרה תורה]\u0006 ב\u0003יבמה\u0004 שמת בעלה \u0003שאין לה בנים\u0004 ש\u0003אסורה\u0004 להינשא לכל אדם מלבד ליבם, ונסיק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 זו ש\u0003יש לה בנים\u0004 — \u0003מותרת\u0004 להינשא.","ומקשים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 נפרש אחרת: אשה ש\u0003אין לה בנים\u0004 — \u0003אסורה לעלמא\u0004 \u0005[לכל]\u0006 \u0003ושריא\u0004 \u0005[ומותרת]\u0006 \u0003ליבם, ו\u0004זו ש\u0003יש לה בנים\u0004 — \u0003לכולי עלמא נמי\u0004 \u0005[לכל העולם,\u0006 לכל האחרים, \u0005גם כן]\u0006 \u0003אסורה! אלא,\u0004 יש ללמוד זאת \u0003מדאמר רחמנא\u0004 \u0005[ממה שאמרה התורה]\u0006 \u0003אלמנה לכהן גדול אסורה,\u0004 ומכאן נבין: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לכהן הדיוט\u0004 היא \u0003שריא\u0004 \u0005[מותרת]\u0006 וכל שכן לישראל.","ומקשים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 נאמר כי \u0003לכהן גדול\u0004 אסורה היא \u0003בלאו\u0004 \u0005[ב\u0006איסור \u0005לא\u0006 תעשה\u0005]\u0006 ואילו \u0003לכולי עלמא\u0004 \u0005[לכל העולם]\u0006 אסורה היא רק \u0003בעשה.\u0004 על כך תוהים: \u0003האי עשה מאי עבידתיה\u0004 \u0005[עשה זה מה מעשיו,\u0006 מה טעמו\u0005]?\u0006 \u0003אי דאהניא\u0004 \u0005[אם שהועילה]\u0006 \u0003מיתת הבעל\u0004 להתירה \u0003תישתרי\u0004 \u0005[\u0006ש\u0005תותר]\u0006 \u0003לגמרי, אי\u0004 \u0005[אם]\u0006 ש\u0003לא אהניא\u0004 \u0005[הועילה]\u0006 \u0003מיתת הבעל\u0004 להתירה \u0003תוקמה במילתא קמייתא\u0004 \u0005[\u0006ש\u0005תישאר בעניינה הראשון]\u0006 בחיי בעלה ויהיה בה איסור מיתת בית דין!","ומשיבים: אין זו קושיה, \u0003אלמה\u0004 \u0005[\u0006ו\u0005מדוע]\u0006 \u0003לא?\u0004 אפשר לומר שמיתת הבעל \u0003אפיקתה\u0004 \u0005[הוציאה אותה]\u0006 \u0003מ\u0004איסור \u0003מיתה ואוקימתה\u0004 \u0005[והעמידה אותה]\u0006 \u0003על\u0004 איסור \u0003עשה, מידי דהוה אפסולי\u0004 \u0005[כמו שהוא על פסולי]\u0006 \u0003המוקדשים,\u0004 בהמות שהוקדשו לקרבן ונפסלו מחמת מום,","\u0003דמעיקרא\u0004 \u0005[שמתחילה]\u0006 כשהיו תמימים \u0003אית בהו\u0004 \u0005[יש בהם]\u0006 \u0003מעילה,\u0004 ואם נהנה מהם — הרי זה מועל בקדשים ומתחייב על כך, \u0003ואסירי\u0004 \u0005[ואסורים]\u0006 \u0003בגיזה\u0004 (של צמרם) \u0003ועבודה\u0004 בהם. ולאחר שנפל בהם מום, כאשר \u0003פרקינהו\u0004 \u0005[פדה אותם]\u0006 — דין \u0003מעילה לית בהו\u0004 \u0005[אין בהם],\u0006 אבל עדיין \u0003בגיזה ועבודה\u0004 הם \u0003אסירי\u0004 \u0005[אסורים]\u0006 וכך אפשר לומר גם לגבי מיתת הבעל שאין היא מתירה לגמרי את האשה, ועדיין לא מצאנו מקור להתירה לנישואין.","\u0003אלא\u0004 יש לומר שהמקור להיתר באלמנה \u0003מדאמר קרא\u0004 \u0005[ממה שאמר הכתוב]\u0006 \u0003\"פן ימות במלחמה ואיש אחר יקחנה\"\u0004 (דברים כ, ז) ומכאן למדים שיכול אדם אחר לשאת את האלמנה. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: אימא\u0004 \u0005[אמור]\u0006 ותפרש שם: \u0003מאן\u0004 \u0005[מיהו]\u0006 אותו איש \u0003אחר\u0004 זה שנזכר בכתוב — \u0003יבם.\u0004","\u0003אמר רב אשי שתי תשובות בדבר: חדא\u0004 \u0005[אחת]\u0006 — ש\u0003יבם לא איקרי\u0004 \u0005[נקרא]\u0006 \u0003אחר\u0004 שאינו איש זר לה. \u0003ועוד כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ושנאה האיש האחרון וכתב לה ספר כריתת... או כי ימות האיש האחרון\"\u0004 (שם כד, ג) \u0003ואיתקש\u0004 \u0005[והוקש]\u0006 בכתוב זה דין \u0003מיתה לגירושין, מה גירושין שריא\u0004 \u0005[מתיר]\u0006 את האשה לכל, \u0003וגומרת,\u0004 כלומר, משלימה את הפירוד ואין עליה שום איסור להינשא לאחר, \u0003אף מיתה שריא\u0004 \u0005[מתירה]\u0006 \u0003וגומרת\u0004 ומשלימה את ההיתר הזה להינשא לכל אדם.","שנינו במשנה ש\u0003היבמה נקנית בביאה כו'.\u0004 ושואלים: \u0003בביאה מנלן\u0004 \u0005[מניין לנו]\u0006 שהיא נקנית? — \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006"]]};
